--
-- TOC entry 815 (class 1255 OID 55192)
-- Name: accept_pass_it_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_pass_it_invitation(p_invitation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_invitation_record pass_it_invitations;
    v_campaign_record pass_it_campaigns;
    v_chain_record pass_it_chains;
    v_new_pass_id UUID;
    v_reward_amount NUMERIC := 0;
    v_reward_given BOOLEAN := FALSE;
    v_user_id UUID := auth.uid();
BEGIN
    -- 1. Validate and fetch invitation details
    SELECT * INTO v_invitation_record
    FROM pass_it_invitations
    WHERE id = p_invitation_id AND invitee_id = v_user_id AND status = 'pending';

    IF v_invitation_record IS NULL THEN
        RAISE EXCEPTION 'Invitation not found, already accepted/declined, or not for this user.';
    END IF;

    -- 2. Fetch campaign details
    SELECT * INTO v_campaign_record
    FROM pass_it_campaigns
    WHERE id = v_invitation_record.campaign_id;

    IF v_campaign_record IS NULL THEN
        RAISE EXCEPTION 'Campaign not found for this invitation.';
    END IF;

    -- 3. Update invitation status
    UPDATE pass_it_invitations
    SET
        status = 'accepted',
        responded_at = NOW()
    WHERE id = p_invitation_id
    RETURNING * INTO v_invitation_record; -- Get updated record

    -- 4. Create or update chain and pass_it_pass entry
    IF v_campaign_record.campaign_type = 'public' THEN
        -- For public campaigns, if the user is accepting an invitation,
        -- it means they are starting a new chain.
        -- Check if a chain already exists for this user in this campaign (due to unique_campaign_invitee)
        SELECT * INTO v_chain_record
        FROM pass_it_chains
        WHERE campaign_id = v_campaign_record.id AND starter_influencer_id = v_user_id;

        IF v_chain_record IS NULL THEN
            -- Create a new chain for the user
            VALUES (v_campaign_record.id, v_user_id, 'active')
            RETURNING * INTO v_chain_record;
        END IF;

        -- Create the first pass in this new chain
            chain_id,
            campaign_id,
            reviewer_id,
            tagged_by_id, -- The inviter_id from the invitation is the one who tagged them
            position_in_chain,
            status
        ) VALUES (
            v_chain_record.id,
            v_campaign_record.id,
            v_user_id,
            v_invitation_record.inviter_id,
            1, -- First pass in the chain
            'pending' -- Status is pending until review is submitted
        ) RETURNING id INTO v_new_pass_id;

    ELSIF v_campaign_record.campaign_type = 'invitational' THEN
        -- For invitational campaigns, the chain already exists.
        -- Create a pass for the invitee in the existing chain.
            chain_id,
            campaign_id,
            reviewer_id,
            tagged_by_id, -- The inviter_id from the invitation is the one who tagged them
            position_in_chain,
            status
        ) VALUES (
            v_invitation_record.chain_id,
            v_campaign_record.id,
            v_user_id,
            v_invitation_record.inviter_id,
            v_invitation_record.position_in_chain,
            'pending' -- Status is pending until review is submitted
        ) RETURNING id INTO v_new_pass_id;
    END IF;

    -- 5. Handle rewards for accepting invitation (if any)
    -- This is a placeholder. Integrate with your existing reward system.
    -- For now, let's assume a small reward for accepting an invitation.
    -- This could be configured per campaign or be a fixed value.
    -- For simplicity, let's say 5 coins for accepting an invitation.
    v_reward_amount := 5; -- Example reward
    IF v_reward_amount > 0 THEN
        -- Call your existing function to give reward
        -- SELECT give_reward_to_user(v_user_id, v_reward_amount, 'pass_it_invitation_accepted') INTO v_reward_given;
        -- For now, just set v_reward_given to true
        v_reward_given := TRUE;
    END IF;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'message', 'Invitation accepted and pass created.',
        'invitation_id', v_invitation_record.id,
        'campaign_id', v_campaign_record.id,
        'new_pass_id', v_new_pass_id,
        'reward_given', v_reward_given,
        'reward_amount', v_reward_amount
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN JSONB_BUILD_OBJECT(
            'success', FALSE,
            'message', SQLERRM
        );
END;
$$;


--
-- TOC entry 665 (class 1255 OID 38846)
-- Name: analyze_gamification_profitability(timestamp with time zone, timestamp with time zone, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analyze_gamification_profitability(start_date timestamp with time zone, end_date timestamp with time zone, transaction_fee_rate numeric, reward_for_status numeric, reward_for_survey numeric, reward_for_challenge numeric) RETURNS TABLE(total_revenue numeric, total_cost numeric, net_profit numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_revenue DECIMAL := 0;
    v_total_cost DECIMAL := 0;
    v_status_posts_count INT;
    v_surveys_count INT;
    v_challenges_count INT;
BEGIN
    -- Calculate total revenue from transaction fees
    SELECT COALESCE(SUM(amount * transaction_fee_rate), 0)
    INTO v_total_revenue
    FROM public.transactions
    WHERE type IN ('cashout_approved', 'transfer_coins')
      AND created_at BETWEEN start_date AND end_date;

    -- Count activities within the period (using 'timestamp' for activity_logs)
    SELECT COUNT(*) INTO v_status_posts_count
    FROM public.activity_logs
    WHERE action_type = 'create_status_post'
      AND timestamp BETWEEN start_date AND end_date;

    SELECT COUNT(*) INTO v_surveys_count
    FROM public.activity_logs
    WHERE action_type = 'create_survey'
      AND timestamp BETWEEN start_date AND end_date;

    SELECT COUNT(*) INTO v_challenges_count
    FROM public.activity_logs
    WHERE action_type = 'create_challenge'
      AND timestamp BETWEEN start_date AND end_date;

    -- Calculate total cost of rewards
    v_total_cost := (v_status_posts_count * reward_for_status)
                 + (v_surveys_count * reward_for_survey)
                 + (v_challenges_count * reward_for_challenge);

    -- Return profitability metrics
    RETURN QUERY
    SELECT v_total_revenue, v_total_cost, (v_total_revenue - v_total_cost);
END;
$$;


--
-- TOC entry 728 (class 1255 OID 31096)
-- Name: approve_cashout(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_cashout(transaction_id_to_approve uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  transaction_to_approve public.transactions;
  v_push_token TEXT;
  v_payload jsonb;
BEGIN
  IF (get_my_claim('user_type'))::text != 'agent' THEN
    RAISE EXCEPTION 'Only agents can approve cashouts';
  END IF;

  UPDATE public.transactions
  SET status = 'completed'
  WHERE id = transaction_id_to_approve
  RETURNING * INTO transaction_to_approve;

  -- Call the new function to distribute profit to investors
  PERFORM public.distribute_cashout_profit(transaction_to_approve.id);

  -- Send push notification
  SELECT push_token INTO v_push_token
  FROM public.profiles
  WHERE id = transaction_to_approve.user_id;

  IF v_push_token IS NOT NULL THEN
    v_payload := jsonb_build_object(
      'to', v_push_token,
      'title', 'Cashout Approved!',
      'body', 'Your cashout request for ' || transaction_to_approve.amount || ' coins has been approved and is being processed.'
    );

    PERFORM net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      body := v_payload,
      headers := '{"Content-Type": "application/json"}'::jsonb
    );
  END IF;
END;
$$;


--
-- TOC entry 504 (class 1255 OID 219498)
-- Name: approve_challenge_submission(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_challenge_submission(p_submission_id uuid, p_brand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$DECLARE
  v_submission public.challenge_submissions;
  v_challenge public.challenges;
  v_status_post public.status_posts;
  v_influencer_profile public.profiles;
  v_reward_amount DECIMAL(10, 2);
  v_payload JSONB;
  v_hub_owner_id UUID;
  v_curation_fee DECIMAL(10, 2) := 0;
  v_total_deduction DECIMAL(10, 2);
  v_is_hub_targeted BOOLEAN;
BEGIN
  -- 1. Fetch submission with ownership verification
  SELECT cs.* INTO v_submission
  FROM public.challenge_submissions cs
  JOIN public.challenges c ON cs.challenge_id = c.id
  JOIN public.status_posts sp ON c.status_post_id = sp.id
  WHERE cs.id = p_submission_id AND sp.brand_id = p_brand_id;

  IF v_submission.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Submission not found or does not belong to this brand.');
  END IF;

  IF v_submission.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Submission is not in pending status.');
  END IF;

  IF v_submission.reward_given = TRUE THEN
    RETURN jsonb_build_object('success', false, 'message', 'Reward already given for this submission.');
  END IF;

  -- 2. Fetch related records and lock for update
  SELECT c.* INTO v_challenge FROM public.challenges c WHERE c.id = v_submission.challenge_id;
  SELECT sp.* INTO v_status_post FROM public.status_posts sp WHERE sp.id = v_challenge.status_post_id FOR UPDATE;
  SELECT * INTO v_influencer_profile FROM public.profiles WHERE id = v_submission.participant_id FOR UPDATE;

  -- 3. Determine reward amount based on campaign type
  IF v_status_post.is_private THEN
    -- Try manual invite first
    SELECT invite_cost INTO v_reward_amount
    FROM public.private_campaign_invites
    WHERE status_post_id = v_status_post.id AND influencer_id = v_influencer_profile.id;

    -- If no manual invite, check hub membership
    IF v_reward_amount IS NULL OR v_reward_amount <= 0 THEN
      IF EXISTS (
        SELECT 1 FROM public.status_post_hubs sph
        JOIN public.hub_members hm ON hm.hub_id = sph.hub_id
        WHERE sph.status_post_id = v_status_post.id AND hm.profile_id = v_influencer_profile.id
      ) THEN
        v_reward_amount := v_status_post.reward_amount;
      ELSE
        RAISE EXCEPTION 'Influencer % has no access to private campaign % (No invite or hub membership)', v_influencer_profile.id, v_status_post.id;
      END IF;
    END IF;

  ELSE -- Public/collaborative challenges
    v_reward_amount := v_status_post.reward_amount;
  END IF;

  -- 4. Check for hub curation fee (10%)
  SELECT h.owner_id INTO v_hub_owner_id
  FROM public.status_post_hubs sph
  JOIN public.hubs h ON h.id = sph.hub_id
  JOIN public.hub_members hm ON hm.hub_id = h.id
  WHERE sph.status_post_id = v_status_post.id 
  AND hm.profile_id = v_influencer_profile.id
  LIMIT 1;

  IF v_hub_owner_id IS NOT NULL AND v_hub_owner_id != v_influencer_profile.id THEN
    v_curation_fee := v_reward_amount * 0.1;
  END IF;

  v_total_deduction := v_reward_amount + v_curation_fee;

  -- 5. Budget Check
  IF v_status_post.reserved_funds < v_total_deduction THEN
    RAISE EXCEPTION 'Insufficient reserved funds. Reserved: %, required: %', v_status_post.reserved_funds, v_total_deduction;
  END IF;

  -- 6. Update Submission Status
  UPDATE public.challenge_submissions
  SET status = 'approved',
      reward_given = TRUE,
      reviewed_at = NOW()
  WHERE id = p_submission_id;

  -- 7. Update status_post
  UPDATE public.status_posts
  SET current_rewards_given = COALESCE(current_rewards_given, 0) + 1,
      reserved_funds = GREATEST(0, reserved_funds - v_total_deduction)
  WHERE id = v_status_post.id;

  -- 8. Record brand escrow release transaction
  VALUES (
    p_brand_id,
    'released_from_escrow',
    -v_total_deduction,
    'Coins released from escrow for challenge reward (including curation fee): ' || v_status_post.title,
    p_submission_id,
    'challenge_reward_release'
  );

  -- 9. Pay Influencer
  UPDATE public.profiles
  SET brandible_coins = brandible_coins + v_reward_amount,
      total_earned = total_earned + v_reward_amount
  WHERE id = v_influencer_profile.id;

  VALUES (v_influencer_profile.id, v_reward_amount, 'earned', 'Reward for: ' || v_status_post.title, v_submission.id, 'challenge_reward');

  -- 10. Pay Hub Owner (10% Curation)
  IF v_curation_fee > 0 THEN
    UPDATE public.profiles 
    SET brandible_coins = brandible_coins + v_curation_fee,
        total_earned = total_earned + v_curation_fee
    WHERE id = v_hub_owner_id;

    VALUES (v_hub_owner_id, v_curation_fee, 'earned', 'Hub curation fee: ' || v_status_post.title, v_submission.id, 'hub_curation_fee');
  END IF;

  -- 11. Send Push Notification
  IF v_influencer_profile.push_token IS NOT NULL THEN
    v_payload := jsonb_build_object(
      'to', v_influencer_profile.push_token,
      'title', 'Challenge Approved! 🎉',
      'body', 'Your submission for "' || v_status_post.title || '" was approved! ' || v_reward_amount || ' coins earned.',
      'data', jsonb_build_object('type', 'challenge_approval', 'submission_id', p_submission_id)
    );

    PERFORM net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      body := v_payload,
      headers := '{"Content-Type": "application/json"}'::jsonb
    );
  END IF;

  -- 12. Return result
  RETURN jsonb_build_object(
    'success', true,
    'message', 'Submission approved and rewards distributed.',
    'reward_amount', v_reward_amount,
    'curation_fee', v_curation_fee,
    'total_deducted', v_total_deduction
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;$$;


--
-- TOC entry 555 (class 1255 OID 31704)
-- Name: approve_collaborative_submission(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_collaborative_submission(p_group_id uuid, p_brand_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_group             RECORD;
  v_challenge         RECORD;
  v_status_post       RECORD;
  v_submission        RECORD;
  v_participant_count INTEGER;
  v_reward_per_person NUMERIC(12,2);
  v_total_reward      NUMERIC(12,2);
  v_brand_coins       NUMERIC(12,2);
BEGIN
  -- Get collaboration group details
  SELECT * INTO v_group
  FROM collaboration_groups
  WHERE id = p_group_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Collaboration group not found');
  END IF;

  -- Get challenge and status post details
  SELECT * INTO v_challenge
  FROM challenges
  WHERE id = v_group.challenge_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Challenge not found for group');
  END IF;

  SELECT * INTO v_status_post
  FROM status_posts
  WHERE id = v_challenge.status_post_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Status post not found for challenge');
  END IF;

  -- Verify brand ownership
  IF v_status_post.brand_id IS DISTINCT FROM p_brand_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized: Not your challenge');
  END IF;

  -- Check if already approved
  IF EXISTS (
    SELECT 1 FROM challenge_submissions
    WHERE group_id = p_group_id AND status = 'approved'
  ) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Collaboration already approved');
  END IF;

  -- Count participants
  SELECT COUNT(*)::integer INTO v_participant_count
  FROM challenge_submissions
  WHERE group_id = p_group_id;

  IF v_participant_count IS NULL OR v_participant_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'No participants to reward');
  END IF;

  -- Calculate rewards
  v_total_reward := v_status_post.reward_amount;
  IF v_total_reward IS NULL OR v_total_reward <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Invalid reward amount on status post');
  END IF;

  v_reward_per_person := ROUND(v_total_reward / v_participant_count, 2);

  -- Check brand balance and lock the row
  SELECT brandible_coins INTO v_brand_coins
  FROM profiles
  WHERE id = p_brand_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Brand profile not found');
  END IF;

  IF v_brand_coins < v_total_reward THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient coin balance');
  END IF;

  -- Approve all submissions
  UPDATE challenge_submissions
  SET status = 'approved', reviewed_at = NOW()
  WHERE group_id = p_group_id;

  -- Update collaboration group
  UPDATE collaboration_groups
  SET status = 'approved', updated_at = NOW()
  WHERE id = p_group_id;

  -- Reward each participant
  FOR v_submission IN
    SELECT id, participant_id FROM challenge_submissions WHERE group_id = p_group_id
  LOOP
    UPDATE profiles
    SET brandible_coins = COALESCE(brandible_coins,0) + v_reward_per_person
    WHERE id = v_submission.participant_id;

      user_id,
      type,
      amount,
      description,
      reference_id,
      reference_type,
      created_at
    ) VALUES (
      v_submission.participant_id,
      'reward',
      v_reward_per_person,
      'Collaborative challenge reward: ' || COALESCE(v_status_post.title,''),
      v_submission.id,
      'challenge_submission',
      NOW()
    );
  END LOOP;

  -- Deduct brand coins
  UPDATE profiles
  SET brandible_coins = COALESCE(brandible_coins,0) - v_total_reward
  WHERE id = p_brand_id;

  -- Record brand transaction
    user_id,
    type,
    amount,
    description,
    reference_id,
    reference_type,
    created_at
  ) VALUES (
    p_brand_id,
    'challenge_reward',
    -v_total_reward,
    'Collaborative challenge reward payment: ' || COALESCE(v_status_post.title,''),
    p_group_id,
    'collaboration_group',
    NOW()
  );

  -- Update status post rewards count
  UPDATE status_posts
  SET current_rewards_given = COALESCE(current_rewards_given,0) + 1
  WHERE id = v_challenge.status_post_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Collaboration approved successfully! All participants rewarded.',
    'participants_rewarded', v_participant_count,
    'reward_per_person', v_reward_per_person
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Unexpected error: ' || SQLERRM
    );
END;
$$;


--
-- TOC entry 580 (class 1255 OID 202368)
-- Name: approve_unboxed_submission(uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_unboxed_submission(p_submission_id uuid, p_reward_per_sale numeric, p_escrow_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_submission RECORD;
    v_brand_profile_id UUID;
    v_brand_balance DECIMAL;
BEGIN
    IF p_reward_per_sale IS NULL OR p_reward_per_sale <= 0 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Reward per sale must be a positive amount');
    END IF;
    
    IF p_escrow_amount IS NULL OR p_escrow_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Escrow amount must be a positive amount');
    END IF;

    SELECT * INTO v_submission FROM public.unboxed_submissions WHERE id = p_submission_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Submission not found');
    END IF;

    IF v_submission.status = 'approved' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Submission is already approved');
    END IF;

    -- ✅ GET BRAND'S PROFILE_ID FIRST
    SELECT profile_id INTO v_brand_profile_id
    FROM public.brands
    WHERE id = v_submission.brand_id;
    
    IF v_brand_profile_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Brand not found');
    END IF;

    -- ✅ USE BRAND'S PROFILE_ID TO GET BALANCE
    SELECT brandible_coins INTO v_brand_balance 
    FROM public.profiles 
    WHERE id = v_brand_profile_id
    FOR UPDATE;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Brand profile not found');
    END IF;
    
    IF v_brand_balance < p_escrow_amount THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient coins for escrow');
    END IF;

    -- ✅ UPDATE USING BRAND'S PROFILE_ID
    UPDATE public.profiles 
    SET brandible_coins = brandible_coins - p_escrow_amount,
        updated_at = NOW()
    WHERE id = v_brand_profile_id;

    VALUES (v_brand_profile_id, 'spent', -p_escrow_amount, 
            'Escrow for unboxed referral: ' || p_submission_id::TEXT, p_submission_id, 'unboxed_escrow');

    UPDATE public.unboxed_submissions
    SET status = 'approved',
        referral_reward = p_reward_per_sale,
        reserved_budget = p_escrow_amount,
        updated_at = NOW()
    WHERE id = p_submission_id;

    VALUES (
        v_submission.influencer_id,
        'unbox_approved',
        'Unbox Approved! 🎉',
        'Your unboxing video has been approved. You will now earn ' || p_reward_per_sale || ' BC for every sale generated!',
        p_submission_id,
        'unboxed_submission',
        jsonb_build_object('submission_id', p_submission_id)
    );

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Submission approved and budget escrowed.',
        'reserved_budget', p_escrow_amount,
        'reward_per_sale', p_reward_per_sale
    );
END;
$$;


--
-- TOC entry 651 (class 1255 OID 196291)
-- Name: award_coins_for_game(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_coins_for_game(p_user_id uuid, p_amount numeric, p_game_name text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_new_total_coins DECIMAL;
BEGIN

  UPDATE public.profiles
  SET game_coins = game_coins + p_amount,
      brandible_coins = brandible_coins + p_amount
  WHERE id = p_user_id;

    user_id,
    type,
    amount,
    description,
    reference_type
  ) VALUES (
    p_user_id,
    'earned',
    p_amount,
    'Level completion reward from ' || p_game_name,
    'game_win'
  );

  SELECT brandible_coins
  INTO v_new_total_coins
  FROM public.profiles
  WHERE id = p_user_id;

  RETURN json_build_object(
    'success', true,
    'message', 'You earned ' || p_amount || ' coins!',
    'new_balance', v_new_total_coins
  );

END;
$$;


--
-- TOC entry 520 (class 1255 OID 202373)
-- Name: can_record_unboxed_sale(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_record_unboxed_sale(p_submission_id uuid) RETURNS TABLE(can_record boolean, reason text, current_status text, remaining_budget numeric, reward_per_sale numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        (us.status = 'approved' AND us.reserved_budget >= us.referral_reward)::BOOLEAN,
        CASE 
            WHEN us.status != 'approved' THEN 'Submission status is not approved'
            WHEN us.reserved_budget < us.referral_reward THEN 'Insufficient budget for reward'
            ELSE 'Ready to record sale'
        END,
        us.status,
        us.reserved_budget,
        us.referral_reward
    FROM public.unboxed_submissions us
    WHERE us.id = p_submission_id;
END;
$$;


--
-- TOC entry 783 (class 1255 OID 97594)
-- Name: check_account_name_similarity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_account_name_similarity(p_user_id uuid, p_bank_account_id uuid) RETURNS TABLE(is_similar boolean, similarity_score numeric, user_full_name text, account_name text, message text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_full_name TEXT;
  v_account_name TEXT;
  v_similarity_score NUMERIC;
  v_threshold NUMERIC;
BEGIN
  -- Get the user's full name from profiles table
  SELECT p.full_name INTO v_user_full_name
  FROM profiles p
  WHERE p.id = p_user_id;
  
  -- Get the account name from user_bank_accounts table
  SELECT uba.account_name INTO v_account_name
  FROM user_bank_accounts uba
  WHERE uba.id = p_bank_account_id AND uba.user_id = p_user_id;
  
  -- Get the similarity threshold from app_settings
  SELECT (value::json->>'value')::NUMERIC INTO v_threshold
  FROM app_settings
  WHERE key = 'cashout_name_similarity_threshold';
  
  -- Default threshold if not set
  IF v_threshold IS NULL THEN
    v_threshold := 0.6;
  END IF;
  
  -- Check if names exist
  IF v_user_full_name IS NULL OR v_account_name IS NULL THEN
    RETURN QUERY
    SELECT 
      false AS is_similar,
      0.0 AS similarity_score,
      v_user_full_name,
      v_account_name,
      'Could not retrieve name information. Please try again.' AS message;
    RETURN;
  END IF;
  
  -- Calculate similarity using pg_trgm
  v_similarity_score := similarity(v_user_full_name, v_account_name);
  
  -- Return results
  RETURN QUERY
  SELECT 
    v_similarity_score >= v_threshold AS is_similar,
    ROUND(v_similarity_score::NUMERIC, 3) AS similarity_score,
    v_user_full_name,
    v_account_name,
    CASE 
      WHEN v_similarity_score >= v_threshold THEN 'Name verification passed'
      ELSE 'Account name does not closely match your registered name. Please use a bank account registered in your name.'
    END AS message;
END;
$$;


--
-- TOC entry 685 (class 1255 OID 41257)
-- Name: check_exploration_and_generosity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_exploration_and_generosity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid := NEW.user_id;
  v_user_type TEXT;
  cnt_media int;
  cnt_features int;
  total_given numeric;
BEGIN
  -- FIX: Only run this logic for users of type 'brand'
  SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_user_id;
  IF v_user_type != 'brand' THEN
    RETURN NEW;
  END IF;

  -- Media enthusiast
  IF NEW.action_type IN ('media_selected','media_upload_attempt','media_upload_success') THEN
    SELECT COUNT(*) INTO cnt_media FROM public.activity_logs
    WHERE user_id = v_user_id
      AND action_type IN ('media_selected','media_upload_attempt','media_upload_success');

    IF cnt_media >= 10 THEN
      PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'media_enthusiast', NEW.id);
    END IF;
  END IF;

  -- Feature explorer
  IF NEW.action_type = 'screen_view' THEN
    SELECT COUNT(DISTINCT (metadata->>'screen_name')) INTO cnt_features
    FROM public.activity_logs
    WHERE user_id = v_user_id
      AND action_type = 'screen_view'
      AND metadata ? 'screen_name';

    IF cnt_features >= 3 THEN
      PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'feature_explorer', NEW.id);
    END IF;
  END IF;

  -- Generosity tracking
  SELECT COALESCE(SUM(ABS(amount)),0) INTO total_given FROM public.transactions
  WHERE user_id = v_user_id
    AND amount < 0
    AND type IN ('reward_payout','status_reward','payout','disbursement','campaign_funding', 'spent', 'released_from_escrow', 'challenge_reward', 'purchased' );

  IF total_given >= 1000 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'generous_brand', NEW.id);
  END IF;
  IF total_given >= 5000 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'big_spender', NEW.id);
  END IF;
  IF total_given >= 10000 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'mega_patron', NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 706 (class 1255 OID 41249)
-- Name: check_login_streaks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_login_streaks() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid := NEW.user_id;
  v_user_type TEXT;
  v_streak int := 0;
  v_day date;
  v_found boolean;
  thresholds int[] := ARRAY[3,7,14,30,60,100];
  t int;
BEGIN
  -- FIX: Only run this logic for users of type 'brand'
  SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_user_id;
  IF v_user_type != 'brand' THEN
    RETURN NEW;
  END IF;

  IF NEW.action_type IS DISTINCT FROM 'login' THEN
    RETURN NEW;
  END IF;

  v_day := (NEW.timestamp AT TIME ZONE 'UTC')::date;

  LOOP
    SELECT EXISTS (
      SELECT 1 FROM public.activity_logs al
      WHERE al.user_id = v_user_id
        AND al.action_type = 'login'
        AND (al.timestamp AT TIME ZONE 'UTC')::date = v_day
    ) INTO v_found;

    IF v_found THEN
      v_streak := v_streak + 1;
      v_day := v_day - INTERVAL '1 day';
    ELSE
      EXIT;
    END IF;
  END LOOP;

  FOREACH t IN ARRAY thresholds LOOP
    IF v_streak >= t THEN
      PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 
        CASE t
          WHEN 3 THEN 'day_3_streak'
          WHEN 7 THEN 'week_streak'
          WHEN 14 THEN 'fortnight_streak'
          WHEN 30 THEN 'month_streak'
          WHEN 60 THEN 'quarter_streak'
          WHEN 100 THEN 'hundred_day_legend'
        END,
        NEW.id
      );
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- TOC entry 551 (class 1255 OID 41259)
-- Name: check_milestone_achievements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_milestone_achievements() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid := NEW.user_id;
  v_user_type TEXT;
  total_actions int;
BEGIN
  -- FIX: Only run this logic for users of type 'brand'
  SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_user_id;
  IF v_user_type != 'brand' THEN
    RETURN NEW;
  END IF;

  -- Count total activity logs
  SELECT COUNT(*) INTO total_actions
  FROM public.activity_logs
  WHERE user_id = v_user_id;

  -- Check milestone thresholds
  IF total_actions >= 1000 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'bronze_tier', NEW.id);
  END IF;
  IF total_actions >= 5000 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'silver_tier', NEW.id);
  END IF;
  IF total_actions >= 10000 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'gold_tier', NEW.id);
  END IF;
  IF total_actions >= 25000 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'platinum_tier', NEW.id);
  END IF;
  IF total_actions >= 50000 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'diamond_tier', NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 657 (class 1255 OID 41253)
-- Name: check_multi_content_achievements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_multi_content_achievements() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid := NEW.user_id;
  v_user_type TEXT;
  cnt_status int;
  cnt_survey int;
  cnt_challenge int;
BEGIN
  -- FIX: Only run this logic for users of type 'brand'
  SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_user_id;
  IF v_user_type != 'brand' THEN
    RETURN NEW;
  END IF;

  IF NEW.action_type NOT IN ('create_status_post','survey_created','challenge_created','status_creation_success','challenge_creation_success') THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(*) INTO cnt_status FROM public.activity_logs
  WHERE user_id = v_user_id AND action_type IN ('create_status_post', 'status_creation_success');

  SELECT COUNT(*) INTO cnt_survey FROM public.activity_logs
  WHERE user_id = v_user_id AND action_type = 'survey_created';

  SELECT COUNT(*) INTO cnt_challenge FROM public.activity_logs
  WHERE user_id = v_user_id AND action_type IN ('challenge_created', 'challenge_creation_success');

  IF cnt_status >= 1 AND cnt_survey >= 1 AND cnt_challenge >= 1 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'triple_threat', NEW.id);
  END IF;

  IF cnt_status >= 10 AND cnt_survey >= 10 AND cnt_challenge >= 10 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'content_wizard', NEW.id);
  END IF;

  IF cnt_status >= 25 AND cnt_survey >= 25 AND cnt_challenge >= 25 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'platform_master', NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 495 (class 1255 OID 54766)
-- Name: check_pass_it_completion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_pass_it_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_campaign_status VARCHAR(20);
BEGIN
    -- First, check if the campaign is still active. If not, do nothing.
    SELECT status INTO v_campaign_status
    FROM pass_it_campaigns
    WHERE id = NEW.campaign_id;

    IF v_campaign_status = 'active' THEN
        -- Update chain pass count
        UPDATE pass_it_chains 
        SET current_passes = current_passes + 1
        WHERE id = NEW.chain_id;
        
        -- Check if target is reached
        IF (SELECT current_passes FROM pass_it_chains WHERE id = NEW.chain_id) >= 
           (SELECT target_passes FROM pass_it_campaigns WHERE id = NEW.campaign_id) THEN
            
            -- Mark chain as winner if first to complete
            UPDATE pass_it_chains 
            SET is_winner = TRUE, status = 'completed', completed_at = NOW()
            WHERE id = NEW.chain_id;
            
            -- Mark campaign as completed
            UPDATE pass_it_campaigns 
            SET status = 'completed', winner_chain_id = NEW.chain_id, completed_at = NOW()
            WHERE id = NEW.campaign_id;
            
            -- (Placeholder) Trigger reward distribution
            -- PERFORM distribute_pass_it_rewards(NEW.chain_id);
            
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


