--
-- TOC entry 590 (class 1255 OID 41251)
-- Name: check_post_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_post_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid := NEW.user_id;
  v_user_type TEXT;
  v_weeks_count int;
BEGIN
  -- FIX: Only run this logic for users of type 'brand'
  SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_user_id;
  IF v_user_type != 'brand' THEN
    RETURN NEW;
  END IF;

  IF NEW.action_type IS DISTINCT FROM 'create_status_post' THEN
    RETURN NEW;
  END IF;

  SELECT COUNT(DISTINCT EXTRACT('year' FROM timestamp)::text || '-' || EXTRACT('week' FROM timestamp)::text)
  INTO v_weeks_count
  FROM public.activity_logs
  WHERE user_id = v_user_id
    AND action_type = 'create_status_post'
    AND timestamp >= (NEW.timestamp - INTERVAL '16 weeks');

  IF v_weeks_count >= 4 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'weekly_creator', NEW.id);
  END IF;

  IF v_weeks_count >= 12 THEN
    PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'monthly_curator', NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 576 (class 1255 OID 41246)
-- Name: check_simple_count_achievements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_simple_count_achievements() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id UUID := NEW.user_id;
  v_user_type TEXT;
  v_action_type TEXT;
  v_achievement_def RECORD;
  v_action_count INT;
  v_already_unlocked BOOLEAN;
BEGIN
  -- FIX: Only run this logic for users of type 'brand'
  SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_user_id;
  IF v_user_type != 'brand' THEN
    RETURN NEW;
  END IF;

  v_action_type := NEW.action_type;

  IF v_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOR v_achievement_def IN 
    SELECT * FROM public.achievement_definitions 
    WHERE action_type = v_action_type 
    AND is_active = true
    AND category NOT IN ('consistency', 'efficiency', 'milestone', 'generosity', 'exploration')
  LOOP
    SELECT EXISTS (
      SELECT 1 FROM public.brand_achievements
      WHERE brand_id = v_user_id AND achievement_key = v_achievement_def.key
    ) INTO v_already_unlocked;

    IF NOT v_already_unlocked THEN
      SELECT COUNT(*) INTO v_action_count
      FROM public.activity_logs
      WHERE user_id = v_user_id AND action_type = v_action_type;

      IF v_action_count >= v_achievement_def.threshold THEN
        VALUES (v_user_id, v_achievement_def.key);

        IF v_achievement_def.reward_coins > 0 THEN
          UPDATE public.profiles
          SET brandible_coins = COALESCE(brandible_coins, 0) + v_achievement_def.reward_coins,
              total_earned = COALESCE(total_earned, 0) + v_achievement_def.reward_coins
          WHERE id = v_user_id;

          VALUES (
            v_user_id,
            'achievement_reward',
            v_achievement_def.reward_coins,
            'Unlocked achievement: ' || v_achievement_def.name,
            NEW.id,
            'activity_log'
          );
        END IF;
      END IF;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- TOC entry 765 (class 1255 OID 41255)
-- Name: check_speed_efficiency_achievements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_speed_efficiency_achievements() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_user_id uuid := NEW.user_id;
  v_user_type TEXT;
  signup_ts timestamptz;
  posts_today int;
  total_posts int;
BEGIN
  -- FIX: Only run this logic for users of type 'brand'
  SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_user_id;
  IF v_user_type != 'brand' THEN
    RETURN NEW;
  END IF;

  IF NEW.action_type NOT IN ('create_status_post', 'status_creation_success') THEN
    RETURN NEW;
  END IF;

  SELECT created_at INTO signup_ts FROM public.profiles WHERE id = v_user_id;
  
  IF signup_ts IS NOT NULL THEN
    SELECT COUNT(*) INTO total_posts FROM public.activity_logs
    WHERE user_id = v_user_id AND action_type IN ('create_status_post', 'status_creation_success');

    IF total_posts = 1 THEN
      IF NEW.timestamp <= signup_ts + INTERVAL '24 hours' THEN
        PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'quick_launcher', NEW.id);
      END IF;
    END IF;

    SELECT COUNT(*) INTO posts_today FROM public.activity_logs
    WHERE user_id = v_user_id
      AND action_type IN ('create_status_post', 'status_creation_success')
      AND (timestamp AT TIME ZONE 'UTC')::date = (NEW.timestamp AT TIME ZONE 'UTC')::date;

    IF posts_today >= 3 THEN
      PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'rapid_fire', NEW.id);
    END IF;

    IF posts_today >= 5 THEN
      PERFORM public.unlock_achievement_if_not_unlocked(v_user_id, 'power_day', NEW.id);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 508 (class 1255 OID 196445)
-- Name: check_trigger_words_availability(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_trigger_words_availability(p_trigger_words text[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_unavailable_words TEXT[];
  v_word TEXT;
BEGIN

  FOREACH v_word IN ARRAY p_trigger_words
  LOOP

    IF EXISTS (
      SELECT 1
      FROM game_campaigns
      WHERE status = 'active'
      AND expires_at > NOW()
      AND v_word = ANY(game_triggers)
    ) THEN
      v_unavailable_words := array_append(v_unavailable_words, v_word);
    END IF;

  END LOOP;

  IF array_length(v_unavailable_words, 1) > 0 THEN

    RETURN json_build_object(
      'available', false,
      'unavailable_words', v_unavailable_words,
      'message',
      'The following trigger words are already in use: ' ||
      array_to_string(v_unavailable_words, ', ')
    );

  ELSE

    RETURN json_build_object(
      'available', true,
      'message', 'All trigger words are available'
    );

  END IF;

END;
$$;


