CREATE FUNCTION public.cleanup_orphaned_files() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  -- This function can be used to clean up files that are no longer referenced
  -- Run this periodically to save storage space
  
  -- Example: Delete challenge submission files older than 90 days with no database reference
  DELETE FROM storage.objects 
  WHERE bucket_id = 'challenge-submissions' 
  AND created_at < NOW() - INTERVAL '90 days'
  AND NOT EXISTS (
    SELECT 1 FROM challenge_submissions cs 
    WHERE cs.submission_url LIKE '%' || name || '%'
  );
  
END;
$$;


