-- TOC entry 672 (class 1255 OID 62853)
-- Name: close_poll(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_poll(p_poll_id uuid) RETURNS public.polls
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_agent_id uuid;
    v_user_type text;
    v_closed_poll public.polls;
BEGIN
    SELECT auth.uid() INTO v_agent_id;
    SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_agent_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RAISE EXCEPTION 'Only agents can close polls.';
    END IF;

    UPDATE public.polls
    SET
        status = 'closed',
        closes_at = NOW() -- Ensure closes_at is set to now if manually closed
    WHERE id = p_poll_id
    RETURNING * INTO v_closed_poll;

    IF v_closed_poll IS NULL THEN
        RAISE EXCEPTION 'Poll not found or not authorized to close.';
    END IF;

    RETURN v_closed_poll;
END;
$$;


--
-- TOC entry 753 (class 1255 OID 203566)
-- Name: close_unboxed_referral_deal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_unboxed_referral_deal(p_submission_id uuid) RETURNS TABLE(success boolean, message text, refunded_amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_submission unboxed_submissions%ROWTYPE;
  v_brand_profile_id UUID;
  v_refund_amount DECIMAL;
BEGIN
  -- 1. Get submission details
  SELECT * INTO v_submission
  FROM unboxed_submissions
  WHERE id = p_submission_id
  FOR UPDATE;

  IF v_submission.id IS NULL THEN
    RETURN QUERY SELECT FALSE::BOOLEAN, 'Submission not found'::TEXT, 0::DECIMAL;
    RETURN;
  END IF;

  -- 2. Only allow closing if submission is approved (active)
  IF v_submission.status != 'approved' THEN
    RETURN QUERY SELECT FALSE::BOOLEAN, 'Can only close active (approved) deals'::TEXT, 0::DECIMAL;
    RETURN;
  END IF;

  -- 3. Get the brand's profile_id
  SELECT profile_id INTO v_brand_profile_id
  FROM brands
  WHERE id = v_submission.brand_id;

  IF v_brand_profile_id IS NULL THEN
    RETURN QUERY SELECT FALSE::BOOLEAN, 'Brand not found'::TEXT, 0::DECIMAL;
    RETURN;
  END IF;

  -- 4. Calculate refund amount (remaining unused budget)
  v_refund_amount := COALESCE(v_submission.reserved_budget, 0);

  -- 5. Update brand's wallet (add refunded amount back)
  IF v_refund_amount > 0 THEN
    UPDATE profiles
    SET brandible_coins = brandible_coins + v_refund_amount
    WHERE id = v_brand_profile_id;

    -- ✅ Record the transaction using 'released_from_escrow' type
      user_id, 
      type, 
      amount, 
      description, 
      reference_id, 
      reference_type
    ) VALUES (
      v_brand_profile_id,
      'released_from_escrow',
      v_refund_amount,
      'Refund from closed unboxed referral deal',
      p_submission_id,
      'unbox_close_deal'
    );
  END IF;

  -- 6. Close the submission (mark as inactive)
  UPDATE unboxed_submissions
  SET 
    reserved_budget = 0,
    status = 'inactive',
    updated_at = NOW()
  WHERE id = p_submission_id;

  -- 7. Log the activity - details as JSONB
    user_id,
    user_type,
    action_type,
    entity_type,
    entity_id,
    details,  -- ✅ This is JSONB
    metadata,
    timestamp
  ) VALUES (
    v_brand_profile_id,
    'brand',
    'unbox_deal_closed',
    'unboxed_submission',
    p_submission_id,
    jsonb_build_object(  -- ✅ Use jsonb_build_object for details
      'refunded_amount', v_refund_amount,
      'action', 'Closed unboxing referral deal and refunded ' || v_refund_amount::TEXT || ' BC'
    ),
    jsonb_build_object(
      'refunded_amount', v_refund_amount,
      'total_sales_made', v_submission.total_sales_count,
      'total_earned_by_influencer', v_submission.total_earned_by_influencer,
      'influencer_id', v_submission.influencer_id
    ),
    NOW()
  );

  RETURN QUERY SELECT TRUE::BOOLEAN, 'Referral deal closed successfully'::TEXT, v_refund_amount;

EXCEPTION WHEN OTHERS THEN
  RETURN QUERY SELECT FALSE::BOOLEAN, SQLERRM::TEXT, 0::DECIMAL;
END;
$$;


