--
-- TOC entry 524 (class 1255 OID 219496)
-- Name: create_challenge_with_balance_check(uuid, text, text, integer, numeric, timestamp with time zone, boolean, text, text, text[], integer, boolean, text, integer, text[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_challenge_with_balance_check(p_brand_id uuid, p_title text, p_description text, p_duration integer, p_reward_amount numeric, p_expires_at timestamp with time zone, p_is_private boolean, p_challenge_prompt text, p_submission_guidelines text, p_hashtags text[] DEFAULT NULL::text[], p_max_duration integer DEFAULT NULL::integer, p_is_collaborative boolean DEFAULT false, p_collaboration_type text DEFAULT NULL::text, p_max_participants integer DEFAULT NULL::integer, p_target_locations text[] DEFAULT '{}'::text[], p_target_hub_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_status_post_id UUID;
  v_challenge_id UUID;
  v_brand_balance NUMERIC(10,2);
  v_total_potential_cost NUMERIC(10,2);
  v_base_cost NUMERIC(10,2);
  v_initial_reserved_funds NUMERIC(10,2);
  v_transaction_type TEXT;
  v_transaction_description TEXT;
  v_is_hub_targeted BOOLEAN;
BEGIN
  -- 1. Determine if hub targeted
  v_is_hub_targeted := p_is_private AND array_length(p_target_hub_ids, 1) > 0;

  -- 2. Calculate total cost (including 10% surcharge if hub targeted)
  v_base_cost := p_reward_amount * p_max_participants;
  v_total_potential_cost := CASE WHEN v_is_hub_targeted THEN v_base_cost * 1.1 ELSE v_base_cost END;

  -- 3. Fetch brand's current balance and lock row
  SELECT brandible_coins INTO v_brand_balance
  FROM public.profiles
  WHERE id = p_brand_id
  FOR UPDATE;

  -- 4. Check balance
  IF v_brand_balance < v_total_potential_cost THEN
    RAISE EXCEPTION 'Insufficient Brandible Coins. Current balance: %, required: %', v_brand_balance, v_total_potential_cost;
  END IF;

  -- 5. Handle Private vs Public Logic
  -- For HUB TARGETED private challenges, we ESCROW the funds now (like public)
  -- For MANUAL INVITE private challenges (no hubs), we don't escrow yet
  IF p_is_private AND NOT v_is_hub_targeted THEN
    v_initial_reserved_funds := 0.00;
    -- No transaction for manual private challenges
    v_transaction_type := NULL;
    v_transaction_description := NULL;
  ELSE
    v_initial_reserved_funds := v_total_potential_cost;
    v_transaction_type := 'reserved';
    v_transaction_description := 'Coins reserved for challenge: ' || p_title;

    UPDATE public.profiles
    SET brandible_coins = brandible_coins - v_total_potential_cost
    WHERE id = p_brand_id;

    VALUES (p_brand_id, v_transaction_type, -v_total_potential_cost, v_transaction_description, 'challenge_escrow');
  END IF;

  -- 6. Insert Status Post
    brand_id, type, title, description,
    duration, reward_amount, expires_at, is_active,
    reward_limit, hashtags, is_private, target_locations, reserved_funds
  ) VALUES (
    p_brand_id, 'challenge', p_title, p_description,
    p_duration, p_reward_amount, p_expires_at, true,
    p_max_participants, COALESCE(p_hashtags, '{}'), p_is_private, 
    p_target_locations, v_initial_reserved_funds
  ) RETURNING id INTO v_status_post_id;

  -- 7. Link Hubs if targeted
  IF v_is_hub_targeted THEN
    SELECT v_status_post_id, unnest(p_target_hub_ids);
  END IF;

  -- 8. Insert Challenge (NO review_required field)
    status_post_id, challenge_prompt, submission_guidelines,
    hashtags, max_duration, 
    is_collaborative, collaboration_type, max_participants
  ) VALUES (
    v_status_post_id, p_challenge_prompt, p_submission_guidelines,
    p_hashtags, p_max_duration,
    p_is_collaborative, p_collaboration_type, p_max_participants
  ) RETURNING id INTO v_challenge_id;

  -- 9. Update Transaction Reference (if a transaction was created)
  IF v_transaction_type IS NOT NULL THEN
    UPDATE public.transactions
    SET reference_id = v_challenge_id
    WHERE user_id = p_brand_id 
      AND type = v_transaction_type 
      AND description = v_transaction_description 
      AND reference_id IS NULL;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'challenge_id', v_challenge_id,
    'status_post_id', v_status_post_id,
    'total_cost', v_total_potential_cost
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;


--
-- TOC entry 857 (class 1255 OID 31381)
-- Name: create_collaboration_group(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_collaboration_group(p_challenge_id uuid, p_creator_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_group_id uuid;
  v_group_code text;
  v_challenge record;
BEGIN
  SELECT c.*, sp.reward_amount INTO v_challenge
  FROM public.challenges c
  JOIN public.status_posts sp ON c.status_post_id = sp.id
  WHERE c.id = p_challenge_id;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'message', 'Challenge not found');
  END IF;

  IF NOT v_challenge.is_collaborative THEN
    RETURN json_build_object('success', false, 'message', 'Challenge is not collaborative');
  END IF;

  v_group_code := generate_group_code();

  VALUES (p_challenge_id, p_creator_id, v_group_code, v_challenge.reward_amount)
  RETURNING id INTO v_group_id;

  VALUES (v_group_id, p_creator_id, 'creator');

  RETURN json_build_object(
    'success', true,
    'group_id', v_group_id,
    'group_code', v_group_code,
    'message', 'Collaboration group created successfully'
  );
END;
$$;


--
-- TOC entry 646 (class 1255 OID 214691)
-- Name: create_influencer_hub(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_influencer_hub(p_name text, p_description text, p_industry text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_code TEXT;
    v_hub_id UUID;
BEGIN
    IF EXISTS (SELECT 1 FROM public.hubs WHERE owner_id = v_user_id) THEN
        RETURN jsonb_build_object('success', false, 'message', 'You already own a Hub.');
    END IF;

    v_code := public.generate_unique_invite_code();

    VALUES (v_user_id, p_name, p_description, p_industry, v_code)
    RETURNING id INTO v_hub_id;

    UPDATE public.profiles SET referral_code = v_code WHERE id = v_user_id;

    RETURN jsonb_build_object(
        'success', true, 
        'hub_id', v_hub_id,
        'invite_code', v_code
    );
END;
$$;


--
-- TOC entry 843 (class 1255 OID 58568)
-- Name: create_investment(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_investment(p_investor_id uuid, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_new_investment_id UUID;
  v_transaction_id UUID;
BEGIN
  IF (get_my_claim('user_type'))::text != 'agent' THEN
    RAISE EXCEPTION 'Only agents can create investments';
  END IF;

  -- Insert into investments table
  VALUES (p_investor_id, p_amount)
  RETURNING id INTO v_new_investment_id;

  -- Insert into transactions table
  VALUES (
    (SELECT profile_id FROM public.investors WHERE id = p_investor_id),
    'investment',
    p_amount,
    'Initial investment',
    v_new_investment_id,
    'investment'
  ) RETURNING id INTO v_transaction_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Investment created successfully',
    'investment_id', v_new_investment_id,
    'transaction_id', v_transaction_id
  );
END;
$$;


--
-- TOC entry 534 (class 1255 OID 59902)
-- Name: create_investment_enhanced(uuid, numeric, date, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_investment_enhanced(p_investor_id uuid, p_amount numeric, p_investment_date date DEFAULT CURRENT_DATE, p_investor_level_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_new_investment_id UUID;
  v_transaction_id UUID;
  v_profile_id UUID;
  v_current_level_id UUID;
BEGIN
  -- Only agents can create investments
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND user_type = 'agent') THEN
    RAISE EXCEPTION 'Only agents can create investments';
  END IF;

  -- Get the investor's profile_id and current level_id
  SELECT profile_id, level_id INTO v_profile_id, v_current_level_id
  FROM public.investors 
  WHERE id = p_investor_id;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Investor not found with ID: %', p_investor_id;
  END IF;

  -- Update investor level if a new one is provided
  IF p_investor_level_id IS NOT NULL AND p_investor_level_id != v_current_level_id THEN
    -- Verify the new level exists
    IF NOT EXISTS (SELECT 1 FROM public.investor_levels WHERE id = p_investor_level_id) THEN
      RAISE EXCEPTION 'Investor level not found with ID: %', p_investor_level_id;
    END IF;

    -- Update the investor's level
    UPDATE public.investors 
    SET level_id = p_investor_level_id 
    WHERE id = p_investor_id;
  END IF;

  -- Insert into investments table
  VALUES (p_investor_id, p_amount, COALESCE(p_investment_date, CURRENT_DATE), p_notes)
  RETURNING id INTO v_new_investment_id;

  -- Insert into transactions table
  VALUES (
    v_profile_id,
    'investment',
    p_amount,
    CASE 
      WHEN p_notes IS NOT NULL AND LENGTH(p_notes) > 0 
      THEN 'Investment: ' || p_notes
      ELSE 'Initial investment'
    END,
    v_new_investment_id,
    'investment'
  ) RETURNING id INTO v_transaction_id;

  RETURN jsonb_build_object(
    'success', TRUE,
    'message', 'Investment created successfully',
    'investment_id', v_new_investment_id,
    'transaction_id', v_transaction_id,
    'notes', p_notes,
    'investment_date', p_investment_date,
    'level_updated', CASE WHEN p_investor_level_id IS NOT NULL AND p_investor_level_id != v_current_level_id THEN TRUE ELSE FALSE END
  );
END;
$$;


