--
-- TOC entry 629 (class 1255 OID 62852)
-- Name: create_poll(text, timestamp with time zone, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_poll(p_question text, p_closes_at timestamp with time zone, p_options text[], p_description text DEFAULT NULL::text) RETURNS public.polls
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_author_id uuid;
    v_user_type text;
    v_new_poll public.polls;
    v_option_text text;
BEGIN
    SELECT auth.uid() INTO v_author_id;
    SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_author_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RAISE EXCEPTION 'Only agents can create polls.';
    END IF;

    IF p_options IS NULL OR array_length(p_options, 1) < 2 THEN
        RAISE EXCEPTION 'A poll must have at least two options.';
    END IF;

    VALUES (p_question, p_description, v_author_id, p_closes_at, 'open')
    RETURNING * INTO v_new_poll;

    FOREACH v_option_text IN ARRAY p_options
    LOOP
        VALUES (v_new_poll.id, v_option_text);
    END LOOP;

    RETURN v_new_poll;
END;
$$;


--
-- TOC entry 515 (class 1255 OID 28848)
-- Name: create_referral_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_referral_code(p_user_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_code TEXT;
    v_username TEXT;
    v_random_suffix TEXT;
    v_is_unique BOOLEAN := false;
BEGIN
    SELECT username INTO v_username FROM public.profiles WHERE id = p_user_id;

    -- Sanitize username and take the first part
    v_username := UPPER(regexp_replace(v_username, '[^a-zA-Z0-9]', '', 'g'));
    IF char_length(v_username) > 8 THEN
        v_username := substring(v_username from 1 for 8);
    END IF;

    -- Loop to ensure code uniqueness
    WHILE NOT v_is_unique LOOP
        v_random_suffix := to_hex(floor(random() * 10000)::int);
        v_code := v_username || '-' || v_random_suffix;

        PERFORM id FROM public.profiles WHERE referral_code = v_code;
        IF NOT FOUND THEN
            v_is_unique := true;
        END IF;
    END LOOP;

    -- Save the unique code to the user's profile
    UPDATE public.profiles SET referral_code = v_code WHERE id = p_user_id;

    RETURN v_code;
END;
$$;


--
-- TOC entry 494 (class 1255 OID 38404)
-- Name: create_status_post_with_balance_check(uuid, text, text, text, text, text, integer, numeric, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_status_post_with_balance_check(p_brand_id uuid, p_type text, p_title text, p_description text, p_media_url text, p_media_type text, p_duration integer, p_reward_amount numeric, p_reward_limit integer, p_expires_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_status_post_id UUID;
  v_brand_balance NUMERIC(10,2);
  v_total_cost NUMERIC(10,2);
BEGIN
  -- 1. Calculate total cost
  v_total_cost := p_reward_amount * p_reward_limit;

  -- 2. Fetch brand's current balance and lock the row for update
  SELECT brandible_coins INTO v_brand_balance
  FROM public.profiles
  WHERE id = p_brand_id
  FOR UPDATE; -- Lock the row to prevent race conditions

  -- 3. Check if brand has sufficient balance
  IF v_brand_balance < v_total_cost THEN
    RAISE EXCEPTION 'Insufficient Brandible Coins. Current balance: %, required: %.', v_brand_balance, v_total_cost;
  END IF;

  -- 4. Deduct coins from brand's balance
  UPDATE public.profiles
  SET brandible_coins = brandible_coins - v_total_cost
  WHERE id = p_brand_id;

  -- 5. Record transaction for coin deduction
  VALUES (
    p_brand_id,
    'spent',
    -v_total_cost, -- Negative amount for deduction
    'Coins spent for status post: ' || p_title,
    NULL, -- reference_id will be updated after status_post insert
    'status_post_creation'
  );

  -- 6. Create the status post
    brand_id, type, title, description,
    media_url, media_type, duration, reward_amount,
    reward_limit, expires_at, is_active
  ) VALUES (
    p_brand_id, p_type, p_title, p_description,
    p_media_url, p_media_type, p_duration, p_reward_amount,
    p_reward_limit, p_expires_at, true
  ) RETURNING id INTO v_status_post_id;

  -- Update the transaction with the actual status_post_id
  UPDATE public.transactions
  SET reference_id = v_status_post_id
  WHERE user_id = p_brand_id AND type = 'spent' AND description = 'Coins spent for status post: ' || p_title AND reference_id IS NULL;

  RETURN v_status_post_id;

EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Status post creation failed: %', SQLERRM;
END;
$$;


--
-- TOC entry 603 (class 1255 OID 215871)
-- Name: create_status_post_with_media_array(uuid, text, text, text, jsonb, integer, numeric, integer, timestamp with time zone, text[], boolean, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_status_post_with_media_array(p_brand_id uuid, p_type text, p_title text, p_description text, p_media_items jsonb, p_duration integer, p_reward_amount numeric, p_reward_limit integer, p_expires_at timestamp with time zone, p_hashtags text[] DEFAULT NULL::text[], p_is_private boolean DEFAULT false, p_target_locations text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_status_post_id UUID;
  v_transaction_id UUID;
  v_brand_balance NUMERIC(10,2);
  v_total_cost NUMERIC(10,2);
  v_media_count INTEGER;
  v_reward_per_media NUMERIC(10,2);
  v_media_item JSONB;
  v_order_index INTEGER := 0;
BEGIN
  -- VALIDATION: Check brand_id is not null
  IF p_brand_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Brand ID cannot be null'
    );
  END IF;

  -- 1. Get media count
  v_media_count := jsonb_array_length(p_media_items);
  IF v_media_count = 0 THEN 
    v_media_count := 1; 
  END IF;

  -- 2. Calculate reward per media & total cost
  v_reward_per_media := p_reward_amount / v_media_count;
  v_total_cost := p_reward_amount * p_reward_limit;

  -- 3. Check brand balance with ROW LOCK (prevents race conditions)
  SELECT brandible_coins INTO v_brand_balance
  FROM public.profiles
  WHERE id = p_brand_id
  FOR UPDATE;

  -- 4. Validate balance
  IF v_brand_balance IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Brand profile not found'
    );
  END IF;

  IF v_brand_balance < v_total_cost THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Insufficient Brandible Coins. Current balance: %s, required: %s', v_brand_balance, v_total_cost)
    );
  END IF;

  -- 5. Deduct coins from brand
  UPDATE public.profiles
  SET brandible_coins = brandible_coins - v_total_cost
  WHERE id = p_brand_id;

  -- 6. Record transaction
  VALUES (
    p_brand_id,
    'spent',
    -v_total_cost,
    'Coins spent for status post: ' || p_title,
    'status_post_creation'
  ) RETURNING id INTO v_transaction_id;

  -- 7. Create the status post (now includes target_locations)
    brand_id, type, title, description,
    media_url, media_type, duration, reward_amount,
    reward_limit, expires_at, is_active, reserved_funds,
    hashtags, is_private, target_locations
  ) VALUES (
    p_brand_id, p_type, p_title, p_description,
    NULL, NULL,
    p_duration, p_reward_amount,
    p_reward_limit * v_media_count, p_expires_at, true, v_total_cost,
    COALESCE(p_hashtags, ARRAY[]::text[]),
    p_is_private,
    COALESCE(p_target_locations, '{}'::text[])
  ) RETURNING id INTO v_status_post_id;

  -- 8. Link transaction to post
  UPDATE public.transactions 
  SET reference_id = v_status_post_id 
  WHERE id = v_transaction_id;

  -- 9. Insert media items
  FOR v_media_item IN SELECT * FROM jsonb_array_elements(p_media_items)
  LOOP
      status_post_id,
      media_url,
      media_type,
      order_index,
      reward_per_view,
      current_rewards_given,
      view_count
    ) VALUES (
      v_status_post_id,
      v_media_item->>'media_url',
      v_media_item->>'media_type',
      v_order_index,
      v_reward_per_media,
      0,
      0
    );
    v_order_index := v_order_index + 1;
  END LOOP;

  -- 10. Return success with diagnostic info
  RETURN jsonb_build_object(
    'success', true,
    'status_post_id', v_status_post_id,
    'transaction_id', v_transaction_id,
    'total_cost', v_total_cost,
    'reward_per_media', v_reward_per_media,
    'media_count', v_media_count,
    'total_reward_limit', p_reward_limit * v_media_count
  );
  
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM,
    'error_detail', SQLSTATE
  );
END;
$$;


--
-- TOC entry 497 (class 1255 OID 219457)
-- Name: create_survey_with_status_post(uuid, text, text, integer, numeric, integer, timestamp with time zone, jsonb, text[], boolean, text[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_survey_with_status_post(p_brand_id uuid, p_title text, p_description text, p_duration integer, p_reward_amount numeric, p_reward_limit integer, p_expires_at timestamp with time zone, p_questions jsonb, p_hashtags text[] DEFAULT NULL::text[], p_is_private boolean DEFAULT false, p_target_locations text[] DEFAULT '{}'::text[], p_target_hub_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_survey_id uuid;
    v_status_post_id uuid;
    v_question JSONB;
    v_question_id UUID;
    v_question_ids UUID[] := '{}';
    v_result JSONB;
    i INTEGER;
    v_brand_balance NUMERIC(10,2);
    v_total_cost NUMERIC(10,2);
    v_base_cost NUMERIC(10,2);
BEGIN
    RAISE NOTICE '--- STARTING SURVEY CREATION ---';

    -- 1. Calculate total cost (including 10% surcharge if private)
    v_base_cost := p_reward_amount * p_reward_limit;
    v_total_cost := CASE WHEN p_is_private THEN v_base_cost * 1.1 ELSE v_base_cost END;

    -- 2. Fetch brand's current balance
    SELECT brandible_coins INTO v_brand_balance
    FROM public.profiles
    WHERE id = p_brand_id
    FOR UPDATE;

    -- 3. Check balance
    IF v_brand_balance < v_total_cost THEN
        RAISE EXCEPTION 'Insufficient Brandible Coins. Current balance: %, required: %.', v_brand_balance, v_total_cost;
    END IF;

    -- 4. Deduct coins
    UPDATE public.profiles
    SET brandible_coins = brandible_coins - v_total_cost
    WHERE id = p_brand_id;

    -- 5. Record transaction
    VALUES (
        p_brand_id,
        'spent',
        -v_total_cost,
        'Coins spent for survey creation: ' || p_title,
        NULL,
        'survey_creation'
    );

    -- 1️⃣ Create the status post (with targeting fields)
        brand_id,
        type,
        title,
        description,
        duration,
        reward_amount,
        reward_limit,
        reserved_funds,     -- ✅ Added from updated version
        expires_at,
        created_at,
        hashtags,
        is_private,         -- ✅ Added for private surveys
        target_locations    -- ✅ Added for location targeting
    )
    VALUES (
        p_brand_id,
        'survey',
        p_title,
        p_description,
        p_duration,
        p_reward_amount,
        p_reward_limit,
        v_total_cost,       -- ✅ Track reserved funds
        p_expires_at,
        NOW(),
        COALESCE(p_hashtags, '{}'),
        p_is_private,       -- ✅ Private flag
        p_target_locations  -- ✅ Location targeting
    )
    RETURNING id INTO v_status_post_id;

    RAISE NOTICE 'Status post created with ID: %', v_status_post_id;

    -- 1.5️⃣ Link hubs if private (NEW from updated version)
    IF p_is_private AND array_length(p_target_hub_ids, 1) > 0 THEN
        SELECT v_status_post_id, unnest(p_target_hub_ids);
        RAISE NOTICE 'Linked % hubs to status post', array_length(p_target_hub_ids, 1);
    END IF;

    -- 2️⃣ Create the survey record
        status_post_id,
        created_at
    )
    VALUES (
        v_status_post_id,
        NOW()
    )
    RETURNING id INTO v_survey_id;

    RAISE NOTICE 'Survey created with ID: %', v_survey_id;

    -- Update transaction reference
    UPDATE public.transactions
    SET reference_id = v_survey_id
    WHERE user_id = p_brand_id 
      AND type = 'spent' 
      AND description = 'Coins spent for survey creation: ' || p_title 
      AND reference_id IS NULL;

    -- 3️⃣ Insert questions (0-based indexing)
    FOR i IN 0..jsonb_array_length(p_questions) - 1
    LOOP
        v_question := p_questions -> i;

            survey_id,
            question_text,
            question_type,
            order_index,
            is_required
        )
        VALUES (
            v_survey_id,
            v_question->>'question_text',
            v_question->>'question_type',
            i,
            COALESCE((v_question->>'is_required')::boolean, TRUE)
        )
        RETURNING id INTO v_question_id;

        v_question_ids := array_append(v_question_ids, v_question_id);
    END LOOP;

    -- 4️⃣ Update options with skip logic (preserved from original)
    FOR i IN 0..jsonb_array_length(p_questions) - 1
    LOOP
        v_question := p_questions -> i;

        IF v_question->>'question_type' = 'multiple_choice'
           AND v_question ? 'options'
           AND jsonb_array_length(v_question->'options') > 0 THEN

            UPDATE public.survey_questions
            SET options = (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'option_text', opt->>'option_text',
                        'next_question_id',
                        CASE
                            WHEN opt->>'next_question_id' = 'no-skip' THEN
                                CASE WHEN (i + 1) < array_length(v_question_ids, 1)
                                     THEN v_question_ids[i + 2]::text
                                     ELSE NULL
                                END
                            WHEN opt->>'next_question_id' = 'end' THEN NULL
                            WHEN (opt->>'next_question_id') ~ '^\d+$' THEN
                                CASE WHEN (opt->>'next_question_id')::integer < array_length(v_question_ids, 1)
                                     THEN v_question_ids[(opt->>'next_question_id')::integer + 1]::text
                                     ELSE NULL
                                END
                            ELSE NULL
                        END
                    )
                )
                FROM jsonb_array_elements(v_question->'options') AS opt
            )
            WHERE id = v_question_ids[i+1];
        END IF;
    END LOOP;

    -- 5️⃣ Return data (enhanced with targeting info)
    RETURN jsonb_build_object(
        'success', true,
        'survey_id', v_survey_id,
        'status_post_id', v_status_post_id,
        'question_ids', v_question_ids,
        'total_cost', v_total_cost,
        'is_private', p_is_private,
        'target_hubs', COALESCE(p_target_hub_ids, '{}'),
        'target_locations', COALESCE(p_target_locations, '{}')
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_detail', SQLSTATE
        );
END;
$_$;


--
-- TOC entry 521 (class 1255 OID 197739)
-- Name: deduct_brand_coins_for_campaign(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deduct_brand_coins_for_campaign(p_brand_id uuid, p_amount numeric, p_campaign_name text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_current_balance DECIMAL;
BEGIN
  -- 1. Check Brand's main balance
  SELECT brandible_coins INTO v_current_balance 
  FROM public.profiles 
  WHERE id = p_brand_id;
  
  IF v_current_balance < p_amount THEN
    RETURN json_build_object(
      'success', false, 
      'message', 'Insufficient Brandible Coins. You need ' || p_amount || ' coins for this budget.'
    );
  END IF;
  
  -- 2. Deduct from main balance
  UPDATE public.profiles
  SET brandible_coins = brandible_coins - p_amount
  WHERE id = p_brand_id;
  
  -- 3. Record transaction
    user_id,
    type,
    amount,
    description,
    reference_type
  ) VALUES (
    p_brand_id,
    'spent',
    -p_amount,
    'Budget allocation for ' || p_campaign_name,
    'campaign_budget'
  );
  
  RETURN json_build_object(
    'success', true, 
    'new_balance', v_current_balance - p_amount
  );
END;
$$;


--
-- TOC entry 847 (class 1255 OID 197693)
-- Name: deduct_coins_for_game(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deduct_coins_for_game(p_user_id uuid, p_amount integer, p_game_name text) RETURNS json
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_current_game_coins DECIMAL;
BEGIN

  -- Fetch only game_coins from the user's profile
  SELECT game_coins 
  INTO v_current_game_coins
  FROM public.profiles 
  WHERE id = p_user_id;

  -- Check if user has enough game_coins
  IF COALESCE(v_current_game_coins, 0) < p_amount THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Insufficient game coins to play. You need ' || p_amount || ' game coins.'
    );
  END IF;

  -- Deduct ONLY from game_coins
  UPDATE public.profiles
  SET game_coins = game_coins - p_amount
  WHERE id = p_user_id;

  -- Insert transaction record
    user_id,
    type,
    amount,
    description,
    reference_type
  ) VALUES (
    p_user_id,
    'spent',
    -p_amount,
    'Level entry stake for ' || p_game_name,
    'game_play'
  );

  -- Return success with new balance
  RETURN json_build_object(
    'success', true,
    'message', 'Game coins deducted for game entry.',
    'new_balance', COALESCE(v_current_game_coins, 0) - p_amount
  );

END;
$$;


