$$;


--
-- TOC entry 788 (class 1255 OID 196444)
-- Name: delete_campaign_with_refund(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_campaign_with_refund(p_campaign_id uuid, p_brand_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$DECLARE
  v_campaign RECORD;
  v_refund_amount DECIMAL;
BEGIN

  SELECT * INTO v_campaign
  FROM game_campaigns
  WHERE id = p_campaign_id
  AND brand_id = p_brand_id;

  IF NOT FOUND THEN
    RETURN json_build_object(
      'success', false,
      'message', 'Campaign not found'
    );
  END IF;

  v_refund_amount := (v_campaign.total_budget - v_campaign.spent_amount) * 0.5;

  IF v_refund_amount > 0 THEN

    UPDATE profiles
    SET brandible_coins = brandible_coins + v_refund_amount
    WHERE id = p_brand_id;

      user_id,
      type,
      amount,
      description,
      reference_id,
      reference_type
    )
    VALUES (
      p_brand_id,
      'earned',
      v_refund_amount,
      'Campaign deletion refund: ' || v_campaign.campaign_name,
      p_campaign_id,
      'campaign_refund'
    );

  END IF;

  DELETE FROM game_campaigns
  WHERE id = p_campaign_id;

  RETURN json_build_object(
    'success', true,
    'refund_amount', v_refund_amount,
    'message', 'Campaign deleted successfully'
  );
END;$$;


--
-- TOC entry 660 (class 1255 OID 38776)
-- Name: delete_challenge_release_escrow(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_challenge_release_escrow(p_challenge_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_challenge public.challenges;
  v_status_post public.status_posts;
  v_brand_profile public.profiles;
  v_amount_to_release NUMERIC(10,2);
  v_participant_count INTEGER;
BEGIN
  -- 1. Fetch the challenge record and lock it
  SELECT * INTO v_challenge
  FROM public.challenges
  WHERE id = p_challenge_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenge with ID % not found.', p_challenge_id;
  END IF;

  -- 2. Fetch related status_post and brand profile, and lock them
  SELECT * INTO v_status_post
  FROM public.status_posts
  WHERE id = v_challenge.status_post_id
  FOR UPDATE;

  SELECT * INTO v_brand_profile
  FROM public.profiles
  WHERE id = v_status_post.brand_id
  FOR UPDATE;

  -- 3. Security Check: Only the brand owner or an agent can delete this challenge
  IF auth.uid() != v_status_post.brand_id AND (SELECT user_type FROM public.profiles WHERE id = auth.uid()) != 'agent' THEN
    RAISE EXCEPTION 'Unauthorized: Only the brand owner or an agent can delete this challenge.';
  END IF;

  -- 4. Validation: Check for participants/submissions
  SELECT COUNT(*) INTO v_participant_count
  FROM public.challenge_submissions
  WHERE challenge_id = p_challenge_id;

  IF v_participant_count > 0 THEN
    RAISE EXCEPTION 'Challenge has % participants/submissions. Cannot delete challenge with participants.', v_participant_count;
  END IF;

  -- 5. Determine amount to release
  v_amount_to_release := v_status_post.reserved_funds;

  IF v_amount_to_release IS NULL THEN
    v_amount_to_release := 0.00; -- Default to 0 if null
  END IF;

  -- 6. Release funds back to brand's balance if any reserved funds exist
  IF v_amount_to_release > 0 THEN
    UPDATE public.profiles
    SET brandible_coins = brandible_coins + v_amount_to_release
    WHERE id = v_brand_profile.id;

    -- 7. Set status_posts.reserved_funds to 0
    UPDATE public.status_posts
    SET reserved_funds = 0.00
    WHERE id = v_status_post.id;

    -- 8. Record transaction for brand (escrow released)
    VALUES (
      v_brand_profile.id,
      'escrow_released',
      v_amount_to_release, -- Positive amount for adding back to balance
      'Coins released from escrow due to challenge deletion: ' || v_status_post.title,
      p_challenge_id,
      'challenge_deletion_release'
    );
  END IF;

  -- 9. Delete the challenge record
  DELETE FROM public.challenges
  WHERE id = p_challenge_id;

  -- 10. Delete the status_post record
  DELETE FROM public.status_posts
  WHERE id = v_status_post.id;

  RETURN jsonb_build_object('success', true, 'message', 'Challenge deleted and unused funds released.');

EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Challenge deletion failed: %', SQLERRM;
END;
$$;


