--
-- TOC entry 680 (class 1255 OID 58026)
-- Name: distribute_cashout_profit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distribute_cashout_profit(p_cashout_transaction_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_cashout_transaction_amount NUMERIC;
    v_platform_fee_rate NUMERIC;
    v_platform_profit NUMERIC;
    v_investor_share_percentage NUMERIC;
    v_total_investments NUMERIC;
    v_investor_record RECORD;
    v_investor_return NUMERIC;
BEGIN
    -- 1. Get Cashout Transaction Details
    SELECT amount INTO v_cashout_transaction_amount
    FROM public.transactions
    WHERE id = p_cashout_transaction_id AND type = 'cashout_approved';

    IF v_cashout_transaction_amount IS NULL THEN
        RAISE EXCEPTION 'Cashout transaction % not found or not approved.', p_cashout_transaction_id;
    END IF;

    -- 2. Get Platform Fee Rate (e.g., 10% from app_settings or hardcoded)
    -- Assuming platform fee is 10% of the cashout amount
    v_platform_fee_rate := 0.10; -- This could be fetched from app_settings if dynamic

    v_platform_profit := v_cashout_transaction_amount * v_platform_fee_rate;

    -- 3. Get Investor Share Percentage from app_settings
    SELECT value::numeric INTO v_investor_share_percentage
    FROM public.app_settings
    WHERE key = 'investor_profit_share_percentage';

    IF v_investor_share_percentage IS NULL THEN
        -- Default to 0 if not set, or raise an error
        v_investor_share_percentage := 0.0;
        -- RAISE EXCEPTION 'App setting "investor_profit_share_percentage" not found.';
    END IF;

    -- Calculate total profit to distribute to investors from this cashout
    v_platform_profit := v_platform_profit * v_investor_share_percentage;

    -- If no profit to distribute, exit
    IF v_platform_profit <= 0 THEN
        RETURN;
    END IF;

    -- 4. Get Total Active Investments from all investors
    SELECT COALESCE(SUM(amount), 0) INTO v_total_investments
    FROM public.investments;

    -- If no investments, no one to distribute to
    IF v_total_investments <= 0 THEN
        RETURN;
    END IF;

    -- 5. Loop through each investor and distribute profit proportionally
    FOR v_investor_record IN
        SELECT i.id AS investor_id, COALESCE(SUM(inv.amount), 0) AS total_invested
        FROM public.investors i
        JOIN public.investments inv ON i.id = inv.investor_id
        GROUP BY i.id
    LOOP
        -- Calculate investor's share of the total investment pool
        -- This assumes all investments are equally weighted for profit distribution
        v_investor_return := (v_investor_record.total_invested / v_total_investments) * v_platform_profit;

        -- 6. Log the Return
        VALUES (
            v_investor_record.investor_id,
            v_investor_return,
            p_cashout_transaction_id,
            'Share of platform profit from cashout transaction'
        );
    END LOOP;

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Error distributing cashout profit for transaction %: %', p_cashout_transaction_id, SQLERRM;
END;
$$;


