--
-- TOC entry 679 (class 1255 OID 38822)
-- Name: extend_status_post_expiration(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extend_status_post_expiration(p_status_post_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_status_post public.status_posts;
  v_brand_id UUID;
  v_new_expires_at TIMESTAMP WITH TIME ZONE;
BEGIN
  -- 1. Fetch the status_post record and lock it
  SELECT * INTO v_status_post
  FROM public.status_posts
  WHERE id = p_status_post_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Status Post with ID % not found.', p_status_post_id;
  END IF;

  v_brand_id := v_status_post.brand_id;

  -- 2. Security Check: Only the brand owner or an agent can extend a campaign
  IF auth.uid() != v_brand_id AND (SELECT user_type FROM public.profiles WHERE id = auth.uid()) != 'agent' THEN
    RAISE EXCEPTION 'Unauthorized: Only the brand owner or an agent can extend this campaign.';
  END IF;

  -- 3. Calculate new expiration time (24 hours from NOW())
  v_new_expires_at := NOW() + INTERVAL '24 hours';

  -- 4. Update status_post
  UPDATE public.status_posts
  SET
    expires_at = v_new_expires_at,
    is_active = TRUE, -- Also reactivate the campaign
    updated_at = NOW()
  WHERE id = p_status_post_id;

  -- 5. Record activity log
  VALUES (
    auth.uid(),
    (SELECT user_type FROM public.profiles WHERE id = auth.uid()),
    'campaign_extended',
    p_status_post_id,
    'status_post',
    jsonb_build_object(
      'campaign_title', v_status_post.title,
      'old_expires_at', v_status_post.expires_at,
      'new_expires_at', v_new_expires_at,
      'campaign_type', v_status_post.type
    )
  );

  RETURN jsonb_build_object('success', true, 'message', 'Campaign expiration extended successfully.');

EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Campaign expiration extension failed: %', SQLERRM;
END;
$$;


--
-- TOC entry 696 (class 1255 OID 27050)
-- Name: feature_submission(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feature_submission(p_submission_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_brand_id UUID;
    v_submission_status TEXT;
BEGIN
    -- Get the brand_id of the challenge owner and the submission status
    SELECT sp.brand_id, cs.status
    INTO v_brand_id, v_submission_status
    FROM public.challenge_submissions cs
    JOIN public.challenges c ON cs.challenge_id = c.id
    JOIN public.status_posts sp ON c.status_post_id = sp.id
    WHERE cs.id = p_submission_id;

    -- Security Check: Ensure the caller is the brand who owns the challenge
    IF auth.uid() != v_brand_id THEN
        RAISE EXCEPTION 'Only the brand owner can feature a submission.';
    END IF;

    -- Logic Check: Ensure the submission has been approved
    IF v_submission_status != 'approved' THEN
        RAISE EXCEPTION 'Only approved submissions can be featured.';
    END IF;

    -- Update the submission to be featured
    UPDATE public.challenge_submissions
    SET is_featured = true
    WHERE id = p_submission_id;
END;
$$;


--
-- TOC entry 766 (class 1255 OID 23847)
-- Name: finalize_purchase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_purchase(p_purchase_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_agent_id uuid;
    v_user_type text;
    v_purchase RECORD;
    v_product RECORD;
BEGIN
    -- 1️⃣ Identify authenticated user (agent)
    SELECT auth.uid() INTO v_agent_id;
    IF v_agent_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Unauthorized: no authenticated user.');
    END IF;

    -- 2️⃣ Verify the user is an agent
    SELECT user_type INTO v_user_type
    FROM public.profiles
    WHERE id = v_agent_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RETURN json_build_object('success', false, 'message', 'Access denied: only agents can approve purchases.');
    END IF;

    -- 3️⃣ Fetch the purchase
    SELECT * INTO v_purchase
    FROM public.purchases
    WHERE id = p_purchase_id;

    IF v_purchase IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Purchase not found.');
    END IF;

    -- 4️⃣ Ensure purchase is shipped before approving
    IF v_purchase.status <> 'shipped' THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Purchase must be in "shipped" status before approval.'
        );
    END IF;

    -- 5️⃣ Fetch product details (for brand reference)
    SELECT * INTO v_product FROM public.products WHERE id = v_purchase.product_id;
    IF v_product IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Associated product not found.');
    END IF;

    -- 6️⃣ Transfer coins (escrow release)
    -- Deduct from buyer
    UPDATE public.profiles
    SET brandible_coins = brandible_coins - v_purchase.total_coins
    WHERE id = v_purchase.buyer_id;

    -- Credit to brand (seller)
    UPDATE public.profiles
    SET brandible_coins = brandible_coins + v_purchase.total_coins
    WHERE id = v_product.brand_id;

    -- 7️⃣ Record transactions
    VALUES (
        v_purchase.buyer_id,
        'spent',
        -v_purchase.total_coins,
        'Approved purchase of ' || v_product.name,
        p_purchase_id,
        'product_purchase'
    );

    VALUES (
        v_product.brand_id,
        'earned',
        v_purchase.total_coins,
        'Sale approved for ' || v_product.name,
        p_purchase_id,
        'product_sale'
    );

    -- 8️⃣ Mark purchase as completed
    UPDATE public.purchases
    SET
        status = 'completed',
        agent_id = v_agent_id,
        confirmed_at = now(),
        updated_at = now()
    WHERE id = p_purchase_id;

    RETURN json_build_object(
        'success', true,
        'message', 'Purchase approved and escrow released successfully.',
        'purchase_id', p_purchase_id
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$$;


--
-- TOC entry 618 (class 1255 OID 22512)
-- Name: finalize_purchase(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_purchase(p_purchase_id uuid, p_agent_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_purchase RECORD;
  v_product RECORD;
BEGIN
  -- 1. Get the purchase details, ensuring it's ready for finalization
  SELECT * INTO v_purchase FROM public.purchases 
  WHERE id = p_purchase_id AND status = 'shipped';

  -- If no purchase is found or it's not in 'shipped' status, exit.
  IF v_purchase IS NULL THEN
    RETURN FALSE;
  END IF;

  -- 2. Get product details to find the brand owner
  SELECT * INTO v_product FROM public.products WHERE id = v_purchase.product_id;
  IF v_product IS NULL THEN
    RETURN FALSE; -- Or raise an error, as this should not happen
  END IF;

  -- 3. Deduct coins from the buyer
  UPDATE public.profiles
  SET brandible_coins = brandible_coins - v_purchase.total_coins
  WHERE id = v_purchase.buyer_id;

  -- 4. Add coins to the brand (seller)
  UPDATE public.profiles
  SET brandible_coins = brandible_coins + v_purchase.total_coins
  WHERE id = v_product.brand_id;

  -- 5. Create the 'spent' transaction record for the buyer
  VALUES (v_purchase.buyer_id, 'spent', -v_purchase.total_coins, 'Purchased ' || v_product.name, p_purchase_id, 'product_purchase');

  -- 6. Create the 'earned' transaction record for the brand
  VALUES (v_product.brand_id, 'earned', v_purchase.total_coins, 'Sale of ' || v_product.name, p_purchase_id, 'product_sale');

  -- 7. Update the purchase record to its final state
  UPDATE public.purchases
  SET 
    status = 'completed',
    agent_id = p_agent_id,
    confirmed_at = NOW()
  WHERE id = p_purchase_id;

  RETURN TRUE;

END;
$$;


--
-- TOC entry 697 (class 1255 OID 93784)
-- Name: find_or_create_dm_chat(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_or_create_dm_chat(user_1_id uuid, user_2_id uuid, p_source_status_id uuid DEFAULT NULL::uuid, p_source_media_id uuid DEFAULT NULL::uuid, p_context_data jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    existing_chat_id UUID;
    user_1_type TEXT;
    user_2_type TEXT;
    final_brand_id UUID;
    final_influencer_id UUID;
BEGIN
    -- Look for an existing DM chat between the two users
    -- Check both directions since we don't know who is brand vs influencer
    SELECT id INTO existing_chat_id
    FROM chats
    WHERE (brand_id = user_1_id AND influencer_id = user_2_id)
       OR (brand_id = user_2_id AND influencer_id = user_1_id)
    LIMIT 1;

    -- If a chat is found, return its ID
    IF existing_chat_id IS NOT NULL THEN
        RETURN existing_chat_id;
    END IF;

    -- Get user types from profiles table
    SELECT user_type INTO user_1_type
    FROM profiles
    WHERE id = user_1_id;

    SELECT user_type INTO user_2_type
    FROM profiles
    WHERE id = user_2_id;

    -- Determine who is brand and who is influencer
    IF user_1_type = 'brand' THEN
        final_brand_id := user_1_id;
        final_influencer_id := user_2_id;
    ELSIF user_2_type = 'brand' THEN
        final_brand_id := user_2_id;
        final_influencer_id := user_1_id;
    ELSE
        -- If neither is explicitly a brand, treat user_1 as brand (fallback)
        -- You might want to raise an exception here instead
        final_brand_id := user_1_id;
        final_influencer_id := user_2_id;
    END IF;

    -- Create a new chat with correct role assignment
        brand_id, 
        influencer_id, 
        purchase_id,
        source_status_id,
        source_media_id,
        context_data
    )
    VALUES (
        final_brand_id, 
        final_influencer_id, 
        NULL,
        p_source_status_id,
        p_source_media_id,
        p_context_data
    )
    RETURNING id INTO existing_chat_id;
           
    RETURN existing_chat_id;
END;
$$;


--
-- TOC entry 658 (class 1255 OID 171154)
-- Name: generate_brand_media_share_link(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_brand_media_share_link(p_media_id uuid, p_referrer_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_brand_id uuid;
    v_brand_username text;
    v_share_link text;
    v_base_url text := 'https://shop.brandiblebms.com';
BEGIN
    -- Get brand_id from brand_wall_media
    SELECT bwm.brand_id
    INTO v_brand_id
    FROM public.brand_wall_media bwm
    WHERE bwm.id = p_media_id;

    IF v_brand_id IS NULL THEN
        RAISE EXCEPTION 'Brand media not found';
    END IF;

    -- Get brand username
    SELECT p.username
    INTO v_brand_username
    FROM public.brands b
    JOIN public.profiles p ON b.profile_id = p.id
    WHERE b.id = v_brand_id;

    IF v_brand_username IS NULL THEN
        RAISE EXCEPTION 'Brand profile not found';
    END IF;

    -- Construct the share link: /brand_username/wall?mediaId=...
    v_share_link := v_base_url || '/' || v_brand_username || '/wall?mediaId=' || p_media_id::text;

    RETURN v_share_link;
END;
$$;


--
-- TOC entry 526 (class 1255 OID 31380)
-- Name: generate_group_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_group_code() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_code text;
  v_exists boolean;
BEGIN
  LOOP
    v_code := upper(substring(md5(random()::text) from 1 for 6));
    SELECT exists(SELECT 1 FROM public.collaboration_groups WHERE group_code = v_code) INTO v_exists;
    IF NOT v_exists THEN
      RETURN v_code;
    END IF;
  END LOOP;
END;
$$;


--
-- TOC entry 577 (class 1255 OID 28920)
-- Name: generate_my_referral_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_my_referral_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_code TEXT;
    v_user_id UUID := auth.uid();
BEGIN
    -- Check if user is authenticated
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Check if user already has a code
    SELECT referral_code INTO v_code FROM public.profiles WHERE id = v_user_id;

    IF v_code IS NOT NULL THEN
        RETURN v_code;
    END IF;

    -- Generate a new unique referral code
    LOOP
        -- Generate a random 8-character alphanumeric code
        v_code := upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 8));
        
        -- Check if this code already exists
        EXIT WHEN NOT EXISTS (SELECT 1 FROM public.profiles WHERE referral_code = v_code);
    END LOOP;

    -- Update the user's profile with the new code
    UPDATE public.profiles 
    SET referral_code = v_code 
    WHERE id = v_user_id;

    RETURN v_code;
END;
$$;


--
-- TOC entry 621 (class 1255 OID 43979)
-- Name: generate_share_link(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_share_link(p_media_id uuid, p_referrer_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$DECLARE
    v_status_post_id uuid;
    v_brand_id uuid;
    v_business_phone_number text;
    v_share_link text;
    v_base_url text := 'https://shop.brandiblebms.com/share';
BEGIN
    -- Get status_post_id and brand ID
    SELECT sm.status_post_id, sp.brand_id
    INTO v_status_post_id, v_brand_id
    FROM public.status_media sm
    JOIN public.status_posts sp ON sm.status_post_id = sp.id
    WHERE sm.id = p_media_id;

    IF v_status_post_id IS NULL THEN
        RAISE EXCEPTION 'Media not found';
    END IF;

    -- Get brand's business phone number
    SELECT b.business_phone_number
    INTO v_business_phone_number
    FROM public.brands b
    WHERE b.profile_id = v_brand_id;

    -- Construct the share link with media_id
    v_share_link := v_base_url || '?media_id=' || p_media_id::text ||
                      '&referrer_id=' || p_referrer_id::text ||
                      '&brand_id=' || v_brand_id::text ||
                      '&status_id=' || v_status_post_id::text;

    IF v_business_phone_number IS NOT NULL THEN
        v_share_link := v_share_link || '&brand_phone=' || url_encode(v_business_phone_number);
    END IF;

    RETURN v_share_link;
END;$$;


--
