CREATE FUNCTION public.generate_unique_invite_code() RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_code TEXT;
    v_exists BOOLEAN;
BEGIN
    LOOP
        v_code := upper(substring(replace(uuid_generate_v4()::text, '-', '') from 1 for 6));
