END;
$$;


--
-- TOC entry 575 (class 1255 OID 196440)
-- Name: get_active_triggers_for_level(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_triggers_for_level(p_word_length integer) RETURNS TABLE(campaign_id uuid, trigger_word text, coin_reward numeric, campaign_name text, brand_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$BEGIN
  RETURN QUERY
  SELECT 
    gc.id,
    word,
    gc.coin_per_trigger,
    gc.campaign_name,
    p.full_name
  FROM game_campaigns gc
  JOIN profiles p ON gc.brand_id = p.id
  CROSS JOIN LATERAL unnest(gc.game_triggers) AS word
  WHERE gc.status = 'active'
    AND gc.expires_at > NOW()
    AND LENGTH(word) = p_word_length
    AND (
      SELECT COUNT(DISTINCT gci.influencer_id)
      FROM game_campaign_interactions gci
      WHERE gci.campaign_id = gc.id
      AND gci.trigger_word = word
      AND gci.success = true
    ) < gc.min_influencer_reach;
END;$$;


--
-- TOC entry 822 (class 1255 OID 219381)
-- Name: get_active_triggers_for_level(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_triggers_for_level(p_word_length integer, p_user_id uuid DEFAULT auth.uid()) RETURNS TABLE(campaign_id uuid, trigger_word text, coin_reward numeric, campaign_name text, brand_name text, source_hub_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$DECLARE
    v_user_state TEXT;
BEGIN
    -- Get the user's current state for location filtering
    SELECT p.state INTO v_user_state FROM public.profiles p WHERE p.id = p_user_id;

    RETURN QUERY
    SELECT 
        gc.id,
        word,
        gc.coin_per_trigger,
        gc.campaign_name,
        p.full_name,
        (
            SELECT h.name 
            FROM public.game_campaign_hubs gch
            JOIN public.hubs h ON h.id = gch.hub_id
            JOIN public.hub_members hm ON hm.hub_id = h.id
            WHERE gch.game_campaign_id = gc.id 
            AND hm.profile_id = p_user_id
            LIMIT 1
        ) as source_hub_name
    FROM public.game_campaigns gc
    JOIN public.profiles p ON gc.brand_id = p.id
    CROSS JOIN LATERAL unnest(gc.game_triggers) AS word
    WHERE gc.status = 'active'
      AND gc.expires_at > NOW()
      AND (
    SELECT COUNT(DISTINCT gci.influencer_id)
    FROM public.game_campaign_interactions gci
    WHERE gci.campaign_id = gc.id
    AND gci.trigger_word = word
    AND gci.success = true
) < gc.min_influencer_reach
      AND LENGTH(word) = p_word_length
      AND (
          -- RULE 1: Public Campaigns
          (gc.is_private = false)
          OR
          -- RULE 2: Targeted Communities (Check Hub Membership)
          (gc.is_private = true AND EXISTS (
              SELECT 1 FROM public.game_campaign_hubs gch
              JOIN public.hub_members hm ON hm.hub_id = gch.hub_id
              WHERE gch.game_campaign_id = gc.id
              AND hm.profile_id = p_user_id
          ))
      )
      AND (
          -- RULE 3: Surgical Location Filter
          array_length(gc.target_locations, 1) IS NULL 
          OR v_user_state = ANY(gc.target_locations)
      );
END;$$;


