CREATE FUNCTION public.get_all_blog_posts() RETURNS SETOF public.blog_posts
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_agent_id uuid;
    v_user_type text;
BEGIN
    SELECT auth.uid() INTO v_agent_id;
    SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_agent_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RAISE EXCEPTION 'Only agents can view all blog posts.';
    END IF;

    RETURN QUERY
    SELECT *
    FROM public.blog_posts
    ORDER BY created_at DESC;
END;
