--
-- TOC entry 557 (class 1255 OID 53790)
-- Name: get_app_setting(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_app_setting(setting_key text, fallback_value numeric) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result NUMERIC;
BEGIN
  -- This runs with postgres privileges, bypassing RLS
  SELECT COALESCE((value->>setting_key)::NUMERIC, fallback_value)
  INTO result
  FROM app_settings 
  WHERE key = 'referral_rewards'
  LIMIT 1;
  
  RETURN COALESCE(result, fallback_value);
EXCEPTION WHEN OTHERS THEN
  RETURN fallback_value;
END;
$$;


