CREATE FUNCTION public.get_brand_analytics(p_start_date text, p_end_date text) RETURNS TABLE(id uuid, title text, type text, view_count integer, participation_count integer, total_spend numeric, reward_limit integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    sp.id,
    sp.title,
    sp.type,
    sp.view_count,
    sp.participation_count,
    (sp.reward_amount * sp.current_rewards_given) as total_spend,
    sp.reward_limit
  FROM
    public.status_posts sp
  WHERE
    sp.brand_id = auth.uid()
    AND sp.created_at BETWEEN p_start_date::timestamptz AND p_end_date::timestamptz;
END;
$$;


