    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        bwa.event_type,
        COUNT(*) as event_count,
        COUNT(DISTINCT bwa.viewer_id) as unique_viewers
    FROM public.brand_wall_analytics bwa
    WHERE bwa.brand_id = p_brand_id
        AND bwa.created_at >= p_start_date
        AND bwa.created_at <= p_end_date
    GROUP BY bwa.event_type
    ORDER BY event_count DESC;
END;
$$;


--
-- TOC entry 739 (class 1255 OID 55462)
-- Name: get_chains_for_campaign(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_chains_for_campaign(p_campaign_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_brand_id UUID;
    v_result JSONB;
BEGIN
    -- Verify that the caller owns the campaign
    SELECT brand_id INTO v_brand_id
    FROM public.pass_it_campaigns
    WHERE id = p_campaign_id;

    IF NOT FOUND OR v_brand_id IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION 'Authorization error or campaign not found.';
    END IF;

    -- Aggregate chain data, now including a nested JSON array of passes
    SELECT jsonb_agg(chain_data ORDER BY chain_data.created_at DESC) -- Order the chains themselves
    INTO v_result
    FROM (
        SELECT
            c.id,
            c.status,
            c.is_winner,
            c.created_at,
            -- Get the starter influencer's profile
            jsonb_build_object(
                'id', s.id,
                'full_name', s.full_name,
                'username', s.username,
                'avatar_url', s.avatar_url
            ) AS starter_influencer,
            -- Aggregate all completed passes for this chain into a JSON array
            (
                SELECT COALESCE(jsonb_agg(pass_details ORDER BY pass_details.completed_at ASC), '[]'::jsonb) -- Corrected ORDER BY
                FROM (
                    SELECT
                        p.id AS pass_id,
                        p.rating,
                        p.review_text,
                        p.completed_at,
                        jsonb_build_object(
                            'id', pr.id,
                            'full_name', pr.full_name,
                            'username', pr.username,
                            'avatar_url', pr.avatar_url
                        ) AS reviewer
                    FROM public.pass_it_passes p
                    JOIN public.profiles pr ON p.reviewer_id = pr.id
                    WHERE p.chain_id = c.id AND p.status = 'completed'
                ) AS pass_details
            ) AS passes
        FROM
            public.pass_it_chains c
        JOIN
            public.profiles s ON c.starter_influencer_id = s.id
        WHERE
            c.campaign_id = p_campaign_id
    ) AS chain_data;

    RETURN COALESCE(v_result, '[]'::jsonb);

END;
$$;


