--
-- TOC entry 705 (class 1255 OID 22246)
-- Name: get_detailed_transactions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_detailed_transactions(p_user_id uuid) RETURNS TABLE(id uuid, created_at timestamp with time zone, type text, amount numeric, description text, reference_type text, brand_name text, campaign_title text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    t.id,
    t.created_at,
    t.type,
    t.amount,
    t.description,
    t.reference_type,
    -- Use COALESCE to get the first non-null brand name and title from the various joins
    COALESCE(p_sv.full_name, p_s.full_name, p_c.full_name, p_p.full_name) AS brand_name,
    COALESCE(sp_sv.title, sp_s.title, sp_c.title, p.name) AS campaign_title
  FROM
    transactions t
    -- Join for status_view
    LEFT JOIN status_posts sp_sv ON t.reference_type = 'status_view' AND t.reference_id = sp_sv.id
    LEFT JOIN profiles p_sv ON sp_sv.brand_id = p_sv.id
    -- Join for surveys
    LEFT JOIN surveys s ON t.reference_type = 'survey' AND t.reference_id = s.id
    LEFT JOIN status_posts sp_s ON s.status_post_id = sp_s.id
    LEFT JOIN profiles p_s ON sp_s.brand_id = p_s.id
    -- Join for challenges
    LEFT JOIN challenge_submissions cs ON t.reference_type = 'challenge' AND t.reference_id = cs.id
    LEFT JOIN challenges c ON cs.challenge_id = c.id
    LEFT JOIN status_posts sp_c ON c.status_post_id = sp_c.id
    LEFT JOIN profiles p_c ON sp_c.brand_id = p_c.id
    -- Join for product purchases
    LEFT JOIN purchases pu ON t.reference_type = 'product_purchase' AND t.reference_id = pu.id
    LEFT JOIN products p ON pu.product_id = p.id
    LEFT JOIN profiles p_p ON p.brand_id = p_p.id
  WHERE
    t.user_id = p_user_id
  ORDER BY
    t.created_at DESC
  LIMIT 50;
END;
$$;


--
-- TOC entry 674 (class 1255 OID 27252)
-- Name: get_discover_influencers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_discover_influencers() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN (
        SELECT json_agg(t)
        FROM (
            SELECT
                p.id,
                p.full_name,
                p.username,
                p.avatar_url,
                p.private_campaign_rate,
                COALESCE(SUM(cs.upvote_count), 0)::INTEGER AS total_upvotes,
                COALESCE(COUNT(cs.id) FILTER (WHERE cs.is_featured = true), 0)::INTEGER AS total_features
            FROM
                public.profiles p
            LEFT JOIN
                public.challenge_submissions cs ON p.id = cs.participant_id
            WHERE
                p.user_type = 'influencer'
                AND p.private_campaign_rate IS NOT NULL
            GROUP BY
                p.id
            ORDER BY
                total_upvotes DESC, total_features DESC
        ) t
    );
END;
$$;


--
-- TOC entry 592 (class 1255 OID 159666)
-- Name: get_facebook_ad_insights(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_facebook_ad_insights(p_ad_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$DECLARE
    insights_data JSONB;
    request_url TEXT;
    response JSONB;
    access_token TEXT;
    api_version TEXT;
BEGIN
    -- Get secret from Vault
    SELECT decrypted_secret INTO access_token
    FROM vault.decrypted_secrets
    WHERE name = 'facebook_access_token';
    
    api_version := 'v19.0';
    
    IF access_token IS NULL OR access_token = '' THEN
        RAISE EXCEPTION 'Facebook access token not found in vault';
    END IF;
    
    -- Construct the request URL with valid date_preset
    -- Valid options: today, yesterday, this_month, last_month, this_quarter, 
    -- maximum, last_3d, last_7d, last_14d, last_28d, last_30d, last_90d, 
    -- last_week_mon_sun, last_week_sun_sat, last_quarter, last_year, 
    -- this_week_mon_today, this_week_sun_today, this_year
    request_url := 'https://graph.facebook.com/' || api_version || '/' || p_ad_id || 
                   '/insights?access_token=' || access_token || 
                   '&fields=spend,impressions,clicks,reach,frequency,ctr,cpc,cpp' ||
                   '&date_preset=maximum';  -- 'maximum' gets all available data

    -- Make HTTP GET request
    SELECT content INTO response
    FROM extensions.http_get(request_url);

    -- Check if the response contains data
    IF response->'data' IS NOT NULL AND jsonb_array_length(response->'data') > 0 THEN
        insights_data := response->'data'->0;
    ELSE
        RAISE WARNING 'No insights data for ad_id %. Response: %', p_ad_id, response;
        insights_data := jsonb_build_object(
            'error', 'No data available', 
            'response', response
        );
    END IF;

    RETURN insights_data;

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Error fetching Facebook Ad insights for ad_id %: %', p_ad_id, SQLERRM;
        RETURN jsonb_build_object('error', 'Failed to fetch insights', 'details', SQLERRM);
END;$$;


--
-- TOC entry 755 (class 1255 OID 197656)
-- Name: get_game_reset_details(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_game_reset_details(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_game_balance DECIMAL;
    v_total_balance DECIMAL;
    v_penalty_percent DECIMAL;
    v_penalty_amount DECIMAL;
    v_current_max_level INTEGER;
BEGIN

    SELECT game_coins, brandible_coins 
    INTO v_game_balance, v_total_balance
    FROM public.profiles 
    WHERE id = p_user_id;

    SELECT value::DECIMAL 
    INTO v_penalty_percent
    FROM public.app_settings
    WHERE key = 'level_reset_penalty_percentage';

    IF v_penalty_percent IS NULL THEN
        v_penalty_percent := 50;
    END IF;

    v_penalty_amount := ROUND(
        COALESCE(v_game_balance,0) * (v_penalty_percent/100.0),
        2
    );

    SELECT max_level_reached
    INTO v_current_max_level
    FROM public.user_game_progress
    WHERE user_id = p_user_id;

    RETURN json_build_object(
        'current_game_balance', COALESCE(v_game_balance,0),
        'current_total_balance', COALESCE(v_total_balance,0),
        'penalty_percentage', v_penalty_percent,
        'penalty_amount', v_penalty_amount,
        'current_max_level', COALESCE(v_current_max_level,1),
        'can_afford', COALESCE(v_total_balance,0) >= v_penalty_amount
    );

END;
$$;


--
-- TOC entry 605 (class 1255 OID 218197)
-- Name: get_hub_by_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hub_by_code(p_code text) RETURNS TABLE(hub_name text, owner_full_name text, owner_username text, category text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        h.name,
        p.full_name,
        p.username,
        h.industry
    FROM public.hubs h
    JOIN public.profiles p ON h.owner_id = p.id
    WHERE h.invite_code = upper(p_code);
END;
$$;


--
-- TOC entry 707 (class 1255 OID 219588)
-- Name: get_hubs_leaderboard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hubs_leaderboard() RETURNS TABLE(id uuid, name text, description text, owner_username text, owner_full_name text, category text, keywords text[], member_count bigint, total_earned numeric, community_earned numeric, campaign_targets_count bigint, is_joined boolean, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        h.id,
        h.name,
        h.description,
        p.username as owner_username,
        p.full_name as owner_full_name,
        h.industry as category,
        h.keywords,
        (SELECT COUNT(*) FROM public.hub_members WHERE hub_id = h.id) as member_count,
        COALESCE((SELECT SUM(amount) FROM public.transactions WHERE (reference_type = 'hub_curation_fee' OR reference_type = 'curation_reward') AND user_id = h.owner_id), 0) as total_earned,
        COALESCE((SELECT SUM(amount) FROM public.transactions WHERE (reference_type IN ('hub_curation_fee', 'curation_reward', 'status_media_view', 'game_campaign', 'challenge_reward', 'survey_response', 'campaign_interaction')) AND reference_id IN (SELECT status_post_id::uuid FROM public.status_post_hubs WHERE hub_id = h.id UNION SELECT game_campaign_id::uuid FROM public.game_campaign_hubs WHERE hub_id = h.id)), 0) as community_earned,
        ((SELECT COUNT(*) FROM public.status_post_hubs WHERE hub_id = h.id) + (SELECT COUNT(*) FROM public.game_campaign_hubs WHERE hub_id = h.id)) as campaign_targets_count,
        EXISTS (SELECT 1 FROM public.hub_members WHERE hub_id = h.id AND profile_id = auth.uid()) as is_joined,
        h.state
    FROM public.hubs h
    JOIN public.profiles p ON h.owner_id = p.id
    ORDER BY community_earned DESC, member_count DESC;
END;
$$;


--
-- TOC entry 816 (class 1255 OID 62516)
-- Name: get_investor_dashboard_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_investor_dashboard_summary(p_user_id uuid) RETURNS TABLE(total_investment numeric, portfolio_value numeric, total_returns numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_investor_id UUID;
BEGIN
    SELECT investors.id INTO v_investor_id
    FROM public.investors
    WHERE investors.profile_id = p_user_id;

    IF v_investor_id IS NULL THEN
        total_investment := 0;
        portfolio_value := 0;
        total_returns := 0;
        RETURN NEXT;
        RETURN;
    END IF;

    SELECT COALESCE(SUM(investments.amount), 0)
    INTO total_investment
    FROM public.investments
    WHERE investments.investor_id = v_investor_id;

    SELECT COALESCE(SUM(returns_log.amount), 0)
    INTO total_returns
    FROM public.returns_log
    WHERE returns_log.investor_id = v_investor_id;

    portfolio_value := total_investment + total_returns;

    RETURN NEXT;
END;
$$;


--
-- TOC entry 752 (class 1255 OID 60208)
-- Name: get_investor_level(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_investor_level(p_user_id uuid) RETURNS TABLE(role_name text, interest_factor numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Check if user is an investor
    IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = p_user_id AND p.user_type = 'investor') THEN
        RETURN;
    END IF;

    -- Get investor level data
    RETURN QUERY
    SELECT 
        il.role_name,
        il.interest_factor
    FROM public.investors i
    JOIN public.investor_levels il ON i.level_id = il.id
    WHERE i.profile_id = p_user_id;
END;
$$;


--
-- TOC entry 746 (class 1255 OID 62542)
-- Name: get_investor_performance_data(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_investor_performance_data(p_user_id uuid) RETURNS TABLE(date date, value numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_investor_id UUID;
BEGIN
    SELECT investors.id INTO v_investor_id
    FROM public.investors
    WHERE investors.profile_id = p_user_id;

    IF v_investor_id IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH daily_activity AS (
        SELECT
            investments.investment_date AS activity_date,
            investments.amount AS investment_change
        FROM
            public.investments
        WHERE
            investments.investor_id = v_investor_id
        UNION ALL
        SELECT
            (returns_log.calculation_date)::date AS activity_date, -- Cast to date to match the other part of the UNION
            returns_log.amount AS investment_change
        FROM
            public.returns_log
        WHERE
            returns_log.investor_id = v_investor_id
    ),
    cumulative_value AS (
        SELECT
            daily_activity.activity_date AS date,
            SUM(daily_activity.investment_change) OVER (ORDER BY daily_activity.activity_date) AS cumulative_change
        FROM
            daily_activity
    )
    SELECT cumulative_value.date, cumulative_value.cumulative_change FROM cumulative_value;
END;
$$;


--
-- TOC entry 692 (class 1255 OID 62518)
-- Name: get_investor_recent_transactions(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_investor_recent_transactions(p_user_id uuid, p_limit integer DEFAULT 5) RETURNS TABLE(id uuid, date timestamp with time zone, description text, amount numeric, type text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_investor_profile_id UUID;
BEGIN
    SELECT profiles.id INTO v_investor_profile_id
    FROM public.profiles
    WHERE profiles.id = p_user_id AND profiles.user_type = 'investor';

    IF v_investor_profile_id IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        transactions.id,
        transactions.created_at,
        transactions.description,
        transactions.amount,
        transactions.type
    FROM
        public.transactions
    WHERE
        transactions.user_id = v_investor_profile_id
    ORDER BY
        transactions.created_at DESC
    LIMIT p_limit;
END;
$$;


