--
-- TOC entry 666 (class 1255 OID 85915)
-- Name: get_media_influencer_breakdown(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_media_influencer_breakdown(p_media_id uuid, p_start_date timestamp with time zone DEFAULT '-infinity'::timestamp with time zone, p_end_date timestamp with time zone DEFAULT 'infinity'::timestamp with time zone) RETURNS TABLE(influencer_id uuid, full_name text, username text, avatar_url text, total_clicks bigint, total_message_clicks bigint, conversion_rate numeric, did_view boolean, did_share boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH influencer_actions AS (
    SELECT 
      CASE 
        -- ✅ UPDATE: Read 'referrer_id' from the 'details' column
        -- We cast 'details' to jsonb just in case it's stored as text, then extract the field
        WHEN al.action_type IN ('share_link_clicked', 'share_message_clicked') 
        THEN (al.details->>'referrer_id')::UUID
        
        -- For 'media_viewed' and 'content_shared', use the user_id directly
        ELSE al.user_id
      END as influencer_id,
      al.action_type
    FROM activity_logs al
    WHERE al.entity_id = p_media_id
      AND al.timestamp BETWEEN p_start_date AND p_end_date
      AND al.action_type IN ('media_viewed', 'content_shared', 'share_link_clicked', 'share_message_clicked')
  )
  SELECT 
    p.id as influencer_id,
    COALESCE(p.full_name, 'Unknown User') as full_name,
    COALESCE(p.username, 'unknown') as username,
    COALESCE(p.avatar_url, '') as avatar_url,
    
    -- Count Clicks
    COUNT(CASE WHEN ia.action_type = 'share_link_clicked' THEN 1 END) as total_clicks,
    
    -- Count Message Clicks
    COUNT(CASE WHEN ia.action_type = 'share_message_clicked' THEN 1 END) as total_message_clicks,
    
    -- Calculate Conversion Rate
    CASE 
      WHEN COUNT(CASE WHEN ia.action_type = 'share_link_clicked' THEN 1 END) > 0 
      THEN (COUNT(CASE WHEN ia.action_type = 'share_message_clicked' THEN 1 END)::NUMERIC / 
            COUNT(CASE WHEN ia.action_type = 'share_link_clicked' THEN 1 END)::NUMERIC) * 100
      ELSE 0
    END as conversion_rate,
    
    -- Check Booleans
    COALESCE(BOOL_OR(ia.action_type = 'media_viewed'), false) as did_view,
    COALESCE(BOOL_OR(ia.action_type = 'content_shared'), false) as did_share
    
  FROM influencer_actions ia
  JOIN profiles p ON p.id = ia.influencer_id
  WHERE ia.influencer_id IS NOT NULL
  GROUP BY p.id, p.full_name, p.username, p.avatar_url
  
  -- Filter: Only show influencers who have at least one interaction
  HAVING COUNT(CASE WHEN ia.action_type IN ('content_shared', 'share_link_clicked', 'share_message_clicked') THEN 1 END) > 0
  
  ORDER BY total_message_clicks DESC, total_clicks DESC;
END;
$$;


--
-- TOC entry 619 (class 1255 OID 87470)
-- Name: get_media_roi_overview(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_media_roi_overview(p_brand_id uuid, p_start_date timestamp with time zone DEFAULT '-infinity'::timestamp with time zone, p_end_date timestamp with time zone DEFAULT 'infinity'::timestamp with time zone) RETURNS TABLE(media_id uuid, media_url text, media_type text, status_post_id uuid, status_post_title text, total_spend numeric, total_views bigint, total_shares bigint, total_clicks bigint, total_message_clicks bigint, conversion_rate numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    sm.id as media_id,
    COALESCE(sm.media_url, '') as media_url,
    COALESCE(sm.media_type, 'media') as media_type,
    sm.status_post_id,
    COALESCE(sp.title, 'Untitled') as status_post_title,
    
    -- Financials: Reward Amount * Rewards Given
    COALESCE((sp.reward_amount * sp.current_rewards_given), 0) as total_spend,
    
    -- Views
    COALESCE(sp.view_count, 0)::BIGINT as total_views,
    
    -- 1. Count Shares (Unique users who performed 'content_shared')
    COUNT(DISTINCT CASE WHEN al.action_type = 'content_shared' THEN al.user_id END) as total_shares,
    
    -- 2. Count Clicks (Any 'share_link_clicked' event)
    COUNT(CASE WHEN al.action_type = 'share_link_clicked' THEN 1 END) as total_clicks,
    
    -- 3. Count Message Clicks (Any 'share_message_clicked' event)
    COUNT(CASE WHEN al.action_type = 'share_message_clicked' THEN 1 END) as total_message_clicks,
    
    -- 4. Conversion Rate (Message Clicks / Link Clicks)
    CASE 
      WHEN COUNT(CASE WHEN al.action_type = 'share_link_clicked' THEN 1 END) > 0 
      THEN (COUNT(CASE WHEN al.action_type = 'share_message_clicked' THEN 1 END)::NUMERIC / 
            COUNT(CASE WHEN al.action_type = 'share_link_clicked' THEN 1 END)::NUMERIC) * 100
      ELSE 0
    END as conversion_rate

  FROM status_media sm
  JOIN status_posts sp ON sm.status_post_id = sp.id
  
  -- Join logs safely (casting entity_id to uuid) and filter logs by date
  LEFT JOIN activity_logs al ON al.entity_id::uuid = sm.id 
    AND al.timestamp BETWEEN p_start_date AND p_end_date
    AND al.action_type IN ('content_shared', 'share_link_clicked', 'share_message_clicked')
    
  WHERE sp.brand_id = p_brand_id
  
  GROUP BY 
    sm.id, 
    sm.media_url, 
    sm.media_type, 
    sm.status_post_id, 
    sp.title, 
    sp.reward_amount, 
    sp.current_rewards_given, 
    sp.view_count
    
  ORDER BY total_message_clicks DESC, total_clicks DESC;
END;
$$;


