--
-- TOC entry 726 (class 1255 OID 55348)
-- Name: get_my_invitations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_invitations() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_invitations json;
BEGIN
    SELECT
        json_agg(
            json_build_object(
                'id', inv.id,
                'campaign_id', inv.campaign_id,
                'chain_id', inv.chain_id,
                'inviter_id', inv.inviter_id,
                'invitee_id', inv.invitee_id,
                'position_in_chain', inv.position_in_chain,
                'status', inv.status,
                'created_at', inv.created_at,
                'expires_at', inv.expires_at,
                'responded_at', inv.responded_at,
                'pass_it_campaigns', json_build_object(
                    'id', pc.id,
                    'title', pc.title,
                    'artwork_url', pc.artwork_url
                ),
                'profiles', json_build_object(
                    'full_name', p.full_name
                )
            )
        )
    INTO
        v_invitations
    FROM
        public.pass_it_invitations inv
    LEFT JOIN
        public.pass_it_campaigns pc ON inv.campaign_id = pc.id
    LEFT JOIN
        public.profiles p ON inv.inviter_id = p.id
    WHERE
        inv.invitee_id = auth.uid();

    RETURN COALESCE(v_invitations, '[]'::json);
END;
$$;


--
-- TOC entry 505 (class 1255 OID 218231)
