--

CREATE FUNCTION public.get_my_joined_hubs() RETURNS TABLE(hub_id uuid, hub_name text, hub_description text, owner_full_name text, owner_username text, category text, keywords text[], joined_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        h.id,
        h.name,
        h.description,
        p.full_name,
        p.username,
        h.industry,
        h.keywords, -- Added keywords
        hm.joined_at
