--

CREATE FUNCTION public.get_my_passes() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_passes json;
BEGIN
    SELECT
        json_agg(
            json_build_object(
                'id', p.id,
                'chain_id', p.chain_id,
                'campaign_id', p.campaign_id,
                'reviewer_id', p.reviewer_id,
                'position_in_chain', p.position_in_chain,
                'status', p.status,
                'rating', p.rating,
                'review_text', p.review_text,
                'created_at', p.created_at,
                'completed_at', p.completed_at,
                'campaign', json_build_object(
                    'id', pc.id,
                    'title', pc.title,
