--
-- TOC entry 572 (class 1255 OID 55504)
-- Name: get_pass_details_for_influencer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pass_details_for_influencer(p_pass_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_influencer_id UUID := auth.uid();
    v_pass_details JSONB;
BEGIN
    -- Fetch pass details and associated campaign information
    SELECT
        jsonb_build_object(
            'id', p.id,
            'chain_id', p.chain_id,
            'campaign_id', p.campaign_id,
            'reviewer_id', p.reviewer_id,
            'position_in_chain', p.position_in_chain,
            'status', p.status,
            'rating', p.rating,
            'review_text', p.review_text,
            'created_at', p.created_at,
            'completed_at', p.completed_at,
            'next_influencer_id', p.next_influencer_id,
            'pass_it_campaigns', jsonb_build_object(
                'id', pc.id,
                'title', pc.title,
                'description', pc.description,
                'artwork_url', pc.artwork_url,
                'artwork_type', pc.artwork_type,
                'target_passes', pc.target_passes,
                'reward_pool', pc.reward_pool,
                'campaign_type', pc.campaign_type,
                'expires_at', pc.expires_at,
                'status', pc.status
            )
        )
    INTO v_pass_details
    FROM
        public.pass_it_passes p
    LEFT JOIN
        public.pass_it_campaigns pc ON p.campaign_id = pc.id
    WHERE
        p.id = p_pass_id
        AND p.reviewer_id = v_influencer_id; -- Ensure the pass belongs to the current influencer

    IF v_pass_details IS NULL THEN
        RAISE EXCEPTION 'Pass not found or not accessible by current user.';
    END IF;

    RETURN v_pass_details;
END;
$$;


--
-- TOC entry 808 (class 1255 OID 54768)
-- Name: get_pass_it_chain_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pass_it_chain_stats(chain_uuid uuid) RETURNS TABLE(chain_id uuid, current_passes integer, target_passes integer, completion_percentage numeric, avg_rating numeric, total_reviews integer, is_winner boolean, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ch.id,
        ch.current_passes,
        c.target_passes,
        ROUND((ch.current_passes::NUMERIC / c.target_passes::NUMERIC) * 100, 2),
        COALESCE(AVG(p.rating), 0),
        COUNT(p.id)::INTEGER,
        ch.is_winner,
        ch.status::TEXT
    FROM pass_it_chains ch
    JOIN pass_it_campaigns c ON ch.campaign_id = c.id
    LEFT JOIN pass_it_passes p ON ch.id = p.chain_id AND p.status = 'completed'
    WHERE ch.id = chain_uuid
    GROUP BY ch.id, c.target_passes;
END;
$$;


--
-- TOC entry 698 (class 1255 OID 62856)
-- Name: get_poll_details_for_agent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_poll_details_for_agent(p_poll_id uuid) RETURNS TABLE(id uuid, question text, description text, created_at timestamp with time zone, closes_at timestamp with time zone, status text, author_id uuid, author_full_name text, options jsonb, total_votes bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_agent_id uuid;
    v_user_type text;
BEGIN
    -- Re-introduce agent check
    SELECT auth.uid() INTO v_agent_id;
    SELECT user_type INTO v_user_type FROM public.profiles WHERE public.profiles.id = v_agent_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RAISE EXCEPTION 'Only agents can view poll details.';
    END IF;

    RETURN QUERY
    SELECT
        p.id,
        p.question,
        p.description,
        p.created_at,
        p.closes_at,
        p.status,
        p.author_id,
        prof.full_name AS author_full_name,
        COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'id', po.id,
                        'option_text', po.option_text,
                        'votes', (SELECT COUNT(*) FROM public.poll_votes pv WHERE pv.poll_option_id = po.id)
                    )
                )
                FROM public.poll_options po
                WHERE po.poll_id = p.id
            ),
            '[]'::jsonb
        ) AS options,
        COUNT(pv_main.id) AS total_votes
    FROM public.polls p
    LEFT JOIN public.profiles prof ON p.author_id = prof.id
    LEFT JOIN public.poll_votes pv_main ON pv_main.poll_id = p.id
    WHERE p.id = p_poll_id
    GROUP BY p.id, prof.full_name;
END;
$$;


--
-- TOC entry 510 (class 1255 OID 63012)
-- Name: get_poll_details_for_investor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_poll_details_for_investor(_poll_id uuid) RETURNS TABLE(poll_id uuid, question text, description text, created_at timestamp with time zone, closes_at timestamp with time zone, status text, author_id uuid, author_full_name text, poll_options jsonb, user_vote_option_id uuid, poll_results jsonb, total_votes bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_id uuid := auth.uid();
    v_poll_status text;
    v_is_poll_closed boolean;
BEGIN
    RAISE NOTICE 'Function called for _poll_id: %', _poll_id;
    RAISE NOTICE 'User ID: %', v_user_id;

    -- Get basic poll info and check status
    SELECT p.status, (p.closes_at IS NOT NULL AND p.closes_at < NOW())
    INTO v_poll_status, v_is_poll_closed
    FROM public.polls p
    WHERE p.id = _poll_id;

    RAISE NOTICE 'Poll Status: %, Is Closed: %', v_poll_status, v_is_poll_closed;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Poll not found.';
    END IF;

    RETURN QUERY
    SELECT
        p.id AS poll_id,
        p.question,
        p.description,
        p.created_at,
        p.closes_at,
        p.status,
        p.author_id,
        prof.full_name AS author_full_name,
        (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', po.id,
                    'option_text', po.option_text
                )
            )
            FROM public.poll_options po
            WHERE po.poll_id = p.id
        ) AS poll_options,
        (
            SELECT pv.poll_option_id
            FROM public.poll_votes pv
            WHERE pv.poll_id = p.id AND pv.voter_id = v_user_id
        ) AS user_vote_option_id,
        CASE
            WHEN v_is_poll_closed OR (v_user_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.poll_votes WHERE public.poll_votes.poll_id = p.id AND voter_id = v_user_id)) THEN
                (
                    SELECT jsonb_agg(
                        jsonb_build_object(
                            'option_id', po.id,
                            'option_text', po.option_text,
                            'votes', COALESCE(vote_counts.count, 0),
                            'percentage', (COALESCE(vote_counts.count, 0)::numeric * 100 / NULLIF(total_poll_votes.total, 0))
                        )
                    )
                    FROM public.poll_options po
                    LEFT JOIN (
                        SELECT poll_option_id, COUNT(id) AS count
                        FROM public.poll_votes
                        WHERE poll_id = p.id
                        GROUP BY poll_option_id
                    ) AS vote_counts ON po.id = vote_counts.poll_option_id
                    LEFT JOIN (
                        SELECT COUNT(id) AS total
                        FROM public.poll_votes
                        WHERE poll_id = p.id
                    ) AS total_poll_votes ON TRUE
                    WHERE po.poll_id = p.id
                )
            ELSE NULL
        END AS poll_results,
        (SELECT COUNT(id) FROM public.poll_votes WHERE public.poll_votes.poll_id = p.id) AS total_votes
    FROM public.polls p
    JOIN public.profiles prof ON p.author_id = prof.id
    WHERE p.id = _poll_id;
END;
$$;


