--
-- TOC entry 583 (class 1255 OID 48112)
-- Name: get_share_earn_metrics(timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_share_earn_metrics(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_brand_id uuid) RETURNS TABLE(total_shares bigint, total_clicks bigint, total_message_clicks bigint, total_conversions bigint, click_to_message_rate numeric, conversion_rate numeric, total_rewards_distributed numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_total_shares bigint;
    v_total_clicks bigint;
    v_total_message_clicks bigint;
    v_total_conversions bigint;
    v_click_to_message_rate numeric;
    v_conversion_rate numeric;
    v_total_rewards numeric;
BEGIN
    -- Count content_shared events (top of funnel)
    SELECT COUNT(*)
    INTO v_total_shares
    FROM public.activity_logs al
    WHERE al.action_type = 'content_shared'
        AND al.details->>'brand_id' = p_brand_id::text
        AND al.timestamp >= p_start_date
        AND al.timestamp <= p_end_date;

    -- Count share_link_clicked events (middle of funnel)
    SELECT COUNT(*)
    INTO v_total_clicks
    FROM public.activity_logs al
    WHERE al.action_type = 'share_link_clicked'
        AND al.details->>'brand_id' = p_brand_id::text
        AND al.timestamp >= p_start_date
        AND al.timestamp <= p_end_date;

    -- Count share_message_clicked events (alternative engagement path)
    SELECT COUNT(*)
    INTO v_total_message_clicks
    FROM public.activity_logs al
    WHERE al.action_type = 'share_message_clicked'
        AND al.details->>'brand_id' = p_brand_id::text
        AND al.timestamp >= p_start_date
        AND al.timestamp <= p_end_date;

    -- Count share_conversion events (bottom of funnel)
    SELECT COUNT(*)
    INTO v_total_conversions
    FROM public.activity_logs al
    WHERE al.action_type = 'share_conversion'
        AND al.details->>'brand_id' = p_brand_id::text
        AND al.timestamp >= p_start_date
        AND al.timestamp <= p_end_date;

    -- Calculate click to message rate (message clicks / total clicks * 100)
    IF v_total_clicks > 0 THEN
        v_click_to_message_rate := ROUND((v_total_message_clicks::numeric / v_total_clicks::numeric * 100), 2);
    ELSE
        v_click_to_message_rate := 0;
    END IF;

    -- Calculate conversion rate (conversions / clicks * 100)
    IF v_total_clicks > 0 THEN
        v_conversion_rate := ROUND((v_total_conversions::numeric / v_total_clicks::numeric * 100), 2);
    ELSE
        v_conversion_rate := 0;
    END IF;

    -- Sum total rewards distributed (from share_conversion events)
    SELECT COALESCE(SUM(
        (al.details->>'total_reward_amount')::numeric
    ), 0)
    INTO v_total_rewards
    FROM public.activity_logs al
    WHERE al.action_type = 'share_conversion'
        AND al.details->>'brand_id' = p_brand_id::text
        AND al.timestamp >= p_start_date
        AND al.timestamp <= p_end_date;

    -- Return the metrics
    RETURN QUERY
    SELECT
        v_total_shares,
        v_total_clicks,
        v_total_message_clicks,
        v_total_conversions,
        v_click_to_message_rate,
        v_conversion_rate,
        v_total_rewards;
END;
$$;


--
-- TOC entry 586 (class 1255 OID 28602)
-- Name: get_top_influencers_for_brand(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_top_influencers_for_brand(p_start_date text, p_end_date text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN (
        SELECT json_agg(t)
        FROM (
            SELECT
                p.id,
                p.full_name,
                p.username,
                p.avatar_url,
                COUNT(cs.id) AS engagement_count
            FROM
                public.profiles p
            JOIN
                public.challenge_submissions cs ON p.id = cs.participant_id
            JOIN
                public.challenges c ON cs.challenge_id = c.id
            JOIN
                public.status_posts sp ON c.status_post_id = sp.id
            WHERE
                sp.brand_id = auth.uid()
                AND cs.submitted_at >= p_start_date::TIMESTAMP WITH TIME ZONE
                AND cs.submitted_at <= p_end_date::TIMESTAMP WITH TIME ZONE
            GROUP BY
                p.id
            ORDER BY
                engagement_count DESC
            LIMIT 10
        ) t
    );
END;
$$;


--
-- TOC entry 796 (class 1255 OID 48113)
-- Name: get_top_share_earners(timestamp with time zone, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_top_share_earners(p_start_date timestamp with time zone, p_end_date timestamp with time zone, p_brand_id uuid, p_limit integer DEFAULT 5) RETURNS TABLE(influencer_id uuid, full_name text, username text, avatar_url text, share_count bigint, click_count bigint, message_click_count bigint, conversion_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Return top influencers by conversion count with all engagement metrics
    RETURN QUERY
    WITH share_data AS (
        -- Get all share-related events for this brand in the date range
        SELECT
            al.details->>'referrer_id' as referrer_id,
            COUNT(CASE WHEN al.action_type = 'content_shared' THEN 1 END) as shares,
            COUNT(CASE WHEN al.action_type = 'share_link_clicked' THEN 1 END) as clicks,
            COUNT(CASE WHEN al.action_type = 'share_message_clicked' THEN 1 END) as message_clicks,
            COUNT(CASE WHEN al.action_type = 'share_conversion' THEN 1 END) as conversions
        FROM public.activity_logs al
        WHERE al.details->>'brand_id' = p_brand_id::text
            AND al.action_type IN ('content_shared', 'share_link_clicked', 'share_message_clicked', 'share_conversion')
            AND al.timestamp >= p_start_date
            AND al.timestamp <= p_end_date
        GROUP BY al.details->>'referrer_id'
        HAVING COUNT(CASE WHEN al.action_type = 'share_conversion' THEN 1 END) > 0
    )
    SELECT
        (sd.referrer_id)::uuid,
        p.full_name,
        p.username,
        p.avatar_url,
        sd.shares,
        sd.clicks,
        sd.message_clicks,
        sd.conversions
    FROM share_data sd
    JOIN public.profiles p ON p.id = (sd.referrer_id)::uuid
    ORDER BY sd.conversions DESC, sd.clicks DESC, sd.shares DESC
    LIMIT p_limit;
END;
$$;


