CREATE FUNCTION public.get_unboxed_submission_summary(p_submission_id uuid) RETURNS TABLE(submission_id uuid, influencer_name text, brand_name text, status text, total_sales integer, total_earned numeric, reserved_budget numeric, reward_per_sale numeric, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        us.id,
        p_inf.display_name,
        p_br.display_name,
        us.status,
        us.total_sales_count,
        us.total_earned_by_influencer,
        us.reserved_budget,
        us.referral_reward,
        us.created_at,
        us.updated_at
    FROM public.unboxed_submissions us
    LEFT JOIN public.profiles p_inf ON us.influencer_id = p_inf.id
    LEFT JOIN public.brands b ON us.brand_id = b.profile_id
    LEFT JOIN public.profiles p_br ON b.profile_id = p_br.id
    WHERE us.id = p_submission_id;
END;
$$;


