--
-- TOC entry 710 (class 1255 OID 218237)
-- Name: get_visible_status_posts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_visible_status_posts(p_user_id uuid) RETURNS TABLE(id uuid, brand_id uuid, type text, title text, description text, reward_amount numeric, reward_limit integer, current_rewards_given integer, expires_at timestamp with time zone, created_at timestamp with time zone, is_private boolean, target_locations text[], source_hub_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_state TEXT;
BEGIN
    -- 1. Get the user's current state for location filtering
    SELECT p.state INTO v_user_state FROM public.profiles p WHERE p.id = p_user_id;

    RETURN QUERY
    SELECT 
        sp.id as id,
        sp.brand_id as brand_id,
        sp.type as type,
        sp.title as title,
        sp.description as description,
        sp.reward_amount as reward_amount,
        sp.reward_limit as reward_limit,
        sp.current_rewards_given as current_rewards_given,
        sp.expires_at as expires_at,
        sp.created_at as created_at,
        sp.is_private as is_private,
        sp.target_locations as target_locations,
        (
            SELECT h.name 
            FROM public.status_post_hubs sph
            JOIN public.hubs h ON h.id = sph.hub_id
            JOIN public.hub_members hm ON hm.hub_id = h.id
            WHERE sph.status_post_id = sp.id 
            AND hm.profile_id = p_user_id
            LIMIT 1
        ) as source_hub_name
    FROM public.status_posts sp
    WHERE 
        sp.is_active = true
        AND sp.expires_at > NOW()
        AND (
            -- RULE 1: Public Campaigns
            (sp.is_private = false)
            OR
            -- RULE 2: Targeted Communities (Check Hub Membership)
            (sp.is_private = true AND EXISTS (
                SELECT 1 FROM public.status_post_hubs sph
                JOIN public.hub_members hm ON hm.hub_id = sph.hub_id
                WHERE sph.status_post_id = sp.id
                AND hm.profile_id = p_user_id
            ))
        )
        AND (
            -- RULE 3: Surgical Location Filter
            array_length(sp.target_locations, 1) IS NULL 
            OR v_user_state = ANY(sp.target_locations)
        )
    ORDER BY sp.created_at DESC;
END;
$$;


