--
-- TOC entry 684 (class 1255 OID 17703)
-- Name: give_challenge_reward(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.give_challenge_reward(p_submission_id uuid, p_participant_id uuid, p_reward_amount numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_status_post_id UUID;
BEGIN
  -- Get the parent status_post_id from the submission
  SELECT c.status_post_id INTO v_status_post_id 
  FROM challenges c JOIN challenge_submissions cs ON c.id = cs.challenge_id 
  WHERE cs.id = p_submission_id;

  -- Give reward to user
  UPDATE profiles 
  SET brandible_coins = brandible_coins + p_reward_amount,
      total_earned = total_earned + p_reward_amount
  WHERE id = p_participant_id;
  
  -- Record transaction
    user_id, 
    type, 
    amount, 
    description, 
    reference_id, 
    reference_type,
    status_post_id
  ) VALUES (
    p_participant_id,
    'earned',
    p_reward_amount,
    'Reward for approved challenge submission',
    p_submission_id,
    'challenge',
    v_status_post_id
  );
  
  -- Mark submission as rewarded
  UPDATE challenge_submissions 
  SET reward_given = TRUE
  WHERE id = p_submission_id;
  
  RETURN TRUE;
END;
$$;


--
-- TOC entry 817 (class 1255 OID 20863)
-- Name: give_status_reward(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.give_status_reward(p_status_id uuid, p_viewer_id uuid, p_reward_amount integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_current_rewards_given INT;
  v_reward_limit INT;
BEGIN
  -- Authoritative check on the server to prevent race conditions
  SELECT current_rewards_given, reward_limit
  INTO v_current_rewards_given, v_reward_limit
  FROM public.status_posts
  WHERE id = p_status_id;

  -- Only proceed if the reward limit has not been reached
  IF v_current_rewards_given < v_reward_limit THEN
    -- Proceed with the updates
    UPDATE public.status_posts
    SET current_rewards_given = current_rewards_given + 1
    WHERE id = p_status_id;

    UPDATE public.profiles
    SET brandible_coins = brandible_coins + p_reward_amount
    WHERE id = p_viewer_id;

    UPDATE public.status_views
    SET reward_given = TRUE
    WHERE status_post_id = p_status_id AND viewer_id = p_viewer_id;
  END IF;
END;
$$;


--
-- TOC entry 632 (class 1255 OID 17701)
-- Name: give_status_reward(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.give_status_reward(p_status_id uuid, p_viewer_id uuid, p_reward_amount numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_current_rewards INTEGER;
  v_reward_limit INTEGER;
  v_reserved_funds NUMERIC;
BEGIN
  -- Get current reward count and limit with row lock
  SELECT current_rewards_given, reward_limit, reserved_funds
  INTO v_current_rewards, v_reward_limit, v_reserved_funds
  FROM status_posts 
  WHERE id = p_status_id
  FOR UPDATE;
  
  -- Check if reward limit reached
  IF v_current_rewards >= v_reward_limit OR v_reserved_funds < p_reward_amount THEN
    RETURN FALSE;
  END IF;
  
  -- Give reward to user
  UPDATE profiles 
  SET brandible_coins = brandible_coins + p_reward_amount,
      total_earned = total_earned + p_reward_amount
  WHERE id = p_viewer_id;
  
  -- Update status post reward count AND decrement reserved_funds
  UPDATE status_posts 
  SET 
    current_rewards_given = current_rewards_given + 1,
    reserved_funds = GREATEST(0, reserved_funds - p_reward_amount)
  WHERE id = p_status_id;
  
  -- Record transaction
    user_id, 
    type, 
    amount, 
    description, 
    reference_id, 
    reference_type
  ) VALUES (
    p_viewer_id,
    'earned',
    p_reward_amount,
    'Reward for viewing status',
    p_status_id,
    'status_view'
  );
  
  RETURN TRUE;
END;
$$;


--
-- TOC entry 712 (class 1255 OID 219459)
-- Name: give_survey_reward(uuid, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.give_survey_reward(p_survey_id uuid, p_respondent_id uuid, p_reward_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$DECLARE
  v_status_post_id UUID;
  v_reward_limit INTEGER;
  v_current_rewards INTEGER;
  v_reserved_funds NUMERIC;
  v_can_give_reward BOOLEAN;
  v_hub_owner_id UUID;
  v_curation_fee NUMERIC := 0;
  v_total_payout NUMERIC;
BEGIN
  -- 1. Get survey info with lock
  SELECT sp.id, sp.reward_limit, sp.current_rewards_given, sp.reserved_funds
  INTO v_status_post_id, v_reward_limit, v_current_rewards, v_reserved_funds
  FROM public.surveys s
  JOIN public.status_posts sp ON sp.id = s.status_post_id
  WHERE s.id = p_survey_id
  FOR UPDATE;

  IF v_status_post_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Survey or status post not found');
  END IF;

  -- 2. Check for hub curation fee
  SELECT h.owner_id INTO v_hub_owner_id
  FROM public.status_post_hubs sph
  JOIN public.hubs h ON h.id = sph.hub_id
  JOIN public.hub_members hm ON hm.hub_id = h.id
  WHERE sph.status_post_id = v_status_post_id 
  AND hm.profile_id = p_respondent_id
  LIMIT 1;

  -- 3. Calculate fees (only if hub owner is different from respondent)
  IF v_hub_owner_id IS NOT NULL AND v_hub_owner_id != p_respondent_id THEN
    v_curation_fee := p_reward_amount * 0.1;
  END IF;

  v_total_payout := p_reward_amount + v_curation_fee;

  -- 4. Check if reward can be given
  v_can_give_reward := (v_current_rewards IS NULL OR v_current_rewards < v_reward_limit) 
                       AND v_reserved_funds >= v_total_payout;

  -- 5. Update status_post counters
  UPDATE public.status_posts
  SET
    participation_count = COALESCE(participation_count, 0) + 1,
    current_rewards_given = CASE
      WHEN v_can_give_reward THEN COALESCE(current_rewards_given, 0) + 1
      ELSE current_rewards_given
    END,
    reserved_funds = CASE
      WHEN v_can_give_reward THEN GREATEST(0, reserved_funds - v_total_payout)
      ELSE reserved_funds
    END
  WHERE id = v_status_post_id;

  -- 6. Give rewards if eligible
  IF v_can_give_reward THEN
    -- Pay respondent
    UPDATE public.profiles
    SET brandible_coins = brandible_coins + p_reward_amount,
        total_earned = total_earned + p_reward_amount
    WHERE id = p_respondent_id;

    VALUES (p_respondent_id, 'earned', p_reward_amount, 'Reward for completing survey', p_survey_id, 'survey_response');

    -- Pay hub owner curation fee
    IF v_curation_fee > 0 THEN
        UPDATE public.profiles 
        SET brandible_coins = brandible_coins + v_curation_fee,
            total_earned = total_earned + v_curation_fee
        WHERE id = v_hub_owner_id;

        VALUES (v_hub_owner_id, 'earned', v_curation_fee, 'Survey curation fee from member completion', p_survey_id, 'hub_curation_fee');
    END IF;
  END IF;
  
  -- 7. Mark survey response as processed (FIXED: missing from updated version)
  UPDATE survey_responses 
  SET reward_given = v_can_give_reward,
      completed_at = NOW()  -- Optional: add timestamp
  WHERE survey_id = p_survey_id AND respondent_id = p_respondent_id;
  
  -- 8. Return result
  RETURN jsonb_build_object(
    'success', true,
    'reward_given', v_can_give_reward,
    'reward_amount', CASE WHEN v_can_give_reward THEN p_reward_amount ELSE 0 END,
    'curation_fee', v_curation_fee,
    'total_payout', CASE WHEN v_can_give_reward THEN v_total_payout ELSE 0 END,
    'hub_owner_id', v_hub_owner_id,
    'status_post_id', v_status_post_id
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;$$;


--
-- TOC entry 834 (class 1255 OID 28774)
-- Name: handle_invite_response_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_invite_response_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_brand_profile public.profiles;
  v_influencer_name TEXT;
  v_campaign_title TEXT;
  v_payload JSON;
BEGIN
  -- Only process when status changes to 'accepted'
  IF TG_OP = 'UPDATE' AND NEW.status = 'accepted' AND OLD.status != 'accepted' THEN
    
    -- Fetch campaign title and influencer name
    SELECT sp.title, p.full_name
    INTO v_campaign_title, v_influencer_name
    FROM public.status_posts sp
    JOIN public.profiles p ON p.id = NEW.influencer_id
    WHERE sp.id = NEW.status_post_id;

    -- Fetch brand profile
    SELECT p.*
    INTO v_brand_profile
    FROM public.profiles p
    JOIN public.status_posts sp ON p.id = sp.brand_id
    WHERE sp.id = NEW.status_post_id;

    -- Send notification if enabled
    IF v_brand_profile.push_token IS NOT NULL
      AND (v_brand_profile.notification_preferences->>'invite_accepted')::boolean THEN
      
      v_payload := json_build_object(
        'to', v_brand_profile.push_token,
        'title', 'Invitation Accepted!',
        'body', v_influencer_name || ' has accepted your invitation to the "' || v_campaign_title || '" campaign.',
        'data', json_build_object('status_post_id', NEW.status_post_id)
      );

      PERFORM net.http_post(
        url := 'https://exp.host/--/api/v2/push/send',
        body := v_payload::text,
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 616 (class 1255 OID 73483)
-- Name: handle_new_campaign_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_campaign_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_influencer_record RECORD;
  v_campaign_type TEXT;
  v_notification_title TEXT;
  v_notification_body TEXT;
  v_payload JSONB;
BEGIN
  -- Only proceed if the campaign is active
  IF NEW.is_active = TRUE AND (OLD IS NULL OR OLD.is_active = FALSE) THEN
    
    -- Determine campaign type
    IF NEW.type = 'status' THEN
      v_campaign_type := 'Status View';
      v_notification_title := 'New Status Available!';
      v_notification_body := 'Check out the new status: "' || NEW.title || '"';
    ELSIF NEW.type = 'challenge' THEN
      v_campaign_type := 'Challenge';
      v_notification_title := 'New Challenge Available!';
      v_notification_body := 'Join the new challenge: "' || NEW.title || '"';
    ELSIF NEW.type = 'survey' THEN
      v_campaign_type := 'Survey';
      v_notification_title := 'New Survey Available!';
      v_notification_body := 'Share your opinion in: "' || NEW.title || '"';
    ELSE
      RETURN NEW; -- Unknown type, skip notification
    END IF;

    -- Send notification to all influencers who have notifications enabled
    FOR v_influencer_record IN 
      SELECT id, push_token, notification_preferences, full_name
      FROM profiles 
      WHERE user_type = 'influencer' 
        AND push_token IS NOT NULL
        AND (notification_preferences->>'new_campaign')::boolean = true
    LOOP
      
      -- Build notification payload
      v_payload := jsonb_build_object(
        'to', v_influencer_record.push_token,
        'title', v_notification_title,
        'body', v_notification_body,
        'data', jsonb_build_object(
          'campaign_id', NEW.id,
          'campaign_type', NEW.type,
          'campaign_title', NEW.title
        )
      );

      -- Send push notification via pg_net
      PERFORM net.http_post(
        url := 'https://exp.host/--/api/v2/push/send',
        headers := '{"Content-Type": "application/json"}'::jsonb,
        body := v_payload
      );

    END LOOP;

  END IF;

  RETURN NEW;
END;
$$;


