--
-- TOC entry 569 (class 1255 OID 219479)
-- Name: handle_new_game_campaign_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_game_campaign_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_influencer_record RECORD;
  v_notification_title TEXT;
  v_notification_body TEXT;
  v_payload JSONB;
  v_error_message TEXT;
BEGIN
  -- Only proceed if the campaign is active
  IF NEW.status = 'active' AND (TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.status != 'active')) THEN
    
    v_notification_title := 'New Game Challenge Available! 🎮';
    v_notification_body := 'Match sponsor words in "' || NEW.campaign_name || '" to earn extra coins!';

    -- Loop through TARGETED influencers only
    FOR v_influencer_record IN 
      SELECT DISTINCT p.id, p.push_token
      FROM public.profiles p
      WHERE p.user_type = 'influencer' 
        AND p.push_token IS NOT NULL
        AND (p.notification_preferences->>'new_campaign')::boolean = true
        AND (
            -- RULE A: Public Game (respect location)
            (NEW.is_private = false AND (
                array_length(NEW.target_locations, 1) IS NULL
                OR p.state = ANY(NEW.target_locations)
            ))
            OR
            -- RULE B: Private Game (Hub Member AND respect location)
            (NEW.is_private = true AND EXISTS (
                SELECT 1 FROM public.game_campaign_hubs gch
                JOIN public.hub_members hm ON hm.hub_id = gch.hub_id
                WHERE gch.game_campaign_id = NEW.id
                AND hm.profile_id = p.id
            ) AND (
                array_length(NEW.target_locations, 1) IS NULL
                OR p.state = ANY(NEW.target_locations)
            ))
        )
    LOOP
      
      -- Build notification payload
      v_payload := jsonb_build_object(
        'to', v_influencer_record.push_token,
        'title', v_notification_title,
        'body', v_notification_body,
        'data', jsonb_build_object(
          'campaign_id', NEW.id,
          'type', 'game_campaign',
          'campaign_title', NEW.campaign_name
        ),
        'sound', 'default'
      );

      -- 1. Send Push Notification with error handling
      BEGIN
        PERFORM net.http_post(
          url := 'https://exp.host/--/api/v2/push/send',
          headers := '{"Content-Type": "application/json"}'::jsonb,
          body := v_payload
        );
      EXCEPTION WHEN OTHERS THEN
        v_error_message := SQLERRM;
        RAISE WARNING 'Failed to send push notification to influencer %: %', v_influencer_record.id, v_error_message;
        -- Continue to next influencer instead of crashing
      END;

      -- 2. Insert In-App Notification with error handling
      BEGIN
          user_id,
          title,
          message,
          payload,
          type
        ) VALUES (
          v_influencer_record.id,
          v_notification_title,
          v_notification_body,
          v_payload->'data',
          'game_campaign'
        );
      EXCEPTION WHEN OTHERS THEN
        v_error_message := SQLERRM;
        RAISE WARNING 'Failed to insert in-app notification for influencer %: %', v_influencer_record.id, v_error_message;
        -- Continue to next influencer instead of crashing
      END;

    END LOOP;

  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 503 (class 1255 OID 93516)
-- Name: handle_new_message_for_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_message_for_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  recipient_id UUID;
  sender_name TEXT;
  recipient_profile_record RECORD; -- Changed to RECORD to fetch multiple columns
  message_body TEXT;
  payload JSONB; -- Changed to JSONB for consistency
BEGIN
  -- Get recipient
  SELECT
    CASE
      WHEN c.brand_id = NEW.sender_id THEN c.influencer_id
      ELSE c.brand_id
    END
  INTO recipient_id
  FROM public.chats c
  WHERE c.id = NEW.chat_id;

  -- Early exit if no recipient found
  IF recipient_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Get recipient profile and sender name
  SELECT p.push_token, p.notification_preferences, COALESCE(s.full_name, 'Someone') AS sender_full_name
  INTO recipient_profile_record
  FROM public.profiles p
  LEFT JOIN public.profiles s ON s.id = NEW.sender_id
  WHERE p.id = recipient_id;

  -- Only send if push token exists AND notification preference is enabled
  IF recipient_profile_record.push_token IS NOT NULL AND (recipient_profile_record.notification_preferences->>'new_message')::boolean THEN
    -- Truncate message if needed
    message_body := NEW.content;
    IF char_length(message_body) > 100 THEN
      message_body := substring(message_body from 1 for 100) || '...';
    END IF;

    -- Build payload
    payload := jsonb_build_object(
      'to', recipient_profile_record.push_token,
      'title', 'New Message from ' || recipient_profile_record.sender_full_name,
      'body', message_body,
      'data', jsonb_build_object('chat_id', NEW.chat_id, 'type', 'new_message') -- Added type for frontend handling
    );

    -- Send notification (wrapped in exception handler)
    BEGIN
      PERFORM net.http_post(
        url := 'https://exp.host/--/api/v2/push/send',
        body := payload::jsonb, -- Cast to jsonb
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
    EXCEPTION WHEN OTHERS THEN
      -- Log error but don't fail the transaction
      RAISE WARNING 'Failed to send push notification: %', SQLERRM;
    END;
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 737 (class 1255 OID 28797)
-- Name: handle_new_message_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_message_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  recipient_id UUID;
  recipient_profile public.profiles;
  payload JSON;
BEGIN
  -- Determine recipient based on sender
  SELECT
    CASE WHEN c.brand_id = NEW.sender_id THEN c.influencer_id ELSE c.brand_id END
  INTO recipient_id
  FROM public.chats c
  WHERE c.id = NEW.chat_id;

  -- Get recipient profile with sender name
  SELECT p.*, s.full_name AS sender_name
  INTO recipient_profile
  FROM public.profiles p
  JOIN public.profiles s ON s.id = NEW.sender_id
  WHERE p.id = recipient_id;

  -- Send notification if token exists and preference enabled
  IF recipient_profile.push_token IS NOT NULL
    AND (recipient_profile.notification_preferences->>'new_message')::boolean THEN
    
    payload := json_build_object(
      'to', recipient_profile.push_token,
      'title', 'New Message from ' || recipient_profile.sender_name,
      'body', CASE
        WHEN char_length(NEW.content) > 100
        THEN substring(NEW.content FROM 1 FOR 100) || '...'
        ELSE NEW.content
      END,
      'data', json_build_object('chat_id', NEW.chat_id)
    );

    PERFORM net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      body := payload::text,
      headers := '{"Content-Type": "application/json"}'::jsonb
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- TOC entry 493 (class 1255 OID 54502)
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  _user_type TEXT;
  _full_name TEXT;
  _username TEXT;
  _company_name TEXT;
  _industry TEXT;
  _referral_code TEXT;
  _hub_record public.hubs;
  _referrer_profile public.profiles;
  _inviter_reward NUMERIC := 0;
  _invitee_reward NUMERIC := 0;
  _base_username TEXT;
  _unique_username TEXT;
  _counter INT := 0;
BEGIN
  -- Extract raw metadata from Supabase auth
  _user_type := COALESCE(NEW.raw_user_meta_data->>'user_type', 'influencer');
  _full_name := NEW.raw_user_meta_data->>'full_name';
  _company_name := NEW.raw_user_meta_data->>'company_name';
  _industry := NEW.raw_user_meta_data->>'industry';
  _referral_code := NEW.raw_user_meta_data->>'referral_code';

  -- Generate unique username
  _base_username := COALESCE(NEW.raw_user_meta_data->>'username', split_part(NEW.email, '@', 1));
  _unique_username := _base_username;

  LOOP
    SELECT username INTO _username FROM public.profiles WHERE username = _unique_username;
    IF _username IS NULL THEN
      _username := _unique_username;
      EXIT;
    END IF;
    _counter := _counter + 1;
    _unique_username := _base_username || _counter::TEXT;
  END LOOP;

  -- ============================================
  -- 1. INSERT INTO PROFILES (All 27 columns)
  -- ============================================
    id,
    email,
    full_name,
    username,
    avatar_url,
    user_type,
    bio,
    phone,
    location,
    followers_count,
    following_count,
    brandible_coins,
    total_earned,
    created_at,
    updated_at,
    private_campaign_rate,
    push_token,
    notification_preferences,
    referral_code,
    referred_by,
    phone_number,
    company_name,
    industry,
    state,
    lga,
    interests,
    game_coins
  )
  VALUES (
    NEW.id,
    NEW.email,
    _full_name,
    _username,
    NULL,
    _user_type,
    NULL,
    NULL,
    NULL,
    0,
    0,
    0.00,
    0.00,
    NOW(),
    NOW(),
    NULL,
    NULL,
    '{"new_message": true, "invite_accepted": true, "submission_approved": true, "new_status_post_created": true}'::jsonb,
    NULL,
    NULL,
    NULL,
    _company_name,
    _industry,
    NULL,
    NULL,
    NULL,
    0.00
  );

  -- ============================================
  -- 2. HUB & REFERRAL LOGIC
  -- ============================================
  IF _referral_code IS NOT NULL AND _referral_code != '' THEN
    
    -- A. INFLUENCERS ONLY: Try Hub Join First
    IF _user_type = 'influencer' THEN
        SELECT * INTO _hub_record FROM public.hubs 
        WHERE invite_code = upper(_referral_code);
        
        IF FOUND THEN
            -- Influencer is joining a hub via invite code
            VALUES (_hub_record.id, NEW.id)
            ON CONFLICT DO NOTHING;
            
            RAISE NOTICE 'Influencer % joined hub %', NEW.id, _hub_record.id;
            -- Exit here - influencers don't get referral bonus if they joined a hub
            RETURN NEW;
        END IF;
    END IF;

    -- B. ALL USERS: Try Legacy Referral Reward (Fallback)
    -- This runs if:
    --   - referral_code didn't match a hub invite code, OR
    --   - user is a brand (who cannot join hubs)
    SELECT * INTO _referrer_profile 
    FROM public.profiles 
    WHERE referral_code = _referral_code 
      AND id != NEW.id
    LIMIT 1;
    
    IF FOUND THEN
        -- Get reward amounts with fallbacks
        BEGIN
            _inviter_reward := public.get_inviter_reward();
            _invitee_reward := public.get_invitee_bonus();
        EXCEPTION WHEN OTHERS THEN
            _inviter_reward := 10;
            _invitee_reward := 5;
            RAISE NOTICE 'Using fallback rewards: inviter=%, invitee=%', _inviter_reward, _invitee_reward;
        END;
        
        -- Update Referrer Coins
        UPDATE public.profiles 
        SET 
          brandible_coins = COALESCE(brandible_coins, 0) + _inviter_reward, 
          total_earned = COALESCE(total_earned, 0) + _inviter_reward,
          updated_at = NOW()
        WHERE id = _referrer_profile.id;
        
        -- Update Invitee Coins
        UPDATE public.profiles 
        SET 
          brandible_coins = COALESCE(brandible_coins, 0) + _invitee_reward, 
          total_earned = COALESCE(total_earned, 0) + _invitee_reward,
          referred_by = _referrer_profile.id,
          updated_at = NOW()
        WHERE id = NEW.id;

        -- ============================================
        -- Log Referrer Transaction
        -- ✅ CORRECTED: Uses user_id, reference_id, reference_type, status
        -- ============================================
        BEGIN
            user_id,
            type,
            amount,
            description,
            reference_id,
            reference_type,
            status,
            created_at
          )
          VALUES (
            _referrer_profile.id,
            'referral_reward',
            _inviter_reward,
            'Referral reward for inviting ' || NEW.email,
            NEW.id,
            'profiles',
            'completed',
            NOW()
          );
          RAISE NOTICE 'Referrer transaction logged for %', _referrer_profile.id;
        EXCEPTION WHEN OTHERS THEN
          -- Don't break the trigger if transaction fails
          RAISE NOTICE 'Failed to log referrer transaction: %', SQLERRM;
        END;

        -- ============================================
        -- Log Invitee Transaction
        -- ✅ CORRECTED: Uses user_id, reference_id, reference_type, status
        -- ============================================
        BEGIN
            user_id,
            type,
            amount,
            description,
            reference_id,
            reference_type,
            status,
            created_at
          )
          VALUES (
            NEW.id,
            'referral_reward',
            _invitee_reward,
            'Welcome bonus from ' || COALESCE(_referrer_profile.full_name, _referrer_profile.email),
            _referrer_profile.id,
            'profiles',
            'completed',
            NOW()
          );
          RAISE NOTICE 'Invitee transaction logged for %', NEW.id;
        EXCEPTION WHEN OTHERS THEN
          -- Don't break the trigger if transaction fails
          RAISE NOTICE 'Failed to log invitee transaction: %', SQLERRM;
        END;
    END IF;  -- IF FOUND (referrer profile)
  END IF;  -- IF _referral_code IS NOT NULL

  -- ============================================
  -- 3. CREATE BRAND RECORD (if user_type = 'brand')
  -- ============================================
  IF _user_type = 'brand' THEN
    BEGIN
      VALUES (NEW.id, _company_name, _industry, NOW());
      RAISE NOTICE 'Brand record created for %', NEW.id;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Failed to create brand record: %', SQLERRM;
    END;
  END IF;

  -- ============================================
  -- 4. DEBUG LOGGING
  -- ============================================
  RAISE NOTICE 'handle_new_user completed: id=%, email=%, username=%, user_type=%, referral_code=%, inviter_reward=%, invitee_reward=%',
    NEW.id, NEW.email, _username, _user_type, _referral_code, _inviter_reward, _invitee_reward;

  RETURN NEW;

EXCEPTION WHEN OTHERS THEN
  -- Log the error but don't fail the trigger
  RAISE NOTICE 'handle_new_user ERROR: %', SQLERRM;
  RETURN NEW;
END;
$$;


--
-- TOC entry 546 (class 1255 OID 18123)
-- Name: handle_new_user_registration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user_registration() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$DECLARE
    _user_type TEXT;
    _full_name TEXT;
    _company_name TEXT;
    _industry TEXT;
    _username TEXT;
BEGIN
    RAISE LOG '🚀 TRIGGER STARTED for user: %', NEW.id;

    -- Fetch metadata
    SELECT raw_user_meta_data->>'user_type',
           raw_user_meta_data->>'full_name',
           raw_user_meta_data->>'username',
           raw_user_meta_data->>'company_name',
           raw_user_meta_data->>'industry'
    INTO _user_type, _full_name, _username, _company_name, _industry
    FROM auth.users 
    WHERE id = NEW.id;

    -- Normalize empty strings to NULL
    IF _company_name = '' THEN
        _company_name := NULL;
    END IF;

    IF _industry = '' THEN
        _industry := NULL;
    END IF;

    RAISE LOG '📊 Normalized: user_type=%, company_name=%, industry=%',
        _user_type, _company_name, _industry;

    -- Update profiles table
    UPDATE public.profiles 
    SET full_name = _full_name,
        username = _username,
        user_type = _user_type
    WHERE id = NEW.id;

    -- Only create brand if valid
    IF _user_type = 'brand'
       AND _company_name IS NOT NULL
       AND _industry IS NOT NULL THEN

        VALUES (NEW.id, _company_name, _industry, NOW())
        ON CONFLICT (profile_id) DO NOTHING;
    END IF;

    RAISE LOG '🎉 TRIGGER COMPLETE for user: %', NEW.id;
    RETURN NEW;

EXCEPTION
    WHEN OTHERS THEN
        RAISE LOG '💥 TRIGGER ERROR: %', SQLERRM;
        RETURN NEW;
END;$$;


--
-- TOC entry 638 (class 1255 OID 26938)
-- Name: increment_participation_count(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_participation_count(p_status_id uuid, p_participant_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_challenge_id UUID;
  v_submission_count INTEGER;
BEGIN
  -- Get the challenge ID for this status post
  SELECT id INTO v_challenge_id
  FROM challenges
  WHERE status_post_id = p_status_id
  LIMIT 1;

  -- Debug: Check if challenge exists
  IF v_challenge_id IS NULL THEN
    RETURN json_build_object('success', FALSE, 'message', 'Challenge not found for status');
  END IF;

  -- Count how many submissions this user has for this challenge
  SELECT COUNT(*) INTO v_submission_count
  FROM challenge_submissions
  WHERE challenge_id = v_challenge_id
  AND participant_id = p_participant_id;

  -- Only increment if this is their first submission (count was 0 before insert)
  IF v_submission_count = 1 THEN
    UPDATE status_posts
    SET participation_count = participation_count + 1
    WHERE id = p_status_id;
    
    RETURN json_build_object('success', TRUE, 'incremented', TRUE);
  ELSE
    RETURN json_build_object('success', TRUE, 'incremented', FALSE, 'reason', 'User already submitted');
  END IF;
END;
$$;


