CREATE FUNCTION public.increment_status_view_count(p_status_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_new_count INTEGER;
BEGIN
  -- Update the view_count (SECURITY DEFINER bypasses RLS)
  UPDATE status_posts 
  SET view_count = COALESCE(view_count, 0) + 1
  WHERE id = p_status_id
  RETURNING view_count INTO v_new_count;
  
  RETURN jsonb_build_object(
    'success', true,
    'new_view_count', v_new_count
  );
END;
$$;


--
-- TOC entry 787 (class 1255 OID 26286)
-- Name: initiate_chat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.initiate_chat(p_purchase_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_chat_id UUID;
  v_brand_id UUID;
  v_influencer_id UUID;
BEGIN
  -- Check if a chat already exists for this purchase
  SELECT id INTO v_chat_id FROM public.chats WHERE purchase_id = p_purchase_id;
  IF v_chat_id IS NOT NULL THEN
    RETURN v_chat_id;
  END IF;

  -- Get brand and influencer IDs from the purchase
  SELECT p.brand_id, pur.buyer_id
  INTO v_brand_id, v_influencer_id
  FROM public.purchases pur
  JOIN public.products p ON pur.product_id = p.id
  WHERE pur.id = p_purchase_id;

  -- Security Check: Ensure the person initiating is the brand owner
  IF auth.uid() != v_brand_id THEN
    RAISE EXCEPTION 'Only the brand owner can initiate a chat.';
  END IF;

  -- Create the new chat
  VALUES (p_purchase_id, v_brand_id, v_influencer_id)
  RETURNING id INTO v_chat_id;

  RETURN v_chat_id;
END;
$$;


