-- TOC entry 582 (class 1255 OID 55084)
-- Name: insert_pass_it_campaign(character varying, text, text, character varying, integer, integer, character varying, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_pass_it_campaign(p_title character varying, p_description text, p_artwork_url text, p_artwork_type character varying, p_target_passes integer, p_reward_pool integer, p_campaign_type character varying, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$DECLARE
    v_campaign_record pass_it_campaigns;
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not  authenticated. User must be logged in to create a campaign.';
    END IF;
    
    -- Your existing validation logic
    IF p_title IS NULL OR p_title = '' THEN
        RAISE EXCEPTION 'Title cannot be empty';
    END IF;
    
    IF p_artwork_url IS NULL OR p_artwork_url = '' THEN
        RAISE EXCEPTION 'Artwork URL cannot be empty';
    END IF;
    
    IF p_target_passes <= 0 THEN
        RAISE EXCEPTION 'Target passes must be greater than 0';
    END IF;
    
    IF p_reward_pool <= 0 THEN
        RAISE EXCEPTION 'Reward pool must be greater than 0';
    END IF;
    
    IF p_campaign_type NOT IN ('invitational', 'public') THEN
        RAISE EXCEPTION 'Campaign type must be either ''invitational'' or ''public''';
    END IF;
    
    -- Insert and return full record
        brand_id,
        title,
        description,
        artwork_url,
        artwork_type,
        target_passes,
        reward_pool,
        campaign_type,
        expires_at,
        status
    ) VALUES (
        v_user_id,
        p_title,
        p_description,
        p_artwork_url,
        p_artwork_type,
        p_target_passes,
        p_reward_pool,
        p_campaign_type,
        p_expires_at,
        'active'
    )
    RETURNING * INTO v_campaign_record;
    
    RETURN to_jsonb(v_campaign_record);
END;$$;


--
-- TOC entry 507 (class 1255 OID 55282)
-- Name: insert_pass_it_campaign(text, text, text, text, integer, integer, text, timestamp with time zone, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_pass_it_campaign(p_title text, p_description text, p_artwork_url text, p_artwork_type text, p_target_passes integer, p_reward_pool integer, p_campaign_type text, p_expires_at timestamp with time zone, p_starter_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_brand_id      UUID := auth.uid();
    v_brand_balance NUMERIC;
    v_campaign_id   UUID;
    v_new_campaign  jsonb;
    v_starter_id    UUID;
    v_chain_id      UUID;
BEGIN
    -- 1. Fetch brand's current balance and lock the row for update
    SELECT brandible_coins
    INTO v_brand_balance
    FROM public.profiles
    WHERE id = v_brand_id
    FOR UPDATE;

    -- 2. Check if brand has sufficient balance
    IF v_brand_balance < p_reward_pool THEN
        RAISE EXCEPTION
            'Insufficient Brandible Coins. You need % but your balance is %.',
            p_reward_pool, v_brand_balance;
    END IF;

    -- 3. Insert the campaign
        brand_id,
        title,
        description,
        artwork_url,
        artwork_type,
        target_passes,
        reward_pool,
        campaign_type,
        expires_at,
        status
    )
    VALUES (
        v_brand_id,
        p_title,
        p_description,
        p_artwork_url,
        p_artwork_type,
        p_target_passes,
        p_reward_pool,
        p_campaign_type,
        p_expires_at,
        'active'
    )
    RETURNING to_jsonb(pass_it_campaigns)
    INTO v_new_campaign;

    v_campaign_id := (v_new_campaign->>'id')::UUID;

    -- 4. Deduct coins from brand's balance
    UPDATE public.profiles
    SET brandible_coins = brandible_coins - p_reward_pool
    WHERE id = v_brand_id;

    -- 5. Record the escrow transaction
        user_id,
        type,
        amount,
        description,
        pass_it_campaign_id
    )
    VALUES (
        v_brand_id,
        'pass_it_escrow',
        -p_reward_pool,  -- Negative amount for deduction
        'Coins moved to escrow for Pass It campaign: ' || p_title,
        v_campaign_id
    );

    -- 6. If invitational, create chains and invitations
    IF p_campaign_type = 'invitational' AND array_length(p_starter_ids, 1) > 0 THEN
        FOREACH v_starter_id IN ARRAY p_starter_ids
        LOOP
            -- Create a chain for each starter
                campaign_id,
                starter_influencer_id,
                status
            )
            VALUES (
                v_campaign_id,
                v_starter_id,
                'active'
            )
            RETURNING id INTO v_chain_id;

            -- Create the initial invitation
                campaign_id,
                chain_id,
                inviter_id,
                invitee_id,
                position_in_chain,
                status
            )
            VALUES (
                v_campaign_id,
                v_chain_id,
                v_brand_id,
                v_starter_id,
                1,
                'pending'
            );
        END LOOP;
    END IF;

    -- 7. Return the created campaign
    RETURN v_new_campaign;
END;
$$;


--
-- TOC entry 828 (class 1255 OID 31382)
-- Name: join_collaboration_group(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_collaboration_group(p_group_code text, p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_group record;
  v_participant_count integer;
  v_challenge record;
BEGIN
  SELECT * INTO v_group FROM public.collaboration_groups WHERE group_code = p_group_code;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'message', 'Invalid group code');
  END IF;

  IF v_group.status != 'open' THEN
    RETURN json_build_object('success', false, 'message', 'Group is no longer accepting participants');
  END IF;

  IF EXISTS(SELECT 1 FROM public.collaboration_participants WHERE group_id = v_group.id AND user_id = p_user_id) THEN
    RETURN json_build_object('success', false, 'message', 'You are already in this group');
  END IF;

  SELECT * INTO v_challenge FROM public.challenges WHERE id = v_group.challenge_id;
  SELECT COUNT(*) INTO v_participant_count FROM public.collaboration_participants WHERE group_id = v_group.id;

  IF v_participant_count >= v_challenge.max_participants THEN
    RETURN json_build_object('success', false, 'message', 'Group is full');
  END IF;

  VALUES (v_group.id, p_user_id, 'collaborator');

  IF v_participant_count + 1 >= v_challenge.max_participants THEN
    UPDATE public.collaboration_groups
    SET status = 'full', updated_at = now()
    WHERE id = v_group.id;
  END IF;

  RETURN json_build_object(
    'success', true,
    'group_id', v_group.id,
    'challenge_id', v_group.challenge_id,
    'message', 'Successfully joined collaboration group'
  );
END;
$$;


--
-- TOC entry 794 (class 1255 OID 214696)
-- Name: join_hub_by_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_hub_by_code(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_hub_record RECORD;
BEGIN
    -- 1. Find the Hub
    SELECT * INTO v_hub_record FROM public.hubs WHERE invite_code = upper(p_code);
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Invalid hub code.');
    END IF;

    -- 2. Check if already a member
    IF EXISTS (SELECT 1 FROM public.hub_members WHERE hub_id = v_hub_record.id AND profile_id = v_user_id) THEN
        RETURN jsonb_build_object('success', false, 'message', 'You are already a member of this hub.');
    END IF;

    -- 3. Check if they are trying to join their own hub (optional, but usually fine)
    -- IF v_hub_record.owner_id = v_user_id THEN
    --     RETURN jsonb_build_object('success', false, 'message', 'You cannot join your own hub.');
    -- END IF;

    -- 4. Join the Hub
    VALUES (v_hub_record.id, v_user_id);

    RETURN jsonb_build_object(
        'success', true, 
        'hub_name', v_hub_record.name,
        'message', 'Successfully joined ' || v_hub_record.name
    );
END;
$$;


--
-- TOC entry 704 (class 1255 OID 218195)
-- Name: leave_hub(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leave_hub(p_hub_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
BEGIN
    -- 1. Check if the user is a member of the hub
    IF NOT EXISTS (SELECT 1 FROM public.hub_members WHERE hub_id = p_hub_id AND profile_id = v_user_id) THEN
        RETURN jsonb_build_object('success', false, 'message', 'You are not a member of this hub.');
    END IF;

    -- 2. Leave the hub
    DELETE FROM public.hub_members
    WHERE hub_id = p_hub_id AND profile_id = v_user_id;

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Successfully left the hub.'
    );
END;
$$;


