-- TOC entry 561 (class 1255 OID 40854)
-- Name: log_activity(text, text, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_activity(p_action_type text, p_resource_type text DEFAULT NULL::text, p_resource_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_activity_id UUID;
  v_user_type TEXT;
BEGIN
  -- Determine user_type from profiles table or set default
  IF p_user_id IS NOT NULL THEN
    SELECT 
      COALESCE(
        (raw_user_meta_data->>'user_type')::TEXT,
        CASE 
          WHEN email LIKE '%@%' THEN 'user'
          ELSE 'unknown'
        END
      )
    INTO v_user_type
    FROM auth.users
    WHERE id = p_user_id;
    
    -- If user not found, set default
    IF v_user_type IS NULL THEN
      v_user_type := 'unknown';
    END IF;
  ELSE
    v_user_type := 'anonymous';
  END IF;

    user_id, 
    user_type,
    action_type, 
    entity_type,
    entity_id,
    details,
    timestamp
  )
  VALUES (
    p_user_id,
    v_user_type,
    p_action_type, 
    p_resource_type,    -- CHANGED: from p_entity_type
    p_resource_id,      -- CHANGED: from p_entity_id
    p_metadata,         -- CHANGED: from p_details
    NOW()
  )
  RETURNING id INTO v_activity_id;
  
  RETURN v_activity_id;
END;
$$;


