--
-- TOC entry 624 (class 1255 OID 54832)
-- Name: manually_select_winner(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manually_select_winner(p_campaign_id uuid, p_winning_chain_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_campaign RECORD;
    v_participants UUID[];
    v_participant_count INT;
    v_reward_per_person NUMERIC;
    v_participant_id UUID;
BEGIN
    -- 1. Get the campaign details, verify ownership, and lock the row
    SELECT * INTO v_campaign
    FROM public.pass_it_campaigns
    WHERE id = p_campaign_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Campaign not found: %', p_campaign_id;
    END IF;

    IF v_campaign.brand_id IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION 'Authorization error: You do not own this campaign.';
    END IF;

    IF v_campaign.status IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION 'Campaign is not active and cannot be manually completed.';
    END IF;

    -- 2. Find all unique participants in the winning chain
    -- This includes the original starter and everyone who completed a pass
    SELECT array_agg(DISTINCT participant_id)
    INTO v_participants
    FROM (
        -- Get the starter of the chain
        SELECT starter_influencer_id AS participant_id
        FROM public.pass_it_chains
        WHERE id = p_winning_chain_id
        UNION
        -- Get all reviewers from the passes in that chain
        SELECT reviewer_id AS participant_id
        FROM public.pass_it_passes
        WHERE chain_id = p_winning_chain_id AND status = 'completed'
    ) AS all_participants;

    v_participant_count := array_length(v_participants, 1);

    -- 3. Check for participants and calculate reward
    IF v_participant_count IS NULL OR v_participant_count = 0 THEN
        RAISE EXCEPTION 'Cannot distribute rewards: No participants found in the winning chain.';
    END IF;

    v_reward_per_person := v_campaign.reward_pool / v_participant_count;

    -- 4. Update the campaign and chain statuses
    UPDATE public.pass_it_campaigns
    SET 
        status = 'completed',
        winner_chain_id = p_winning_chain_id,
        completed_at = NOW()
    WHERE id = p_campaign_id;

    UPDATE public.pass_it_chains
    SET 
        is_winner = TRUE,
        status = 'completed',
        completed_at = NOW()
    WHERE id = p_winning_chain_id;

    -- 5. Distribute rewards to each participant
    FOREACH v_participant_id IN ARRAY v_participants
    LOOP
        -- Add coins to influencer's wallet
        UPDATE public.profiles
        SET brandible_coins = brandible_coins + v_reward_per_person
        WHERE id = v_participant_id;

        -- Create a transaction record for the influencer
        VALUES (
            v_participant_id,
            'pass_it_reward',
            v_reward_per_person,
            'Reward for winning Pass It chain: ' || v_campaign.title,
            p_campaign_id
        );
    END LOOP;

    -- 6. Create a final transaction to show the escrow is fully paid out for the brand.
    -- This is for accounting/history; the brand's balance was already debited at creation.
    VALUES (
        v_campaign.brand_id,
        'pass_it_payout',
        v_campaign.reward_pool, -- Positive amount to balance the initial negative escrow
        'Escrow paid out to winners for campaign: ' || v_campaign.title,
        p_campaign_id
    );

    RAISE NOTICE 'Campaign % successfully completed. Chain % declared winner. % coins distributed to % participants.', p_campaign_id, p_winning_chain_id, v_campaign.reward_pool, v_participant_count;

END;
$$;


