--
-- TOC entry 514 (class 1255 OID 22628)
-- Name: place_order_from_cart(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_order_from_cart(p_brand_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_total_cost DECIMAL(10, 2);
  v_user_coins DECIMAL(10, 2);
  cart_item RECORD;
BEGIN
  -- 1. Calculate the total cost of items for the specified brand in the user's cart
  SELECT INTO v_total_cost SUM(p.coin_price * ci.quantity)
  FROM public.cart_items ci
  JOIN public.products p ON ci.product_id = p.id
  WHERE ci.user_id = v_user_id AND p.brand_id = p_brand_id;

  -- If cart is empty for this brand, do nothing.
  IF v_total_cost IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'Your cart for this brand is empty.');
  END IF;

  -- 2. Get the user's current coin balance
  SELECT INTO v_user_coins brandible_coins FROM public.profiles WHERE id = v_user_id;

  -- 3. Check if the user has enough coins
  IF v_user_coins < v_total_cost THEN
    RETURN json_build_object('success', false, 'message', 'Insufficient coins to place this order.');
  END IF;

  -- 4. Create a purchase record for each item in the cart for that brand
  FOR cart_item IN 
    SELECT ci.id AS cart_item_id, ci.product_id, ci.quantity, p.coin_price
    FROM public.cart_items ci
    JOIN public.products p ON ci.product_id = p.id
    WHERE ci.user_id = v_user_id AND p.brand_id = p_brand_id
  LOOP
    VALUES (v_user_id, cart_item.product_id, cart_item.quantity, (cart_item.coin_price * cart_item.quantity), 'pending_fulfillment');
  END LOOP;

  -- 5. Delete the items from the cart for that brand
  DELETE FROM public.cart_items
  WHERE id IN (
    SELECT ci.id
    FROM public.cart_items ci
    JOIN public.products p ON ci.product_id = p.id
    WHERE ci.user_id = v_user_id AND p.brand_id = p_brand_id
  );

  RETURN json_build_object('success', true, 'message', 'Order placed successfully!');

END;
$$;


