--
-- TOC entry 827 (class 1255 OID 38962)
-- Name: process_brand_activity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_brand_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_user_id UUID := NEW.user_id;
    v_user_type TEXT;
    v_action_type TEXT;
    v_achievement_def RECORD;
    v_action_count INT;
    v_already_unlocked BOOLEAN;
BEGIN
    -- FIX: Only run this logic for users of type 'brand'
    SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_user_id;
    IF v_user_type != 'brand' THEN
        RETURN NEW;
    END IF;

    v_action_type := NEW.action_type;

    IF v_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    FOR v_achievement_def IN
        SELECT * FROM public.achievement_definitions
        WHERE action_type = v_action_type AND is_active = true
    LOOP
        SELECT EXISTS (
            SELECT 1 FROM public.brand_achievements
            WHERE brand_id = v_user_id AND achievement_key = v_achievement_def.key
        ) INTO v_already_unlocked;

        IF NOT v_already_unlocked THEN
            SELECT COUNT(*) INTO v_action_count
            FROM public.activity_logs
            WHERE user_id = v_user_id AND action_type = v_action_type;

            IF v_action_count >= v_achievement_def.threshold THEN
                VALUES (v_user_id, v_achievement_def.key);

                IF v_achievement_def.reward_coins > 0 THEN
                    UPDATE public.profiles
                    SET brandible_coins = COALESCE(brandible_coins, 0) + v_achievement_def.reward_coins,
                        total_earned = COALESCE(total_earned, 0) + v_achievement_def.reward_coins
                    WHERE id = v_user_id;

                    VALUES (
                        v_user_id,
                        'achievement_reward',
                        v_achievement_def.reward_coins,
                        'Unlocked achievement: ' || v_achievement_def.name,
                        NEW.id,
                        'activity_log'
                    );
                END IF;
            END IF;
        END IF;
    END LOOP;

    RETURN NEW;
END;
$$;


--
-- TOC entry 669 (class 1255 OID 28558)
-- Name: process_coin_purchase(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_coin_purchase(p_buyer_id uuid, p_package_id uuid, p_payment_reference uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  coin_amount DECIMAL;
  bonus_coins DECIMAL;
  total_coins DECIMAL;
BEGIN
  -- Get package details
  SELECT cp.coin_amount, cp.bonus_coins 
  INTO coin_amount, bonus_coins
  FROM coin_packages cp
  WHERE cp.id = p_package_id AND cp.is_active = TRUE;
  
  IF coin_amount IS NULL THEN
    RETURN FALSE;
  END IF;
  
  total_coins := coin_amount + COALESCE(bonus_coins, 0);
  
  -- Add coins to user account
  UPDATE profiles 
  SET brandible_coins = brandible_coins + total_coins
  WHERE id = p_buyer_id;
  
  -- Record transaction
    user_id, 
    type, 
    amount, 
    description, 
    reference_id, 
    reference_type
  ) VALUES (
    p_buyer_id,
    'purchased',
    total_coins,
    'Coin package purchase: ' || coin_amount || ' + ' || COALESCE(bonus_coins, 0) || ' bonus',
    p_package_id,
    'coin_purchase'
  );
  
  -- Update coin purchase record
  UPDATE coin_purchases 
  SET status = 'completed'
  WHERE id = p_payment_reference;
  
  RETURN TRUE;
END;
$$;


--
-- TOC entry 500 (class 1255 OID 17705)
-- Name: process_product_purchase(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_product_purchase(p_buyer_id uuid, p_product_id uuid, p_quantity integer DEFAULT 1) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  coin_price DECIMAL;
  total_cost DECIMAL;
  user_coins DECIMAL;
  purchase_id UUID;
BEGIN
  -- Get product price and user coins
  SELECT coin_price INTO coin_price FROM products WHERE id = p_product_id AND is_active = TRUE;
  SELECT brandible_coins INTO user_coins FROM profiles WHERE id = p_buyer_id;
  
  IF coin_price IS NULL THEN
    RAISE EXCEPTION 'Product not found or inactive';
  END IF;
  
  total_cost := coin_price * p_quantity;
  
  IF user_coins < total_cost THEN
    RAISE EXCEPTION 'Insufficient coins';
  END IF;
  
  -- Deduct coins from user
  UPDATE profiles 
  SET brandible_coins = brandible_coins - total_cost
  WHERE id = p_buyer_id;
  
  -- Create purchase record
    buyer_id, 
    product_id, 
    quantity, 
    total_coins,
    status
  ) VALUES (
    p_buyer_id,
    p_product_id,
    p_quantity,
    total_cost,
    'confirmed'
  ) RETURNING id INTO purchase_id;
  
  -- Record transaction
    user_id, 
    type, 
    amount, 
    description, 
    reference_id, 
    reference_type
  ) VALUES (
    p_buyer_id,
    'spent',
    -total_cost,
    'Product purchase',
    purchase_id,
    'product_purchase'
  );
  
  -- Update product stock
  UPDATE products 
  SET stock_quantity = stock_quantity - p_quantity
  WHERE id = p_product_id;
  
  RETURN purchase_id;
END;
$$;


--
-- TOC entry 708 (class 1255 OID 105376)
-- Name: process_referral(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_referral(p_referrer_id uuid, p_media_id uuid, p_referee_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_referee_id uuid;
    v_media_record record;
    v_reward_amount numeric;
    v_referee_reward numeric;
    v_referrer_reward numeric;
    v_referral_id uuid;
    v_reward_split jsonb;
    v_referrer_percentage numeric := 0.10;
    v_referee_percentage numeric := 0.90;
    v_brand_id uuid;
    v_status_post_id uuid;
    v_existing_referral uuid;
    v_app_settings_exists boolean;
BEGIN
    v_referee_id := p_referee_id;
    
    IF v_referee_id IS NULL THEN
        v_referee_id := auth.uid();
    END IF;
    
    IF v_referee_id IS NULL THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Authentication required. Please log in to claim this reward.',
            'error_code', 'NOT_AUTHENTICATED'
        );
    END IF;

    IF v_referee_id = p_referrer_id THEN
        RETURN json_build_object(
            'success', false,
            'message', 'You cannot claim your own referral link',
            'error_code', 'SELF_REFERRAL'
        );
    END IF;

    IF EXISTS (
        SELECT 1 FROM status_views 
        WHERE media_id = p_media_id 
          AND viewer_id = v_referee_id
          AND reward_given = true
    ) THEN
        RETURN json_build_object(
            'success', false,
            'message', 'You have already viewed this media and received a reward',
            'error_code', 'ALREADY_VIEWED_AND_REWARDED'
        );
    END IF;

    SELECT id INTO v_existing_referral
    FROM referrals
    WHERE referee_id = v_referee_id 
      AND status_media_id = p_media_id
      AND status = 'completed'
    LIMIT 1;

    IF FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'You have already claimed the reward for this campaign',
            'error_code', 'ALREADY_CLAIMED'
        );
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM app_settings WHERE key = 'referral_reward_split'
    ) INTO v_app_settings_exists;

    IF v_app_settings_exists THEN
        SELECT value INTO v_reward_split 
        FROM app_settings 
        WHERE key = 'referral_reward_split';
        
        v_referrer_percentage := COALESCE((v_reward_split->>'referrer')::numeric, 0.10);
        v_referee_percentage := COALESCE((v_reward_split->>'referee')::numeric, 0.90);
    END IF;

    SELECT 
        sm.id,
        sm.status_post_id,
        sm.reward_per_view,
        sp.id as status_post_id,
        sp.brand_id,
        sp.reward_limit,
        sp.current_rewards_given,
        sp.reserved_funds,
        sp.is_active as post_active,
        sp.is_deleted as post_deleted,
        sp.expires_at
    INTO v_media_record
    FROM status_media sm
    INNER JOIN status_posts sp ON sm.status_post_id = sp.id
    WHERE sm.id = p_media_id;

    IF NOT FOUND THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Campaign not found or no longer available',
            'error_code', 'CAMPAIGN_NOT_FOUND'
        );
    END IF;

    v_brand_id := v_media_record.brand_id;
    v_status_post_id := v_media_record.status_post_id;
    v_reward_amount := v_media_record.reward_per_view;

    IF v_media_record.post_deleted = true THEN
        RETURN json_build_object(
            'success', false,
            'message', 'This campaign has been removed',
            'error_code', 'CAMPAIGN_DELETED'
        );
    END IF;

    IF v_media_record.post_active = false THEN
        RETURN json_build_object(
            'success', false,
            'message', 'This campaign is currently inactive',
            'error_code', 'CAMPAIGN_INACTIVE'
        );
    END IF;

    IF v_media_record.expires_at IS NOT NULL AND v_media_record.expires_at < NOW() THEN
        RETURN json_build_object(
            'success', false,
            'message', 'This campaign has ended',
            'error_code', 'CAMPAIGN_EXPIRED'
        );
    END IF;

    IF v_media_record.current_rewards_given >= v_media_record.reward_limit THEN
        RETURN json_build_object(
            'success', false,
            'message', 'All rewards for this campaign have been claimed',
            'error_code', 'LIMIT_REACHED'
        );
    END IF;

    IF v_media_record.reserved_funds < v_reward_amount THEN
        RETURN json_build_object(
            'success', false,
            'message', 'This campaign has run out of funds',
            'error_code', 'INSUFFICIENT_FUNDS'
        );
    END IF;

    v_referee_reward := ROUND(v_reward_amount * v_referee_percentage, 2);
    v_referrer_reward := ROUND(v_reward_amount * v_referrer_percentage, 2);

    BEGIN
        UPDATE profiles
        SET brandible_coins = COALESCE(brandible_coins, 0) + v_referee_reward,
            total_earned = COALESCE(total_earned, 0) + v_referee_reward
        WHERE id = v_referee_id;

        VALUES (v_referee_id, 'referral_reward', v_referee_reward, 
                'Referral reward for viewing campaign', p_referrer_id, 'referral');

        UPDATE profiles
        SET brandible_coins = COALESCE(brandible_coins, 0) + v_referrer_reward,
            total_earned = COALESCE(total_earned, 0) + v_referrer_reward
        WHERE id = p_referrer_id;

        VALUES (p_referrer_id, 'referral_reward', v_referrer_reward, 
                'Reward for referring a user', v_referee_id, 'referral');

        UPDATE status_posts
        SET
            reserved_funds = reserved_funds - v_reward_amount,
            current_rewards_given = current_rewards_given + 1,
            updated_at = NOW()
        WHERE id = v_status_post_id;

        VALUES (p_referrer_id, v_referee_id, p_media_id, 'completed')
        RETURNING id INTO v_referral_id;

        -- 🆕 NEW: Insert record into status_views for the referee
        VALUES (v_referee_id, p_media_id, v_status_post_id, TRUE, v_referee_reward, 'referral');

            user_id, user_type, action_type, entity_type, entity_id, details, metadata
        ) VALUES (
            v_referee_id, 'influencer', 'share_conversion', 'referral', v_referral_id,
            jsonb_build_object(
                'referrer_id', p_referrer_id, 
                'referee_id', v_referee_id,
                'media_id', p_media_id, 
                'status_post_id', v_status_post_id,
                'brand_id', v_brand_id, 
                'referral_reward_amount', v_referrer_reward,
                'new_user_reward_amount', v_referee_reward, 
                'total_reward_amount', v_reward_amount
            ),
            jsonb_build_object(
                'referral_id', v_referral_id, 
                'success', true, 
                'processed_at', NOW()
            )
        );

        RETURN json_build_object(
            'success', true,
            'message', 'Referral processed successfully!',
            'reward_amount', v_referee_reward,
            'referrer_reward', v_referrer_reward,
            'referral_id', v_referral_id,
            'status_id', v_status_post_id
        );

    EXCEPTION
        WHEN unique_violation THEN
            RETURN json_build_object(
                'success', false,
                'message', 'This referral has already been processed',
                'error_code', 'DUPLICATE_REFERRAL'
            );
        WHEN OTHERS THEN
            RAISE WARNING 'Transaction failed: %', SQLERRM;
            RETURN json_build_object(
                'success', false,
                'message', 'Failed to process referral due to a system error',
                'error_code', 'TRANSACTION_FAILED',
                'debug_info', SQLERRM
            );
    END;

EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'Outer exception: %', SQLERRM;
        RETURN json_build_object(
            'success', false,
            'message', 'An unexpected error occurred while processing your referral',
            'error_code', 'INTERNAL_ERROR',
            'debug_info', SQLERRM
        );
END;
$$;


--
-- TOC entry 513 (class 1255 OID 62847)
-- Name: publish_blog_post(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_blog_post(p_post_id uuid) RETURNS public.blog_posts
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_agent_id uuid;
    v_user_type text;
    v_published_post public.blog_posts;
BEGIN
    SELECT auth.uid() INTO v_agent_id;
    SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_agent_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RAISE EXCEPTION 'Only agents can publish blog posts.';
    END IF;

    UPDATE public.blog_posts
    SET
        status = 'published',
        published_at = NOW()
    WHERE id = p_post_id
    RETURNING * INTO v_published_post;

    IF v_published_post IS NULL THEN
        RAISE EXCEPTION 'Blog post not found or not authorized to publish.';
    END IF;

    RETURN v_published_post;
END;
$$;


--
-- TOC entry 688 (class 1255 OID 22350)
-- Name: purchase_product_with_coins(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purchase_product_with_coins(p_product_id uuid, p_buyer_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_product RECORD;
  v_buyer RECORD;
  v_purchase_id UUID;
BEGIN
  -- 1. Get product and buyer details within a single transaction lock
  SELECT * INTO v_product FROM public.products WHERE id = p_product_id FOR UPDATE;
  SELECT * INTO v_buyer FROM public.profiles WHERE id = p_buyer_id FOR UPDATE;

  -- 2. Check for validity
  IF v_product IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'Product not found.');
  END IF;

  IF v_product.stock_quantity <= 0 THEN
    RETURN json_build_object('success', false, 'message', 'Product is out of stock.');
  END IF;

  IF v_buyer.brandible_coins < v_product.coin_price THEN
    RETURN json_build_object('success', false, 'message', 'Insufficient coins.');
  END IF;

  -- 3. Update product stock
  UPDATE public.products
  SET stock_quantity = stock_quantity - 1
  WHERE id = p_product_id;

  -- 4. Update buyer's coin balance
  UPDATE public.profiles
  SET brandible_coins = brandible_coins - v_product.coin_price
  WHERE id = p_buyer_id;

  -- 5. Create purchase record
  VALUES (p_buyer_id, p_product_id, 1, v_product.coin_price, 'confirmed')
  RETURNING id INTO v_purchase_id;

  -- 6. Create transaction record
  VALUES (
    p_buyer_id,
    'spent',
    -v_product.coin_price,
    'Purchased ' || v_product.name,
    v_purchase_id, -- Reference the purchase itself
    'product_purchase'
  );

  -- 7. Return success
  RETURN json_build_object('success', true, 'message', 'Purchase successful!');

EXCEPTION
  WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$$;


--
-- TOC entry 770 (class 1255 OID 26872)
-- Name: record_challenge_view(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_challenge_view(p_status_id uuid, p_viewer_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Check if view already exists
  IF NOT EXISTS (
    SELECT 1 FROM status_views 
    WHERE status_post_id = p_status_id AND viewer_id = p_viewer_id
  ) THEN
    -- Insert view record
    VALUES (p_status_id, p_viewer_id, FALSE);
    
    -- Update view count
    UPDATE status_posts
    SET view_count = view_count + 1
    WHERE id = p_status_id;
  END IF;
  
  RETURN json_build_object('success', TRUE);
END;
$$;


--
-- TOC entry 664 (class 1255 OID 219400)
-- Name: record_game_interaction(uuid, uuid, text, boolean, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_game_interaction(p_campaign_id uuid, p_influencer_id uuid, p_trigger_word text, p_success boolean, p_coins_earned numeric, p_full_cost numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_brand_id UUID;
    v_hub_owner_id UUID;
    v_curation_fee DECIMAL := 0;
    v_amount_to_deduct DECIMAL;
    v_new_balance DECIMAL;
    v_campaign_successful_interactions INTEGER;
    v_campaign_min_reach INTEGER;
BEGIN
    -- 1. Get campaign info
    SELECT brand_id, successful_interactions, min_influencer_reach 
    INTO v_brand_id, v_campaign_successful_interactions, v_campaign_min_reach
    FROM public.game_campaigns 
    WHERE id = p_campaign_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Campaign not found'
        );
    END IF;

    -- 2. Identify Hub Owner for Curation Fee (10%)
    SELECT h.owner_id INTO v_hub_owner_id
    FROM public.game_campaign_hubs gch
    JOIN public.hubs h ON h.id = gch.hub_id
    JOIN public.hub_members hm ON hm.hub_id = h.id
    WHERE gch.game_campaign_id = p_campaign_id 
    AND hm.profile_id = p_influencer_id
    LIMIT 1;

    -- 3. Calculate Curation Fee (10% of influencer reward)
    IF v_hub_owner_id IS NOT NULL AND v_hub_owner_id != p_influencer_id THEN
        v_curation_fee := p_coins_earned * 0.1;
    END IF;

    -- 4. Record the interaction
        campaign_id,
        influencer_id,
        trigger_word,
        success,
        coins_earned,
        created_at
    ) VALUES (
        p_campaign_id,
        p_influencer_id,
        p_trigger_word,
        p_success,
        p_coins_earned,
        NOW()
    );

    -- 5. Only process rewards if successful
    IF p_success THEN
        -- Calculate total cost (reward + curation fee)
        v_amount_to_deduct := COALESCE(p_full_cost, p_coins_earned + v_curation_fee);
        
        -- Update campaign stats
        UPDATE public.game_campaigns
        SET 
            spent_amount = COALESCE(spent_amount,0) + v_amount_to_deduct,
            total_interactions = COALESCE(total_interactions,0) + 1,
            successful_interactions = COALESCE(successful_interactions,0) + 1
        WHERE id = p_campaign_id;

        -- Pay Influencer (both game_coins and brandible_coins)
        UPDATE public.profiles
        SET 
            game_coins = COALESCE(game_coins,0) + p_coins_earned,
            brandible_coins = COALESCE(brandible_coins,0) + p_coins_earned
        WHERE id = p_influencer_id;

        -- Record influencer transaction
            user_id,
            type,
            amount,
            description,
            reference_type,
            reference_id
        ) VALUES (
            p_influencer_id,
            'earned',
            p_coins_earned,
            'Campaign reward for trigger word: ' || p_trigger_word,
            'campaign_interaction',
            p_campaign_id
        );

        -- Pay Hub Owner (10% Curation Fee)
        IF v_hub_owner_id IS NOT NULL AND v_curation_fee > 0 THEN
            UPDATE public.profiles 
            SET brandible_coins = COALESCE(brandible_coins,0) + v_curation_fee 
            WHERE id = v_hub_owner_id;

            -- Record curation transaction
                user_id,
                type,
                amount,
                description,
                reference_type,
                reference_id
            ) VALUES (
                v_hub_owner_id, 
                'earned',
                v_curation_fee, 
                'Curation fee from game trigger: ' || p_trigger_word || ' (member: ' || p_influencer_id || ')',
                'curation_reward',
                p_campaign_id
            );
        END IF;

        -- Get new balance for response
        SELECT brandible_coins INTO v_new_balance
        FROM public.profiles
        WHERE id = p_influencer_id;

        RETURN jsonb_build_object(
            'success', true,
            'message', 'Campaign reward granted! You earned ' || p_coins_earned || ' coins!' || 
                       CASE WHEN v_curation_fee > 0 THEN ' Hub owner earned ' || v_curation_fee || ' coins curation fee.' ELSE '' END,
            'new_balance', v_new_balance,
            'coins_earned', p_coins_earned,
            'curation_fee', v_curation_fee,
            'hub_owner_id', v_hub_owner_id
        );
    ELSE
        -- Unsuccessful interaction - just record, no payments
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Incorrect trigger word. Try again!',
            'coins_earned', 0
        );
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Error: ' || SQLERRM,
            'error_detail', SQLSTATE
        );
END;
$$;


--
-- TOC entry 757 (class 1255 OID 42612)
-- Name: record_media_view_with_reward(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_media_view_with_reward(p_media_id uuid, p_viewer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_media RECORD;
  v_status_post RECORD;
  v_reward_given BOOLEAN := FALSE;
  v_reward_amount NUMERIC := 0;
  v_curation_fee NUMERIC := 0;
  v_total_payout NUMERIC := 0;
  v_total_rewards_given INTEGER;
  v_existing_referral uuid;
  v_hub_id UUID;
  v_hub_owner_id UUID;
  v_is_eligible BOOLEAN := FALSE;
  v_message TEXT := 'View recorded';
  v_error_code TEXT := NULL;
  v_already_viewed BOOLEAN := FALSE;
BEGIN
  -- 1. Check referral eligibility (Legacy protection)
  SELECT id INTO v_existing_referral FROM referrals
  WHERE referee_id = p_viewer_id AND status_media_id = p_media_id AND status = 'completed' LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object('success', false, 'reward_given', false, 'message', 'Already earned via referral', 'error_code', 'ALREADY_EARNED_VIA_REFERRAL');
  END IF;

  -- 2. Get media and status with ROW LOCK
  SELECT * INTO v_media FROM status_media WHERE id = p_media_id FOR UPDATE;
  IF v_media IS NULL THEN RETURN jsonb_build_object('success', false, 'message', 'Media not found'); END IF;

  SELECT * INTO v_status_post FROM status_posts WHERE id = v_media.status_post_id FOR UPDATE;

  -- 3. ELIGIBILITY CHECK: Hub Targeting
  IF v_status_post.is_private = false THEN
      v_is_eligible := TRUE;
  ELSE
      SELECT h.id, h.owner_id INTO v_hub_id, v_hub_owner_id
      FROM public.status_post_hubs sph
      JOIN public.hubs h ON sph.hub_id = h.id
      JOIN public.hub_members hm ON hm.hub_id = h.id
      WHERE sph.status_post_id = v_status_post.id
      AND hm.profile_id = p_viewer_id
      LIMIT 1;

      IF v_hub_id IS NOT NULL THEN
          v_is_eligible := TRUE;
      END IF;
  END IF;

  IF NOT v_is_eligible THEN
      RETURN jsonb_build_object('success', false, 'message', 'This community content is restricted.', 'error_code', 'RESTRICTED_COMMUNITY');
  END IF;

  -- 4. Impression Tracking
  UPDATE status_media SET impression_count = impression_count + 1 WHERE id = p_media_id;
  UPDATE status_posts SET impression_count = impression_count + 1 WHERE id = v_media.status_post_id;

  -- 5. Duplicate View Check
  v_already_viewed := EXISTS (SELECT 1 FROM status_views WHERE media_id = p_media_id AND viewer_id = p_viewer_id);
  IF v_already_viewed THEN
    RETURN jsonb_build_object('success', true, 'reward_given', false, 'message', 'Already viewed', 'error_code', 'ALREADY_VIEWED', 'impression_recorded', true);
  END IF;

  -- 6. Budget Check & Reward Calculation
  SELECT COALESCE(SUM(current_rewards_given), 0) INTO v_total_rewards_given FROM status_media WHERE status_post_id = v_media.status_post_id;

  v_reward_amount := v_media.reward_per_view;
  
  -- Calculate TOTAL payout (reward + 10% fee if applicable)
  IF v_hub_owner_id IS NOT NULL THEN
    v_curation_fee := v_reward_amount * 0.10;
    v_total_payout := v_reward_amount + v_curation_fee;
  ELSE
    v_total_payout := v_reward_amount;
  END IF;

  IF v_total_rewards_given < v_status_post.reward_limit AND v_status_post.reserved_funds >= v_total_payout THEN
    v_reward_given := TRUE;

    -- Update Counts
    UPDATE status_media SET current_rewards_given = current_rewards_given + 1, view_count = view_count + 1 WHERE id = p_media_id;
    UPDATE status_posts SET current_rewards_given = current_rewards_given + 1, view_count = view_count + 1, reserved_funds = GREATEST(0, reserved_funds - v_total_payout) WHERE id = v_media.status_post_id;

    -- Reward Viewer
    UPDATE profiles SET brandible_coins = brandible_coins + v_reward_amount, total_earned = total_earned + v_reward_amount WHERE id = p_viewer_id;
    VALUES (p_viewer_id, 'earned', v_reward_amount, 'Reward for viewing ' || v_status_post.title, p_media_id, 'status_media_view');

    -- Reward Hub Owner (The 10% Kickback)
    IF v_hub_owner_id IS NOT NULL AND v_hub_owner_id != p_viewer_id THEN
        UPDATE profiles SET brandible_coins = brandible_coins + v_curation_fee WHERE id = v_hub_owner_id;
        VALUES (v_hub_owner_id, 'earned', v_curation_fee, 'Curation fee from member view: ' || v_status_post.title, p_media_id, 'hub_curation_fee');
    END IF;

    v_message := 'Reward earned! Check your wallet.';
  ELSE
    -- Budget exhausted fallback
    UPDATE status_media SET view_count = view_count + 1 WHERE id = p_media_id;
    UPDATE status_posts SET view_count = view_count + 1 WHERE id = v_media.status_post_id;
    v_message := 'Aww, you''re late! Reward budget exhausted. Support the brand by viewing!';
    v_error_code := 'BUDGET_EXHAUSTED';
  END IF;

  -- 7. Record the UNIQUE view
  VALUES (v_media.status_post_id, p_viewer_id, v_reward_given, p_media_id);

  RETURN jsonb_build_object(
    'success', true,
    'reward_given', v_reward_given,
    'reward_amount', v_reward_amount,
    'curation_fee_paid', (v_hub_owner_id IS NOT NULL AND v_reward_given),
    'message', v_message,
    'error_code', v_error_code,
    'impression_recorded', true
  );
END;
$$;


--
-- TOC entry 764 (class 1255 OID 26810)
-- Name: record_status_view_with_reward(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_status_view_with_reward(p_status_id uuid, p_viewer_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status RECORD;
  v_reward_given BOOLEAN := FALSE;
  v_reward_amount NUMERIC := 0;
BEGIN
  -- Get status details with row lock
  SELECT * INTO v_status
  FROM status_posts
  WHERE id = p_status_id
  FOR UPDATE;
  
  -- Check if user already viewed
  IF EXISTS (
    SELECT 1 FROM status_views 
    WHERE status_post_id = p_status_id AND viewer_id = p_viewer_id
  ) THEN
    RETURN json_build_object(
      'success', FALSE,
      'message', 'Already viewed',
      'reward_given', FALSE
    );
  END IF;
  
  -- Check if rewards are still available
  IF v_status.current_rewards_given < v_status.reward_limit AND v_status.reserved_funds >= v_status.reward_amount THEN
    v_reward_given := TRUE;
    v_reward_amount := v_status.reward_amount;
    
    -- Update reward count AND decrement reserved_funds
    UPDATE status_posts
    SET 
        current_rewards_given = current_rewards_given + 1,
        reserved_funds = GREATEST(0, reserved_funds - v_reward_amount)
    WHERE id = p_status_id;
    
    -- Update user's coin balance
    UPDATE profiles 
    SET 
    brandible_coins = brandible_coins + v_reward_amount,
    total_earned = total_earned + v_reward_amount
    WHERE id = p_viewer_id;

    -- Record the transaction
      user_id, 
      type, 
      amount, 
      description, 
      reference_id, 
      reference_type
    ) VALUES (
      p_viewer_id,
      'earned',
      v_reward_amount,
      'Reward for viewing status',
      p_status_id,
      'status_view'
    );
    
  END IF;
  
  -- Insert view record
  VALUES (p_status_id, p_viewer_id, v_reward_given);
  
  -- Update view count
  UPDATE status_posts
  SET view_count = view_count + 1
  WHERE id = p_status_id;
  
  RETURN json_build_object(
    'success', TRUE,
    'reward_given', v_reward_given,
    'reward_amount', v_reward_amount
  );
END;
$$;


--
-- TOC entry 748 (class 1255 OID 26704)
-- Name: record_survey_view(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_survey_view(p_status_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_already_viewed BOOLEAN;
  v_new_view_count INTEGER;
BEGIN
  -- Check if user already viewed this post
  SELECT EXISTS (
    SELECT 1 FROM status_views 
    WHERE status_post_id = p_status_id AND viewer_id = p_user_id
  ) INTO v_already_viewed;

  IF v_already_viewed THEN
    RETURN jsonb_build_object(
      'success', true,
      'new_view', false,
      'message', 'User already viewed this post'
    );
  END IF;

  -- Insert the view record
  VALUES (p_status_id, p_user_id, false);

  -- Update the view count
  UPDATE status_posts 
  SET view_count = COALESCE(view_count, 0) + 1
  WHERE id = p_status_id
  RETURNING view_count INTO v_new_view_count;

  RETURN jsonb_build_object(
    'success', true,
    'new_view', true,
    'new_view_count', v_new_view_count
  );
END;
$$;


--
-- TOC entry 654 (class 1255 OID 202369)
-- Name: record_unboxed_sale(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_unboxed_sale(p_chat_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_chat RECORD;
    v_submission RECORD;
    v_reward DECIMAL;
    v_rows_affected INTEGER;
BEGIN
    -- Get chat and verify it's linked to an unboxed submission
    SELECT * INTO v_chat FROM public.chats WHERE id = p_chat_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Chat not found');
    END IF;
    
    IF v_chat.unboxed_submission_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'This chat did not originate from an unboxed video');
    END IF;

    -- Get submission details with lock
    SELECT * INTO v_submission FROM public.unboxed_submissions 
    WHERE id = v_chat.unboxed_submission_id
    FOR UPDATE;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Associated unboxed submission not found');
    END IF;

    -- Store the reward amount for this transaction
    v_reward := v_submission.referral_reward;

    -- ATOMIC UPDATE: Deduct from reserved budget only if sufficient funds exist
    UPDATE public.unboxed_submissions
    SET reserved_budget = reserved_budget - v_reward,
        total_sales_count = total_sales_count + 1,
        total_earned_by_influencer = total_earned_by_influencer + v_reward,
        updated_at = NOW()
    WHERE id = v_submission.id
    AND reserved_budget >= v_reward;

    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
    
    IF v_rows_affected = 0 THEN
        -- Budget exhausted; mark submission as inactive
        UPDATE public.unboxed_submissions 
        SET status = 'inactive', updated_at = NOW()
        WHERE id = v_submission.id AND status = 'approved';
        
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient referral budget. Submission is now inactive.');
    END IF;

    -- Pay Influencer
    UPDATE public.profiles
    SET brandible_coins = brandible_coins + v_reward,
        total_earned = total_earned + v_reward,
        updated_at = NOW()
    WHERE id = v_submission.influencer_id;

    -- Record Payout Transaction
    VALUES (v_submission.influencer_id, 'earned', v_reward, 'Unboxed referral reward from brand', p_chat_id, 'unboxed_sale');

    -- Notify Influencer
    VALUES (
        v_submission.influencer_id,
        'reward',
        'Referral Reward! 💰',
        'You earned ' || v_reward || ' BC from a referral sale!',
        p_chat_id,
        'unboxed_sale',
        jsonb_build_object('chat_id', p_chat_id, 'submission_id', v_submission.id)
    );

    -- Check budget status and notify brand if needed
    IF (v_submission.reserved_budget - v_reward) <= 0 THEN
        -- DEPLETED: Mark inactive and alert brand
        UPDATE public.unboxed_submissions 
        SET status = 'inactive', updated_at = NOW()
        WHERE id = v_submission.id AND status = 'approved';
        
        VALUES (
            v_submission.brand_id,
            'unbox_budget_depleted',
            'Unboxed Budget Depleted!',
            'The referral budget for an unboxed video has run out. The content is now hidden.',
            v_submission.id,
            'unboxed_submission',
            jsonb_build_object('submission_id', v_submission.id)
        );

    ELSIF (v_submission.reserved_budget - v_reward) < (v_reward * 2) THEN
        -- LOW: Alert brand to top up
        VALUES (
            v_submission.brand_id,
            'unbox_budget_low',
            'Unboxed Budget Low!',
            'The referral budget for an unboxed video is almost empty. Top up to keep it active!',
            v_submission.id,
            'unboxed_submission',
            jsonb_build_object('submission_id', v_submission.id)
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Sale recorded and influencer rewarded.',
        'reward_amount', v_reward,
        'influencer_id', v_submission.influencer_id
    );
END;
$$;


