--
-- TOC entry 522 (class 1255 OID 197706)
-- Name: refresh_game_campaign(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_game_campaign(p_campaign_id uuid, p_extension_hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_campaign public.game_campaigns;
  v_extension_interval INTERVAL;
  v_new_expires_at TIMESTAMP WITH TIME ZONE;
  v_old_expires_at TIMESTAMP WITH TIME ZONE;
BEGIN
  -- 1. Fetch and lock campaign
  SELECT * INTO v_campaign
  FROM public.game_campaigns
  WHERE id = p_campaign_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Game campaign not found.');
  END IF;

  -- 2. Security check
  IF auth.uid() != v_campaign.brand_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized: You do not own this campaign.');
  END IF;

  -- 3. Check if campaign can be refreshed (Budget-only check)
  IF v_campaign.spent_amount >= (v_campaign.total_budget - 0.01) THEN
    RETURN jsonb_build_object(
      'success', false, 
      'message', 'Campaign cannot be refreshed as the total budget has been exhausted (' || v_campaign.spent_amount || ' of ' || v_campaign.total_budget || ' coins spent).'
    );
  END IF;

  -- Store old expires_at for logging
  v_old_expires_at := v_campaign.expires_at;

  -- 4. Calculate new expires_at
  IF p_extension_hours IS NOT NULL AND p_extension_hours > 0 THEN
    v_extension_interval := (p_extension_hours || ' hours')::INTERVAL;
  ELSE
    v_extension_interval := '24 hours'::INTERVAL;
  END IF;

  v_new_expires_at := NOW() + v_extension_interval;

  -- 5. Update campaign
  -- ✅ KEY FIX: Update both created_at and duration_hours so the trigger calculates correct expires_at
  -- The trigger will then recalculate: expires_at = created_at + (duration_hours * INTERVAL '1 hour')
  UPDATE public.game_campaigns
  SET
    created_at = NOW(),  -- Reset created_at to now
    duration_hours = p_extension_hours,  -- Set duration to the extension hours
    updated_at = NOW(),
    status = 'active'
    -- ❌ DO NOT set expires_at directly - let the trigger calculate it
  WHERE id = p_campaign_id;

  -- 6. Log activity
  VALUES (
    auth.uid(),
    'brand',
    'game_campaign_refreshed',
    p_campaign_id,
    'game_campaign',
    jsonb_build_object(
      'campaign_name', v_campaign.campaign_name,
      'old_expires_at', v_old_expires_at,
      'new_expires_at', v_new_expires_at,
      'extension_hours', p_extension_hours,
      'remaining_budget', v_campaign.total_budget - v_campaign.spent_amount
    )
  );

  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Game campaign refreshed and extended by ' || p_extension_hours || ' hours successfully.',
    'new_expires_at', v_new_expires_at
  );

EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unexpected error: ' || SQLERRM);
END;
$$;


--
-- TOC entry 579 (class 1255 OID 31097)
-- Name: reject_cashout(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_cashout(transaction_id_to_reject uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_transaction public.transactions;
  v_push_token text;
  v_payload jsonb;
  v_refund_amount numeric;
BEGIN
  -- Check authorization
  IF (get_my_claim('user_type'))::text != 'agent' THEN
    RAISE EXCEPTION 'Only agents can reject cashouts';
  END IF;

  -- Fetch the transaction
  SELECT * INTO v_transaction
  FROM public.transactions
  WHERE id = transaction_id_to_reject;

  -- Guard clause: ensure transaction exists
  IF v_transaction IS NULL THEN
    RAISE EXCEPTION 'Transaction not found: %', transaction_id_to_reject;
  END IF;

  v_refund_amount := -v_transaction.amount;

  -- Update transaction status
  UPDATE public.transactions
  SET status = 'failed'
  WHERE id = transaction_id_to_reject;

  -- Refund coins to user
  UPDATE public.profiles
  SET brandible_coins = brandible_coins + v_refund_amount
  WHERE id = v_transaction.user_id;

  -- Record refund transaction
  VALUES (
    v_transaction.user_id,
    'earned',
    v_refund_amount,
    'Cashout rejected: refund',
    'refund',
    'completed'
  );

  -- Send push notification
  SELECT push_token INTO v_push_token
  FROM public.profiles
  WHERE id = v_transaction.user_id;

  IF v_push_token IS NOT NULL THEN
    v_payload := jsonb_build_object(
      'to', v_push_token,
      'title', 'Cashout Rejected',
      'body', 'Your cashout request for ' || v_refund_amount || ' coins has been rejected. The coins have been returned to your wallet.'
    );

    PERFORM net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      body := v_payload,
      headers := '{"Content-Type": "application/json"}'::jsonb
    );
  END IF;
END;
$$;


