--
-- TOC entry 837 (class 1255 OID 38690)
-- Name: reject_private_invite_release_escrow(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_private_invite_release_escrow(p_invite_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_invite public.private_campaign_invites;
  v_status_post public.status_posts;
  v_brand_profile public.profiles;
  v_influencer_profile public.profiles;
  v_amount_to_release NUMERIC(10,2);
BEGIN
  -- 1. Fetch the invite record and lock it
  SELECT * INTO v_invite
  FROM public.private_campaign_invites
  WHERE id = p_invite_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Private campaign invite with ID % not found.', p_invite_id;
  END IF;

  IF v_invite.status != 'pending' THEN
    RAISE EXCEPTION 'Invite is not in pending status and cannot be rejected.';
  END IF;

  -- 2. Fetch related status_post and brand profile, and lock them
  SELECT * INTO v_status_post
  FROM public.status_posts
  WHERE id = v_invite.status_post_id
  FOR UPDATE;

  SELECT * INTO v_brand_profile
  FROM public.profiles
  WHERE id = v_status_post.brand_id
  FOR UPDATE;

  -- 3. Security Check: Only the invited influencer or the brand owner can reject
  IF auth.uid() != v_invite.influencer_id AND auth.uid() != v_status_post.brand_id THEN
    RAISE EXCEPTION 'Unauthorized: Only the invited influencer or brand owner can reject this invite.';
  END IF;

  -- 4. Determine amount to release
  v_amount_to_release := v_invite.invite_cost; -- Use the cost stored with the invite

  IF v_amount_to_release IS NULL OR v_amount_to_release <= 0 THEN
    RAISE EXCEPTION 'Invite cost is invalid or not set for invite %.', p_invite_id;
  END IF;

  -- 5. Release funds back to brand's balance
  UPDATE public.profiles
  SET brandible_coins = brandible_coins + v_amount_to_release
  WHERE id = v_brand_profile.id;

  -- 6. Deduct from status_posts.reserved_funds
  UPDATE public.status_posts
  SET reserved_funds = reserved_funds - v_amount_to_release
  WHERE id = v_status_post.id;

  -- 7. Record transaction for brand (escrow released)
  VALUES (
    v_brand_profile.id,
    'escrow_released', -- New type for released escrow funds
    v_amount_to_release, -- Positive amount for adding back to balance
    'Coins released from escrow due to invite rejection for campaign: ' || v_status_post.title,
    p_invite_id,
    'private_invite_rejection'
  );

  -- 8. Update private_campaign_invites status
  UPDATE public.private_campaign_invites
  SET status = 'declined', updated_at = NOW() -- <--- Changed 'rejected' to 'declined'
  WHERE id = p_invite_id;

  RETURN jsonb_build_object('success', true, 'message', 'Invite rejected and funds released.');

EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Invite rejection failed: %', SQLERRM;
END;
$$;


--
-- TOC entry 609 (class 1255 OID 23888)
-- Name: reject_purchase(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_purchase(p_purchase_id uuid, p_rejection_reason text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_agent_id uuid;
    v_user_type text;
    v_purchase_exists boolean;
BEGIN
    -- 1️⃣ Get authenticated user
    SELECT auth.uid() INTO v_agent_id;
    IF v_agent_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Unauthorized: no authenticated user.');
    END IF;

    -- 2️⃣ Verify user is an agent
    SELECT user_type INTO v_user_type
    FROM public.profiles
    WHERE id = v_agent_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RETURN json_build_object('success', false, 'message', 'Access denied: only agents can reject purchases.');
    END IF;

    -- 3️⃣ Check if the purchase exists and is pending fulfillment or shipped
    SELECT EXISTS (
        SELECT 1
        FROM public.purchases
        WHERE id = p_purchase_id
        AND status IN ('pending_fulfillment', 'shipped')
    ) INTO v_purchase_exists;

    IF NOT v_purchase_exists THEN
        RETURN json_build_object('success', false, 'message', 'Purchase not found or not in a rejectable state.');
    END IF;

    -- 4️⃣ Mark as rejected
    UPDATE public.purchases
    SET
        status = 'rejected',
        agent_id = v_agent_id,
        rejection_reason = p_rejection_reason,
        updated_at = now()
    WHERE id = p_purchase_id;

    -- 5️⃣ Optionally: refund coins to buyer if coins were pre-held (uncomment if needed)
    /*
    UPDATE public.profiles
    SET brandible_coins = brandible_coins + v_purchase.total_coins
    WHERE id = v_purchase.buyer_id;
    */

    -- 6️⃣ Return response
    RETURN json_build_object('success', true, 'message', 'Purchase rejected successfully.');

EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$$;


--
-- TOC entry 527 (class 1255 OID 202371)
-- Name: reject_unboxed_submission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_unboxed_submission(p_submission_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_submission RECORD;
    v_refund_amount DECIMAL;
BEGIN
    -- Get submission details
    SELECT * INTO v_submission FROM public.unboxed_submissions WHERE id = p_submission_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Submission not found');
    END IF;

    -- Calculate refund
    v_refund_amount := v_submission.reserved_budget;

    -- Only refund if there's budget to return
    IF v_refund_amount > 0 THEN
        UPDATE public.profiles
        SET brandible_coins = brandible_coins + v_refund_amount,
            updated_at = NOW()
        WHERE id = v_submission.brand_id;

        VALUES (v_submission.brand_id, 'earned', v_refund_amount, 
                'Refund for rejected unboxed submission: ' || COALESCE(p_reason, 'No reason provided'), 
                p_submission_id, 'unboxed_refund');
    END IF;

    -- Mark submission as rejected
    UPDATE public.unboxed_submissions
    SET status = 'rejected',
        reserved_budget = 0,
        updated_at = NOW()
    WHERE id = p_submission_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Submission rejected and escrowed budget refunded.',
        'refunded_amount', v_refund_amount,
        'reason', p_reason
    );
END;
$$;


--
-- TOC entry 517 (class 1255 OID 38754)
-- Name: release_unused_challenge_escrow(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_unused_challenge_escrow(p_status_post_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_status_post public.status_posts;
  v_brand_profile public.profiles;
  v_amount_to_release NUMERIC(10,2);
BEGIN
  -- 1. Fetch the status_post record and lock it
  SELECT * INTO v_status_post
  FROM public.status_posts
  WHERE id = p_status_post_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Status Post with ID % not found.', p_status_post_id;
  END IF;

  -- 2. Fetch brand profile and lock it
  SELECT * INTO v_brand_profile
  FROM public.profiles
  WHERE id = v_status_post.brand_id
  FOR UPDATE;

  -- 3. Security Check: Only the brand owner or an agent can release unused funds
  IF auth.uid() != v_status_post.brand_id AND (SELECT user_type FROM public.profiles WHERE id = auth.uid()) != 'agent' THEN
    RAISE EXCEPTION 'Unauthorized: Only the brand owner or an agent can release unused funds for this challenge.';
  END IF;

  -- 4. Determine amount to release
  v_amount_to_release := v_status_post.reserved_funds;

  IF v_amount_to_release IS NULL OR v_amount_to_release <= 0 THEN
    RETURN jsonb_build_object('success', true, 'message', 'No unused funds to release for this challenge.');
  END IF;

  -- 5. Release funds back to brand's balance
  UPDATE public.profiles
  SET brandible_coins = brandible_coins + v_amount_to_release
  WHERE id = v_brand_profile.id;

  -- 6. Set status_posts.reserved_funds to 0
  UPDATE public.status_posts
  SET reserved_funds = 0.00
  WHERE id = p_status_post_id;

  -- 7. Record transaction for brand (escrow released)
  VALUES (
    v_brand_profile.id,
    'escrow_released',
    v_amount_to_release, -- Positive amount for adding back to balance
    'Unused coins released from escrow for challenge: ' || v_status_post.title,
    p_status_post_id,
    'challenge_escrow_release'
  );

  RETURN jsonb_build_object('success', true, 'message', 'Unused funds released successfully.');

EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Release unused funds failed: %', SQLERRM;
END;
$$;


--
-- TOC entry 711 (class 1255 OID 197694)
-- Name: reset_game_level(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_game_level(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_details JSON;
    v_penalty_amount DECIMAL;
    v_game_balance DECIMAL;
    v_penalty_percent DECIMAL;
    v_can_afford BOOLEAN;
BEGIN

    v_details := get_game_reset_details(p_user_id);

    v_penalty_amount := (v_details->>'penalty_amount')::DECIMAL;
    v_game_balance := (v_details->>'current_game_balance')::DECIMAL;
    v_penalty_percent := (v_details->>'penalty_percentage')::DECIMAL;
    v_can_afford := (v_details->>'can_afford')::BOOLEAN;

    IF NOT v_can_afford THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Insufficient coins to pay the level reset penalty of ' || v_penalty_amount || ' coins.'
        );
    END IF;

    -- FIXED: Deduct ONLY from game_coins
    UPDATE public.profiles
    SET game_coins = game_coins - v_penalty_amount
    WHERE id = p_user_id;

    UPDATE public.user_game_progress
    SET max_level_reached = 1,
        updated_at = NOW()
    WHERE user_id = p_user_id;

        user_id,
        type,
        amount,
        description,
        reference_type
    ) VALUES (
        p_user_id,
        'spent',
        -v_penalty_amount,
        'Level reset penalty (' || v_penalty_percent || '% of ' || v_game_balance || ' game coins)',
        'level_reset_penalty'
    );

    RETURN json_build_object(
        'success', true,
        'message', 'Level reset successful.',
        'new_balance', (v_game_balance - v_penalty_amount)
    );

END;
$$;


