--

CREATE FUNCTION public.restart_game_campaign(p_campaign_id uuid, p_brand_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_campaign RECORD;
BEGIN
  -- Get campaign details
  SELECT * INTO v_campaign 
  FROM game_campaigns 
  WHERE id = p_campaign_id AND brand_id = p_brand_id;
  
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'message', 'Campaign not found');
  END IF;

  -- Reset status to active and update created_at to restart duration
  UPDATE game_campaigns 
  SET status = 'active',
      created_at = NOW()
  WHERE id = p_campaign_id;
  
  RETURN json_build_object(
    'success', true, 
    'message', 'Campaign restarted successfully'
  );
END;
$$;


--
-- TOC entry 722 (class 1255 OID 215874)
-- Name: save_campaign_hubs(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_campaign_hubs(p_status_post_id uuid, p_hub_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_inserted_count INTEGER;
BEGIN
  -- Validate status_post_id
  IF p_status_post_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Status post ID cannot be null'
    );
  END IF;

  -- Delete any existing mappings (for updates)
  DELETE FROM public.status_post_hubs 
  WHERE status_post_id = p_status_post_id;
  
  -- Insert new mappings only if hub_ids provided
  IF p_hub_ids IS NOT NULL AND array_length(p_hub_ids, 1) > 0 THEN
    SELECT p_status_post_id, unnest(p_hub_ids);
    
    GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
  ELSE
    v_inserted_count := 0;
  END IF;
  
  RETURN jsonb_build_object(
    'success', true,
    'hubs_linked', v_inserted_count
  );
  
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM
  );
END;
$$;


--
-- TOC entry 559 (class 1255 OID 219382)
