--

CREATE FUNCTION public.save_game_campaign_hubs(p_campaign_id uuid, p_hub_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- 1. Remove existing associations
    DELETE FROM public.game_campaign_hubs WHERE game_campaign_id = p_campaign_id;

    -- 2. Insert new associations
    IF p_hub_ids IS NOT NULL AND array_length(p_hub_ids, 1) > 0 THEN
        SELECT p_campaign_id, unnest(p_hub_ids);
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$$;


--
-- TOC entry 604 (class 1255 OID 169972)
-- Name: search_brand_media(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_brand_media(search_query text, limit_count integer DEFAULT 50) RETURNS TABLE(id uuid, brand_id uuid, media_url text, media_type text, caption text, keywords text[], thumbnail_url text, created_at timestamp with time zone, brand_username text, brand_profile_image text, relevance_score double precision)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        sbm.id,
        sbm.brand_id,
        sbm.media_url,
        sbm.media_type,
        sbm.caption,
        sbm.keywords,
        sbm.thumbnail_url,
        sbm.created_at,
        sbm.brand_username,
        sbm.brand_profile_image,
        -- Calculate relevance score based on keyword matches and caption similarity
        (
            -- Keyword exact match boost
            CASE 
                WHEN sbm.keywords && string_to_array(lower(search_query), ' ') THEN 10.0
                ELSE 0.0
            END +
            -- Caption full-text search score
            ts_rank(
                to_tsvector('english', COALESCE(sbm.caption, '')),
                plainto_tsquery('english', search_query)
            ) * 5.0 +
            -- Brand name match
            CASE 
                WHEN lower(sbm.brand_username) LIKE lower('%' || search_query || '%') THEN 3.0
                ELSE 0.0
            END
        ) as relevance_score
    FROM public.searchable_brand_media sbm
    WHERE 
        -- Search in keywords
        sbm.keywords && string_to_array(lower(search_query), ' ')
        OR 
        -- Search in caption using full-text search
        to_tsvector('english', COALESCE(sbm.caption, '')) @@ plainto_tsquery('english', search_query)
        OR
        -- Search in brand username
        lower(sbm.brand_username) LIKE lower('%' || search_query || '%')
    ORDER BY relevance_score DESC, sbm.created_at DESC
    LIMIT limit_count;
END;
$$;


