--
-- TOC entry 552 (class 1255 OID 172322)
-- Name: send_new_status_post_notification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_new_status_post_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$DECLARE
    v_influencer_profile RECORD;
    v_notification_title TEXT;
    v_notification_body TEXT;
    v_payload JSONB;
    v_target_screen TEXT;
    v_brand_profile RECORD;
    v_error_message TEXT;
BEGIN
    SELECT username INTO v_brand_profile FROM public.profiles WHERE id = NEW.brand_id;

    -- Type-specific messaging (from second function)
    IF NEW.type = 'challenge' THEN
        v_notification_title := 'New Challenge Alert! 🚀';
        v_notification_body := v_brand_profile.username || ' just posted a new challenge: "' || NEW.title || '". Join now to earn coins!';
        v_target_screen := 'ChallengeDetail';
    ELSIF NEW.type = 'survey' THEN
        v_notification_title := 'New Survey Available! 📝';
        v_notification_body := v_brand_profile.username || ' has a new survey: "' || NEW.title || '". Share your thoughts and get rewarded!';
        v_target_screen := 'SurveyDetail';
    ELSE -- status_view or other types
        v_notification_title := 'New Post from ' || v_brand_profile.username || '!';
        v_notification_body := v_brand_profile.username || ' just shared new content: "' || NEW.title || '". Check it out!';
        v_target_screen := 'StatusPostDetail';
    END IF;

    -- Location-aware + hub-aware influencer selection (from first function)
    FOR v_influencer_profile IN
        SELECT DISTINCT p.id, p.push_token
        FROM public.profiles p
        WHERE p.user_type = 'influencer'
          AND p.push_token IS NOT NULL
          AND (p.notification_preferences->>'new_status_post_created')::boolean IS TRUE
          AND (
            -- Case 1: Post is Public
            (NEW.is_private = false AND (
                array_length(NEW.target_locations, 1) IS NULL 
                OR p.state = ANY(NEW.target_locations)
            ))
            OR 
            -- Case 2: Post is Private, Hub AND Location check
            (NEW.is_private = true AND EXISTS (
                SELECT 1 FROM public.status_post_hubs sph
                JOIN public.hub_members hm ON hm.hub_id = sph.hub_id
                WHERE sph.status_post_id = NEW.id
                AND hm.profile_id = p.id
            ) AND (
                array_length(NEW.target_locations, 1) IS NULL 
                OR p.state = ANY(NEW.target_locations)
            ))
          )
    LOOP
        -- Push Notification
        IF v_influencer_profile.push_token IS NOT NULL THEN
            v_payload := jsonb_build_object(
                'to', v_influencer_profile.push_token,
                'title', v_notification_title,
                'body', v_notification_body,
                'data', jsonb_build_object(
                    'type', 'new_status_post',
                    'status_post_id', NEW.id,
                    'target_screen', v_target_screen
                )
            );
        BEGIN
            PERFORM net.http_post(
                url := 'https://exp.host/--/api/v2/push/send',
                body := v_payload,
                headers := '{"Content-Type": "application/json"}'::jsonb
            );
        EXCEPTION WHEN OTHERS THEN
                v_error_message := SQLERRM;
                RAISE WARNING 'Failed to send push notification to influencer %: %', v_influencer_profile.id, v_error_message;
                -- Continue to next influencer instead of crashing
        END;
    END IF;

        -- In-app notification
    BEGIN
        VALUES (
            v_influencer_profile.id, 
            'new_status_post_created', 
            v_notification_title, 
            v_notification_body,
            jsonb_build_object(
                'status_post_id', NEW.id,
                'brand_id', NEW.brand_id,
                'status_post_type', NEW.type,
                'target_screen', v_target_screen
            )
        );
    EXCEPTION WHEN OTHERS THEN
            v_error_message := SQLERRM;
            RAISE WARNING 'Failed to insert in-app notification for influencer %: %', v_influencer_profile.id, v_error_message;
            -- Continue to next influencer instead of crashing
    END;

END LOOP;

    RETURN NEW;
END;$$;


--
-- TOC entry 671 (class 1255 OID 27188)
-- Name: send_private_invites(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_private_invites(p_status_post_id uuid, p_influencer_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_brand_id UUID;
    v_influencer_id UUID;
    v_status_post_exists BOOLEAN;
    v_total_escrow_amount NUMERIC(10,2) := 0.00;
    v_brand_balance NUMERIC(10,2);
    v_influencer_rate NUMERIC(10,2);
    v_campaign_title TEXT;
BEGIN
    RAISE NOTICE '--- STARTING send_private_invites RPC ---';
    RAISE NOTICE 'p_status_post_id: %', p_status_post_id;
    RAISE NOTICE 'p_influencer_ids: %', p_influencer_ids;

    -- Verify status_post_id exists and get brand_id and campaign title
    SELECT brand_id, title INTO v_brand_id, v_campaign_title
    FROM public.status_posts
    WHERE id = p_status_post_id;

    IF v_brand_id IS NULL THEN
        RAISE EXCEPTION 'Status Post with ID % not found.', p_status_post_id;
    END IF;

    RAISE NOTICE 'Found status_post. Brand ID: %, Campaign Title: %', v_brand_id, v_campaign_title;

    -- Security Check: Ensure the caller is the brand who owns the campaign.
    IF auth.uid() != v_brand_id THEN
        RAISE EXCEPTION 'Only the brand owner can send invites for this campaign.';
    END IF;

    -- Calculate total escrow amount based on individual influencer rates
    FOREACH v_influencer_id IN ARRAY p_influencer_ids -- <--- Corrected to FOREACH
    LOOP
        SELECT private_campaign_rate INTO v_influencer_rate
        FROM public.profiles
        WHERE id = v_influencer_id;

        IF v_influencer_rate IS NULL OR v_influencer_rate <= 0 THEN
            RAISE EXCEPTION 'Influencer % does not have a valid private campaign rate set.', v_influencer_id;
        END IF;
        v_total_escrow_amount := v_total_escrow_amount + v_influencer_rate;
    END LOOP;

    RAISE NOTICE 'Calculated total escrow amount: %', v_total_escrow_amount;

    -- Fetch brand's current balance and lock the row for update
    SELECT brandible_coins INTO v_brand_balance
    FROM public.profiles
    WHERE id = v_brand_id
    FOR UPDATE; -- Lock the row to prevent race conditions

    RAISE NOTICE 'Brand current balance: %', v_brand_balance;

    -- Check if brand has sufficient balance
    IF v_brand_balance < v_total_escrow_amount THEN
        RAISE EXCEPTION 'Insufficient Brandible Coins. Current balance: %, required: % for sending invites.', v_brand_balance, v_total_escrow_amount;
    END IF;

    -- Deduct coins from brand's balance
    UPDATE public.profiles
    SET brandible_coins = brandible_coins - v_total_escrow_amount
    WHERE id = v_brand_id;

    RAISE NOTICE 'Deducted % coins from brand % balance.', v_total_escrow_amount, v_brand_id;

    -- Update status_posts.reserved_funds
    UPDATE public.status_posts
    SET reserved_funds = reserved_funds + v_total_escrow_amount
    WHERE id = p_status_post_id;

    RAISE NOTICE 'Updated reserved_funds for status_post % by %.', p_status_post_id, v_total_escrow_amount;

    -- Record transaction for coin deduction (as escrowed)
    VALUES (
      v_brand_id,
      'escrowed',
      -v_total_escrow_amount, -- Negative amount for deduction
      'Coins escrowed for private invites to campaign: ' || v_campaign_title,
      p_status_post_id,
      'private_invite_escrow'
    );

    RAISE NOTICE 'Recorded escrow transaction.';

    -- Insert an invitation for each selected influencer.
    FOREACH v_influencer_id IN ARRAY p_influencer_ids
    LOOP
        -- Fetch influencer's rate again to store with the invite
        SELECT private_campaign_rate INTO v_influencer_rate
        FROM public.profiles
        WHERE id = v_influencer_id;

        VALUES (p_status_post_id, v_influencer_id, COALESCE(v_influencer_rate, 0))
        ON CONFLICT (status_post_id, influencer_id) DO NOTHING;
        RAISE NOTICE 'Inserted invite for influencer % with cost %.', v_influencer_id, COALESCE(v_influencer_rate, 0);
    END LOOP;

    RAISE NOTICE '--- send_private_invites RPC END ---';
END;
$$;


