--
-- TOC entry 830 (class 1255 OID 27096)
-- Name: set_private_rate(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_private_rate(p_new_rate numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_is_eligible BOOLEAN;
BEGIN
    -- Check for eligibility: user must have at least one featured submission
    SELECT EXISTS (
        SELECT 1 FROM public.challenge_submissions
        WHERE participant_id = auth.uid() AND is_featured = true
    ) INTO v_is_eligible;

    IF NOT v_is_eligible THEN
        RAISE EXCEPTION 'Only creators with featured submissions can set a private rate.';
    END IF;

    -- Input validation
    IF p_new_rate < 0 THEN
        RAISE EXCEPTION 'Rate must be a positive number.';
    END IF;

    -- Update the profile
    UPDATE public.profiles
    SET private_campaign_rate = p_new_rate
    WHERE id = auth.uid();
END;
$$;


