--
-- TOC entry 571 (class 1255 OID 54854)
-- Name: start_public_chain(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_public_chain(p_campaign_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_campaign_type VARCHAR(20);
    v_campaign_status VARCHAR(20);
    v_user_id UUID := auth.uid();
    v_existing_chain_id UUID;
    v_new_chain_id UUID;
BEGIN
    -- 1. Verify the campaign is an active, public campaign
    SELECT campaign_type, status INTO v_campaign_type, v_campaign_status
    FROM pass_it_campaigns
    WHERE id = p_campaign_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Campaign not found: %', p_campaign_id;
    END IF;

    IF v_campaign_type IS DISTINCT FROM 'public' THEN
        RAISE EXCEPTION 'This campaign is not public and chains cannot be started freely.';
    END IF;

    IF v_campaign_status IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION 'This campaign is not active.';
    END IF;

    -- 2. Check if the user has already started a chain for this campaign
    SELECT id INTO v_existing_chain_id
    FROM pass_it_chains
    WHERE campaign_id = p_campaign_id AND starter_influencer_id = v_user_id;

    IF v_existing_chain_id IS NOT NULL THEN
        RAISE EXCEPTION 'You have already started a chain for this campaign.';
    END IF;

    -- 3. Create the new chain with the current user as the starter
    VALUES (p_campaign_id, v_user_id)
    RETURNING id INTO v_new_chain_id;

    -- 4. Create the initial invitation for the starter to make the first pass
    VALUES (p_campaign_id, v_new_chain_id, v_user_id, v_user_id, 'pending');
    -- Note: inviter_id and invitee_id are the same for the very first pass.

    RAISE NOTICE 'User % started a new chain % for public campaign %', v_user_id, v_new_chain_id, p_campaign_id;

    RETURN v_new_chain_id;
END;
$$;


--
-- TOC entry 5869 (class 0 OID 0)
-- Dependencies: 571
-- Name: FUNCTION start_public_chain(p_campaign_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.start_public_chain(p_campaign_id uuid) IS 'Allows a user to start a new chain for a public campaign, creating the chain and the initial invitation for the user to act upon.';


--
-- TOC entry 653 (class 1255 OID 55214)
-- Name: submit_pass_it_review(uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_pass_it_review(p_pass_id uuid, p_rating integer, p_review_text text, p_next_influencer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_pass_record pass_it_passes;
    v_campaign_record pass_it_campaigns;
    v_user_id UUID := auth.uid();
    v_new_invitation_id UUID;
BEGIN
    -- 1. Validate and fetch pass details
    SELECT * INTO v_pass_record
    FROM pass_it_passes
    WHERE id = p_pass_id AND reviewer_id = v_user_id AND status = 'pending';

    IF v_pass_record IS NULL THEN
        RAISE EXCEPTION 'Pass not found, already completed, or not for this user.';
    END IF;

    -- 2. Fetch campaign details
    SELECT * INTO v_campaign_record
    FROM pass_it_campaigns
    WHERE id = v_pass_record.campaign_id;

    IF v_campaign_record IS NULL THEN
        RAISE EXCEPTION 'Campaign not found for this pass.';
    END IF;

    -- 3. Update the current pass with the review details
    UPDATE pass_it_passes
    SET
        rating = p_rating,
        review_text = p_review_text,
        next_influencer_id = p_next_influencer_id,
        status = 'completed',
        completed_at = NOW()
    WHERE id = p_pass_id;

    -- 4. Create a new invitation for the next influencer
        campaign_id,
        chain_id,
        inviter_id,
        invitee_id,
        position_in_chain,
        status
    ) VALUES (
        v_pass_record.campaign_id,
        v_pass_record.chain_id,
        v_user_id, -- The current user is the inviter
        p_next_influencer_id,
        v_pass_record.position_in_chain + 1,
        'pending'
    ) RETURNING id INTO v_new_invitation_id;

    -- The check_pass_it_completion trigger will automatically run
    -- when the pass status is updated to 'completed'.

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'message', 'Review submitted and invitation sent.',
        'completed_pass_id', p_pass_id,
        'new_invitation_id', v_new_invitation_id
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN JSONB_BUILD_OBJECT(
            'success', FALSE,
            'message', SQLERRM
        );
END;
$$;


