--
-- TOC entry 741 (class 1255 OID 197691)
-- Name: top_up_game_coins(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.top_up_game_coins(p_user_id uuid, p_amount numeric) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_main_balance DECIMAL;
BEGIN
  -- Get current main balance
  SELECT brandible_coins INTO v_main_balance FROM public.profiles WHERE id = p_user_id;
  
  -- Check if user has enough coins
  IF v_main_balance < p_amount THEN
    RETURN json_build_object('success', false, 'message', 'Insufficient Brandible Coins.');
  END IF;
  
  -- Deduct from main, add to game
  UPDATE public.profiles
  SET brandible_coins = brandible_coins - p_amount,
      game_coins = game_coins + p_amount
  WHERE id = p_user_id;
  
  -- Record transaction
    user_id,
    type,
    amount,
    description,
    reference_type
  ) VALUES (
    p_user_id,
    'transferred',
    -p_amount,
    'Transfer to Game Wallet',
    'game_topup'
  );
  
  RETURN json_build_object('success', true, 'new_game_balance', (SELECT game_coins FROM public.profiles WHERE id = p_user_id));
END;
$$;


--
-- TOC entry 659 (class 1255 OID 203593)
-- Name: top_up_unboxed_budget(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.top_up_unboxed_budget(p_submission_id uuid, p_amount numeric) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_submission RECORD;
  v_brand_id UUID;
  v_brand_profile_id UUID;
  v_brand_balance NUMERIC;
  v_new_budget NUMERIC;
BEGIN
  -- Get submission
  SELECT id, brand_id, status, reserved_budget 
  INTO v_submission
  FROM unboxed_submissions 
  WHERE id = p_submission_id;
  
  IF v_submission IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'Submission not found');
  END IF;
  
  IF v_submission.status != 'approved' THEN
    RETURN json_build_object('success', false, 'message', 'Submission must be approved');
  END IF;
  
  v_brand_id := v_submission.brand_id;
  
  -- Get brand profile
  SELECT profile_id INTO v_brand_profile_id
  FROM brands WHERE id = v_brand_id;
  
  IF v_brand_profile_id IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'Brand profile not found');
  END IF;
  
  -- Check balance
  SELECT brandible_coins INTO v_brand_balance
  FROM profiles WHERE id = v_brand_profile_id;
  
  IF v_brand_balance IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'Wallet not found');
  END IF;
  
  IF v_brand_balance < p_amount THEN
    RETURN json_build_object('success', false, 'message', 'Insufficient balance: ' || v_brand_balance::text || ' BC available, need ' || p_amount::text || ' BC');
  END IF;
  
  -- Deduct from wallet
  UPDATE profiles SET brandible_coins = brandible_coins - p_amount
  WHERE id = v_brand_profile_id;
  
  -- Add to budget
  v_new_budget := v_submission.reserved_budget + p_amount;
  
  UPDATE unboxed_submissions 
  SET reserved_budget = v_new_budget, updated_at = NOW()
  WHERE id = p_submission_id;
  
  -- ✅ Log to transactions with 'escrowed' type
    user_id,
    type,
    amount,
    description,
    reference_id,
    reference_type
  ) VALUES (
    v_brand_profile_id,
    'escrowed',
    -p_amount,
    'Top up budget for unboxing deal',
    p_submission_id,
    'unbox_topup'
  );
  
  -- ✅ Log to activity_logs - details as JSONB
    user_id,
    user_type,
    action_type,
    entity_type,
    entity_id,
    details,  -- ✅ This is JSONB
    metadata,
    timestamp
  ) VALUES (
    v_brand_profile_id,
    'brand',
    'unbox_budget_topped_up',
    'unboxed_submission',
    p_submission_id,
    jsonb_build_object(  -- ✅ Use jsonb_build_object for details
      'top_up_amount', p_amount,
      'new_budget', v_new_budget,
      'action', 'Top up budget for unboxing deal'
    ),
    jsonb_build_object(
      'top_up_amount', p_amount,
      'new_budget', v_new_budget,
      'influencer_id', (SELECT influencer_id FROM unboxed_submissions WHERE id = p_submission_id)
    ),
    NOW()
  );
  
  RETURN json_build_object(
    'success', true, 
    'message', 'Budget topped up successfully',
    'new_budget', v_new_budget
  );
  
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'message', 'Error: ' || SQLERRM);
END;
$$;


--
-- TOC entry 776 (class 1255 OID 31138)
-- Name: transfer_coins_to_friend(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_coins_to_friend(recipient_username text, amount_to_transfer numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  sender_id UUID;
  recipient_id UUID;
  sender_profile public.profiles;
  recipient_profile public.profiles;
  v_push_token_sender TEXT;
  v_push_token_recipient TEXT;
  v_payload JSON;
BEGIN
  -- Get sender and recipient IDs
  sender_id := auth.uid();
  SELECT id INTO recipient_id FROM public.profiles WHERE username = recipient_username;

  -- Validation
  IF recipient_id IS NULL THEN
    RAISE EXCEPTION 'Recipient not found';
  END IF;

  IF sender_id = recipient_id THEN
    RAISE EXCEPTION 'You cannot send coins to yourself';
  END IF;

  SELECT * INTO sender_profile FROM public.profiles WHERE id = sender_id;

  IF sender_profile.brandible_coins < amount_to_transfer THEN
    RAISE EXCEPTION 'Insufficient funds';
  END IF;

  -- Perform the transfer
  UPDATE public.profiles
  SET brandible_coins = brandible_coins - amount_to_transfer
  WHERE id = sender_id;

  UPDATE public.profiles
  SET brandible_coins = brandible_coins + amount_to_transfer
  WHERE id = recipient_id;

  -- Record transactions
  VALUES (sender_id, 'spent', -amount_to_transfer, 'Transfer to ' || recipient_username, 'transfer');

  VALUES (recipient_id, 'earned', amount_to_transfer, 'Transfer from ' || sender_profile.username, 'transfer');

  -- Send sender notification
  SELECT push_token INTO v_push_token_sender FROM public.profiles WHERE id = sender_id;
  IF v_push_token_sender IS NOT NULL THEN
    v_payload := json_build_object(
      'to', v_push_token_sender,
      'title', 'Transfer Sent!',
      'body', 'You sent ' || amount_to_transfer || ' coins to ' || recipient_username || '.'
    );

    PERFORM net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      body := v_payload::text,
      headers := '{"Content-Type": "application/json"}'::jsonb
    );
  END IF;

  -- Send recipient notification
  SELECT push_token INTO v_push_token_recipient FROM public.profiles WHERE id = recipient_id;
  IF v_push_token_recipient IS NOT NULL THEN
    v_payload := json_build_object(
      'to', v_push_token_recipient,
      'title', 'Coins Received!',
      'body', 'You received ' || amount_to_transfer || ' coins from ' || sender_profile.username || '.'
    );

    PERFORM net.http_post(
      url := 'https://exp.host/--/api/v2/push/send',
      body := v_payload::text,
      headers := '{"Content-Type": "application/json"}'::jsonb
    );
  END IF;
END;
$$;


--
-- TOC entry 554 (class 1255 OID 41248)
-- Name: unlock_achievement_if_not_unlocked(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unlock_achievement_if_not_unlocked(p_brand_id uuid, p_achievement_key text, p_activity_log_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_already boolean;
  v_def RECORD;
BEGIN
  -- Ensure we have the achievement definition
  SELECT * INTO v_def FROM public.achievement_definitions
  WHERE key = p_achievement_key AND is_active = true;
  
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Check if already unlocked
  SELECT EXISTS (
    SELECT 1 FROM public.brand_achievements
    WHERE brand_id = p_brand_id AND achievement_key = p_achievement_key
  ) INTO v_already;

  IF v_already THEN
    RETURN;
  END IF;

  -- Insert achievement
  VALUES (p_brand_id, p_achievement_key);

  -- Award coins if defined
  IF v_def.reward_coins IS NOT NULL AND v_def.reward_coins > 0 THEN
    UPDATE public.profiles
    SET brandible_coins = COALESCE(brandible_coins, 0) + v_def.reward_coins,
        total_earned = COALESCE(total_earned, 0) + v_def.reward_coins
    WHERE id = p_brand_id;

    VALUES (
      p_brand_id,
      'achievement_reward',
      v_def.reward_coins,
      'Unlocked achievement: ' || v_def.name,
      p_activity_log_id,
      'activity_log'
    );
  END IF;

  RAISE NOTICE 'Achievement unlocked: % (+% coins) for user: %', 
    v_def.name, v_def.reward_coins, p_brand_id;
END;
$$;


--
-- TOC entry 655 (class 1255 OID 62848)
-- Name: unpublish_blog_post(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unpublish_blog_post(p_post_id uuid) RETURNS public.blog_posts
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_agent_id uuid;
    v_user_type text;
    v_unpublished_post public.blog_posts;
BEGIN
    SELECT auth.uid() INTO v_agent_id;
    SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_agent_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RAISE EXCEPTION 'Only agents can unpublish blog posts.';
    END IF;

    UPDATE public.blog_posts
    SET
        status = 'draft',
        published_at = NULL
    WHERE id = p_post_id
    RETURNING * INTO v_unpublished_post;

    IF v_unpublished_post IS NULL THEN
        RAISE EXCEPTION 'Blog post not found or not authorized to unpublish.';
    END IF;

    RETURN v_unpublished_post;
END;
$$;


