--

CREATE FUNCTION public.unvote_submission(p_submission_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- The RLS policy on submission_upvotes ensures a user can only delete their own vote.
    DELETE FROM public.submission_upvotes
    WHERE submission_id = p_submission_id AND voter_id = auth.uid();
END;
$$;


--
-- TOC entry 518 (class 1255 OID 62846)
-- Name: update_blog_post(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_blog_post(p_post_id uuid, p_title text, p_content text, p_cover_image_url text DEFAULT NULL::text) RETURNS public.blog_posts
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_agent_id uuid;
    v_user_type text;
    v_updated_post public.blog_posts;
BEGIN
    SELECT auth.uid() INTO v_agent_id;
    SELECT user_type INTO v_user_type FROM public.profiles WHERE id = v_agent_id;

    IF v_user_type IS DISTINCT FROM 'agent' THEN
        RAISE EXCEPTION 'Only agents can update blog posts.';
    END IF;

    UPDATE public.blog_posts
    SET
        title = p_title,
        content = p_content,
        cover_image_url = p_cover_image_url,
        created_at = NOW() -- Update timestamp to reflect modification
    WHERE id = p_post_id
    RETURNING * INTO v_updated_post;

    IF v_updated_post IS NULL THEN
        RAISE EXCEPTION 'Blog post not found or not authorized to update.';
    END IF;

    RETURN v_updated_post;
END;
$$;


