--
-- TOC entry 475 (class 1259 OID 197730)
-- Name: game_campaigns_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.game_campaigns_summary AS
 SELECT gc.id AS campaign_id,
    gc.campaign_name,
    gc.campaign_message,
    gc.campaign_link,
    gc.cta_text,
    gc.brand_id,
    b.company_name AS brand_name,
    gc.media_url,
    gc.media_type,
    gc.total_interactions,
    gc.successful_interactions,
    COALESCE(sum(gci.coins_earned), (0)::numeric) AS total_coins_earned_by_influencers
   FROM ((public.game_campaigns gc
     LEFT JOIN public.brands b ON ((gc.brand_id = b.profile_id)))
     LEFT JOIN public.game_campaign_interactions gci ON (((gci.campaign_id = gc.id) AND (gci.success = true))))
  GROUP BY gc.id, gc.campaign_name, gc.campaign_message, gc.campaign_link, gc.cta_text, gc.brand_id, b.company_name, gc.media_url, gc.media_type, gc.total_interactions, gc.successful_interactions;


