--
-- TOC entry 437 (class 1259 OID 54775)
-- Name: pass_it_analytics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.pass_it_analytics AS
 SELECT c.id,
    c.title,
    c.brand_id,
    c.target_passes,
    c.reward_pool,
    c.status,
    c.created_at,
    c.completed_at,
    count(DISTINCT ch.id) AS total_chains,
    count(DISTINCT p.reviewer_id) AS unique_participants,
    COALESCE(sum(ch.current_passes), (0)::bigint) AS total_passes,
    COALESCE(avg(p.rating), (0)::numeric) AS avg_rating,
    count(DISTINCT
        CASE
            WHEN ((p.status)::text = 'completed'::text) THEN p.id
            ELSE NULL::uuid
        END) AS completed_reviews,
        CASE
            WHEN (((c.status)::text = 'completed'::text) AND (c.completed_at IS NOT NULL)) THEN (EXTRACT(epoch FROM (c.completed_at - c.created_at)) / (3600)::numeric)
            ELSE NULL::numeric
        END AS completion_hours,
        CASE
            WHEN (c.target_passes > 0) THEN round((((COALESCE(sum(ch.current_passes), (0)::bigint))::numeric / (c.target_passes)::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS overall_progress_percentage
   FROM ((public.pass_it_campaigns c
     LEFT JOIN public.pass_it_chains ch ON ((c.id = ch.campaign_id)))
     LEFT JOIN public.pass_it_passes p ON (((ch.id = p.chain_id) AND ((p.status)::text = 'completed'::text))))
  GROUP BY c.id, c.title, c.brand_id, c.target_passes, c.reward_pool, c.status, c.created_at, c.completed_at;


