--
-- TOC entry 466 (class 1259 OID 169967)
-- Name: searchable_brand_media; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.searchable_brand_media AS
 SELECT bwm.id,
    bwm.brand_id,
    bwm.media_url,
    bwm.media_type,
    bwm.caption,
    bwm.keywords,
    bwm.thumbnail_url,
    bwm.created_at,
    b.id AS brand_table_id,
    p.username AS brand_username,
    p.avatar_url AS brand_profile_image,
    p.bio AS brand_bio,
    bwm.facebook_ad_id,
    bwm.youtube_ad_id
   FROM ((public.brand_wall_media bwm
     JOIN public.brands b ON ((bwm.brand_id = b.id)))
     JOIN public.profiles p ON ((b.profile_id = p.id)))
  ORDER BY bwm.created_at DESC;


