--
-- TOC entry 465 (class 1259 OID 165394)
-- Name: youtube_ad_metrics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.youtube_ad_metrics (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    youtube_ad_id uuid NOT NULL,
    impressions bigint DEFAULT 0,
    views bigint DEFAULT 0,
    clicks bigint DEFAULT 0,
    cost numeric DEFAULT 0,
    video_views_25 bigint DEFAULT 0,
    video_views_50 bigint DEFAULT 0,
    video_views_75 bigint DEFAULT 0,
    video_views_100 bigint DEFAULT 0,
    ctr numeric GENERATED ALWAYS AS (
CASE
    WHEN (impressions > 0) THEN (((clicks)::numeric / (impressions)::numeric) * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    view_rate numeric GENERATED ALWAYS AS (
CASE
    WHEN (impressions > 0) THEN (((views)::numeric / (impressions)::numeric) * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    avg_cpm numeric GENERATED ALWAYS AS (
CASE
    WHEN (impressions > 0) THEN (cost / ((impressions)::numeric / (1000)::numeric))
    ELSE (0)::numeric
END) STORED,
    avg_cpv numeric GENERATED ALWAYS AS (
CASE
    WHEN (views > 0) THEN (cost / (views)::numeric)
    ELSE (0)::numeric
END) STORED,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL,
    date_start date NOT NULL,
    date_end date NOT NULL
);


